import { type UserDetails } from '../../types';

export const isUserObject = (value?: unknown): value is UserDetails => {
  return (
    typeof value === 'object' &&
    value !== null &&
    'objectType' in value &&
    typeof value.objectType === 'string' &&
    value.objectType === 'user'
  );
};

export const normalizeUserQueues = (
  queues?: Partial<UserDetails['queues']>,
): UserDetails['queues'] => {
  const objects = queues?.objects ?? [];

  return {
    ...(queues ?? {}),
    count: queues?.count ?? objects.length,
    objects,
    total: queues?.total ?? objects.length,
  };
};
