import { Observable } from 'rxjs';
import { axiosInstance } from './axios';

/**
 * A parsed SSE event following the W3C Server-Sent Events specification.
 * @see https://html.spec.whatwg.org/multipage/server-sent-events.html
 */
export interface SseEvent {
  /** Raw data payload (may be multiline). Consumer is responsible for JSON.parse if needed. */
  data: string;
  /** Event type. Defaults to "message" if the server omits the `event:` field. */
  event: string;
  /** Optional event ID. Servers use this for reconnection via `Last-Event-ID`. */
  id?: string;
  /** Optional retry interval in milliseconds (hint from server). */
  retry?: number;
}

export interface SseClientOptions {
  /** Additional headers to send with the request (merged with axios defaults). */
  headers?: Record<string, string>;
  /** URL query parameters. */
  params?: Record<string, string | string[] | boolean | number>;
  /** AbortSignal for external cancellation. Unsubscribing from the Observable also aborts. */
  signal?: AbortSignal;
}

/**
 * Parses a raw SSE text chunk into zero or more SseEvents.
 * Handles both LF (\n) and CRLF (\r\n) line endings per the SSE spec.
 *
 * SSE wire format:
 *   event: <type>\n
 *   data: <payload>\n
 *   data: <continued payload>\n
 *   id: <id>\n
 *   retry: <ms>\n
 *   \n                          ← empty line dispatches the event
 *   : this is a comment\n      ← ignored
 */
function parseSseChunk(
  chunk: string,
  buffer: { data: string[]; event: string; id?: string; retry?: number },
): SseEvent[] {
  const events: SseEvent[] = [];
  // Split on LF or CRLF — handles both Unix and Windows line endings
  const lines = chunk.split(/\r?\n/);

  for (const line of lines) {
    // Empty line = dispatch the buffered event
    if (line === '') {
      if (buffer.data.length > 0 || buffer.event !== 'message') {
        events.push({
          data: buffer.data.join('\n'),
          event: buffer.event,
          ...(buffer.id !== undefined && { id: buffer.id }),
          ...(buffer.retry !== undefined && { retry: buffer.retry }),
        });
      }
      // Reset buffer for next event
      buffer.data = [];
      buffer.event = 'message';
      buffer.id = undefined;
      buffer.retry = undefined;
      continue;
    }

    // Comment line — ignore (keepalive pings, etc.)
    if (line.startsWith(':')) {
      continue;
    }

    // Parse field: value
    const colonIndex = line.indexOf(':');
    let field: string;
    let value: string;

    if (colonIndex === -1) {
      field = line;
      value = '';
    } else {
      field = line.slice(0, colonIndex);
      // Spec: if the character after the colon is a space, skip it
      value = line[colonIndex + 1] === ' ' ? line.slice(colonIndex + 2) : line.slice(colonIndex + 1);
    }

    switch (field) {
      case 'data':
        buffer.data.push(value);
        break;
      case 'event':
        buffer.event = value;
        break;
      case 'id':
        buffer.id = value;
        break;
      case 'retry': {
        const retryMs = parseInt(value, 10);
        if (!isNaN(retryMs)) {
          buffer.retry = retryMs;
        }
        break;
      }
      // Unknown fields are ignored per spec
    }
  }

  return events;
}

/**
 * Creates an RxJS Observable that connects to an SSE endpoint and emits parsed events.
 *
 * Uses the axios instance (with `adapter: 'fetch'` and `responseType: 'stream'`) so all
 * configured defaults are inherited: baseURL, Authorization, cookies (withCredentials),
 * Deviceid, Nextiva-Platform, Accept-Language, etc.
 *
 * The stream is automatically aborted when the Observable is unsubscribed, or when the
 * consumer-provided `signal` fires.
 *
 * @param path - URL path relative to the axios base URL (e.g., `/v2/search/stream`)
 * @param options - Headers, query params, and abort signal
 * @returns Observable that emits SseEvent objects, completes when stream ends, errors on failure
 *
 * @example
 * ```typescript
 * const abort = new AbortController();
 * const stream$ = createSseStream('/v2/search/stream', {
 *   params: { q: 'Robert', pageSize: 5 },
 *   signal: abort.signal,
 * });
 *
 * const subscription = stream$.subscribe({
 *   next: (event) => {
 *     const payload = JSON.parse(event.data);
 *     if (event.event === 'results') handleResults(payload);
 *     if (event.event === 'done') handleDone(payload);
 *   },
 *   error: (err) => console.error('Stream failed', err),
 *   complete: () => console.log('Stream ended'),
 * });
 *
 * // Cancel on query change:
 * abort.abort();
 * // Or unsubscribe (also aborts):
 * subscription.unsubscribe();
 * ```
 */
export function createSseStream(path: string, options: SseClientOptions = {}): Observable<SseEvent> {
  return new Observable<SseEvent>((subscriber) => {
    const internalAbort = new AbortController();

    // Link external signal to internal abort, keeping a reference for cleanup
    let externalAbortHandler: (() => void) | undefined;
    if (options.signal) {
      if (options.signal.aborted) {
        subscriber.complete();
        return;
      }
      externalAbortHandler = () => {
        internalAbort.abort();
      };
      options.signal.addEventListener('abort', externalAbortHandler, { once: true });
    }

    const run = async () => {
      // Use axios with fetch adapter to get a ReadableStream.
      // This inherits all axios config: baseURL, headers, withCredentials, interceptors.
      const response = await axiosInstance<ReadableStream<Uint8Array>>(path, {
        adapter: 'fetch',
        headers: {
          Accept: 'text/event-stream',
          ...options.headers,
        },
        method: 'GET',
        params: options.params,
        responseType: 'stream',
        signal: internalAbort.signal,
      });

      const body = response.data as unknown;
      if (!body || typeof (body as { getReader?: unknown }).getReader !== 'function') {
        throw new Error('SSE response has no readable stream body');
      }

      const reader = (body as ReadableStream<Uint8Array>).getReader();
      const decoder = new TextDecoder();

      // Buffer for incomplete lines across chunks
      let textBuffer = '';

      // State for the current SSE event being parsed
      const eventBuffer = {
        data: [] as string[],
        event: 'message',
        id: undefined as string | undefined,
        retry: undefined as number | undefined,
      };

      try {
        for (;;) {
          const { done, value } = await reader.read();

          if (done) {
            // Flush the decoder for any remaining multi-byte sequence
            textBuffer += decoder.decode();

            // Flush any remaining text + buffered event
            // Append a newline so the parser can dispatch any trailing event
            if (textBuffer.length > 0 || eventBuffer.data.length > 0) {
              const finalChunk = textBuffer + '\n';
              const events = parseSseChunk(finalChunk, eventBuffer);
              for (const event of events) {
                subscriber.next(event);
              }
            }

            subscriber.complete();
            return;
          }

          textBuffer += decoder.decode(value, { stream: true });

          // Process only complete SSE frames — an SSE event is dispatched on a
          // blank line (two consecutive line terminators: \n\n or \r\n\r\n).
          // Flushing on the last *single* newline would split a frame mid-way
          // when a TCP chunk boundary falls between the `event:` and `data:`
          // lines, causing the parser to dispatch an incomplete event.
          let boundaryEnd = -1;
          const lfBoundary = textBuffer.lastIndexOf('\n\n');
          const crlfBoundary = textBuffer.lastIndexOf('\r\n\r\n');

          if (lfBoundary !== -1) {
            boundaryEnd = lfBoundary + 2;
          }
          if (crlfBoundary !== -1) {
            const crlfEnd = crlfBoundary + 4;
            if (crlfEnd > boundaryEnd) {
              boundaryEnd = crlfEnd;
            }
          }

          if (boundaryEnd === -1) {
            continue;
          }

          const completePart = textBuffer.slice(0, boundaryEnd);
          textBuffer = textBuffer.slice(boundaryEnd);

          const events = parseSseChunk(completePart, eventBuffer);
          for (const event of events) {
            subscriber.next(event);
          }
        }
      } finally {
        reader.releaseLock();
      }
    };

    run().catch((error: unknown) => {
      // AbortError means the stream was intentionally cancelled — complete, don't error
      if (error instanceof DOMException && error.name === 'AbortError') {
        subscriber.complete();
        return;
      }
      // Axios wraps errors — check for abort in the cause
      if (
        error instanceof Error &&
        'code' in error &&
        (error as { code?: string }).code === 'ERR_CANCELED'
      ) {
        subscriber.complete();
        return;
      }
      subscriber.error(error);
    });

    // Teardown: abort the stream and clean up the external signal listener
    return () => {
      internalAbort.abort();
      if (externalAbortHandler && options.signal) {
        options.signal.removeEventListener('abort', externalAbortHandler);
      }
    };
  });
}
