import { dependencyInjectionContainer } from '../../internal';
import { type AudioQualityService } from '../../services';
import { type QualityWarnings } from '../../types';

const DEFAULT_WARNINGS = {
  ['high-jitter']: false,
  ['high-packet-loss']: false,
  ['high-rtt']: false,
  ['low-mos']: false,
};

/**
 * Handles the warnings related to the call quality described by the
 * `WebRTC` peer connection and report them to the BE service.
 *
 * Exposes public methods to handle the Twilio warning subscription API.
 */
class TwilioStatsCompilation {
  private warnings: typeof DEFAULT_WARNINGS;

  private audioQualityServiceInstance: AudioQualityService;

  private logger = dependencyInjectionContainer.resolve('loggerService');

  constructor() {
    this.audioQualityServiceInstance = dependencyInjectionContainer.resolve('audioQualityService');
    this.warnings = { ...DEFAULT_WARNINGS };
  }

  /**
   * Report to the `TwilioStatsCompilation` that a new warning has been raised
   * @param warningName one of `high-jitter`, `high-packet-loss`, `high-rtt`, `low-mos`
   */
  public handleWebRTCWarning(warningName: string) {
    if (
      Object.keys(this.warnings).includes(warningName) &&
      !this.warnings[warningName as keyof typeof this.warnings]
    ) {
      this.warnings[warningName as keyof typeof this.warnings] = true;
      this.sendWarnings().catch(() => {});
    }
  }

  /**
   * Report to the `TwilioStatsCompilation` that a previously reported warning has been cleared
   * @param warningName one of `high-jitter`, `high-packet-loss`, `high-rtt`, `low-mos`
   */
  public handleWebRTCWarningCleared(warningName: string) {
    if (
      Object.keys(this.warnings).includes(warningName) &&
      this.warnings[warningName as keyof typeof this.warnings]
    ) {
      this.warnings[warningName as keyof typeof this.warnings] = false;
      this.sendWarnings().catch(() => {});
    }
  }

  private async sendWarnings() {
    const warningMessage: QualityWarnings = {
      highJitter: this.warnings['high-jitter'],
      highPacketLoss: this.warnings['high-packet-loss'],
      highRtt: this.warnings['high-rtt'],
      lowMos: this.warnings['low-mos'],
    };

    try {
      await this.audioQualityServiceInstance.sendCurrentWarnings(warningMessage);
    } catch (error) {
      this.logger.error('TwilioStatsCompilation - sendWarnings - error', error);
    }
  }
}

export { TwilioStatsCompilation };
