import { ofType, queryClient } from '../../utilities';
import { InternalEvents } from '../../models';
import { dependencyInjectionContainer, type InjectionContainer } from '../dependencyInjectionContainer';
import type { EventsService, LoggerService } from '../../services';
import {
  type AIEmployeesQueryData,
  getAIEmployeesQueryOptions,
} from '../../utilities/queries/getAIEmployeesQueryOptions';

export class AIEmployeeService {
  protected eventsService: EventsService;
  protected logger: LoggerService;

  constructor({
    eventsService,
    loggerService,
  }: Pick<InjectionContainer, 'eventsService' | 'loggerService'>) {
    loggerService.trace('AIEmployeeService - constructor');

    this.eventsService = eventsService;
    this.logger = loggerService;

    this.handleAiEmployeeUpdatedNotification();
  }

  private handleAiEmployeeUpdatedNotification() {
    this.eventsService.internalEvents$
      .pipe(ofType(InternalEvents.AiEmployeeUpdatedNotification))
      .subscribe((event) => {
        // The type declares `aiemployee` as non-nullable, but the backend can
        // deliver a malformed/partial payload at runtime. Guard defensively so
        // an empty payload no-ops instead of crashing the RxJS observer.
        // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
        const incoming = event.data?.aiemployee;

        // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
        if (!incoming?.aiemployeeId) {
          this.logger.warn(
            'AIEmployeeService - AiEmployeeUpdatedNotification - missing aiemployee payload',
            // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
            { hasAiemployee: !!event.data?.aiemployee, hasData: !!event.data },
          );
          return;
        }

        const queryKey = getAIEmployeesQueryOptions().queryKey;

        this.logger.debug('AIEmployeeService - AiEmployeeUpdatedNotification', {
          aiemployeeId: incoming.aiemployeeId,
        });

        queryClient.setQueryData<AIEmployeesQueryData>(queryKey, (current) => {
          const employees = current?.employees ?? [];
          const idx = employees.findIndex((e) => e.aiemployeeId === incoming.aiemployeeId);

          if (incoming.deletedAt) {
            return {
              cursor: current?.cursor,
              employees: idx >= 0 ? employees.filter((_, i) => i !== idx) : employees,
            };
          }

          const next = [...employees];
          if (idx >= 0) {
            next[idx] = { ...next[idx], ...incoming };
          } else {
            next.push(incoming);
          }
          return { cursor: current?.cursor, employees: next };
        });

        // Persist the WS-driven cache write. The default per-query persister only
        // fires for queryFn results, so direct setQueryData writes need an explicit
        // call (mirrors conversation.ts schedulePersistQuery).
        const queryPersister = dependencyInjectionContainer
          .resolve('persisterClient')
          .getQueryPersister();
        queryPersister
          ?.persistQueryByKey(queryKey, queryClient)
          .catch((error: unknown) => {
            this.logger.debug('AIEmployeeService - persist error', error);
          });
      });
  }
}
