/**
 * @deprecated Use `LoggerService`
 */
export const Logger = {
  error(...args: Parameters<typeof console.error>): void {
    if (!this.isTracing()) {
      return;
    }
    // eslint-disable-next-line no-console
    console.error(...args);
  },
  force(...args: Parameters<typeof console.log>): void {
    // eslint-disable-next-line no-console
    console.log(...args);
  },
  group(...args: Parameters<typeof console.group>): void {
    if (!this.isTracing()) {
      return;
    }

    // eslint-disable-next-line no-console, @typescript-eslint/no-unsafe-argument
    console.group(...args);
  },
  groupEnd(...args: Parameters<typeof console.groupEnd>): void {
    if (!this.isTracing()) {
      return;
    }

    // eslint-disable-next-line no-console
    console.groupEnd(...args);
  },
  info(...args: Parameters<typeof console.info>): void {
    if (!this.isTracing()) {
      return;
    }
    // eslint-disable-next-line no-console
    console.info(...args);
  },
  isTracing(): boolean {
    return this.trace;
  },
  log(...args: Parameters<typeof console.log>): void {
    if (!this.isTracing()) {
      return;
    }

    // eslint-disable-next-line no-console
    console.log(...args);
  },
  setTracing(trace: boolean): void {
    this.trace = trace;
  },
  trace: true,
  warn(...args: Parameters<typeof console.warn>): void {
    if (!this.isTracing()) {
      return;
    }

    // eslint-disable-next-line no-console
    console.warn(...args);
  },
};
