import type { FetchQueryOptions } from '@tanstack/query-core';
import type { TicketDetailQueryData } from '../../types';
import { Logger } from '../logger';

export function getTicketDetailQueryOptions({
  ticketId,
}: {
  ticketId: string;
}) {
  return {
    queryFn: ({ client, queryKey }) => {
      const queryData = client.getQueryData<TicketDetailQueryData>(queryKey);

      Logger.log('getTicketDetailQueryOptions', 'Query invoked', {
        hasData: !!queryData?.ticket,
        ticketId,
      });

      return queryData ?? { ticket: null };
    },
    queryKey: ['tickets', 'detail', ticketId],
  } satisfies FetchQueryOptions<TicketDetailQueryData>;
}
