import { type AgentAssistConversation } from '../types/agentAssistConversation';
import { type TextDecoration } from '../types/textDecoration';
import { s360AxiosClient } from '../utilities/s360AxiosClient';
import { type SuggestionResponse } from '../types/suggestionResponse';
import { type AgentConversation } from '../types/conversation';
import { type TextDecorationResponse } from '../types/textDecorationResponse';
import type { InjectionContainer } from '../internal';

export class AgentAssistService {
  private logger: InjectionContainer['loggerService'];

  constructor({ loggerService }: Pick<InjectionContainer, 'loggerService'>) {
    this.logger = loggerService;

    this.logger.trace('AgentAssistService - constructor');
  }

  // ============================================
  // API Methods
  // ============================================

  /**
   * Posts a conversation to the Agent Assist service.
   *
   * @param conversation - The conversation to post.
   * @returns A Promise that resolves to the response from the server.
   */
  public async createConversation(conversation: AgentAssistConversation): Promise<void> {
    await s360AxiosClient.post(
      '/agent-assist-orchestration-service/private/v1/conversation',
      conversation,
    );
    return;
  }

  /**
   * Updates a conversation in the Agent Assist service.
   *
   * @param conversation - The conversation to update.
   * @returns A Promise that resolves to the response from the server.
   */
  public async updateConversation(conversation: AgentAssistConversation): Promise<void> {
    await s360AxiosClient.put(
      '/agent-assist-orchestration-service/private/v1/conversation',
      conversation,
    );
    return;
  }

  /**
   * Gets a conversation from the Agent Assist service.
   *
   * @param conversationId - The ID of the conversation to get.
   * @param tenantId - The ID of the tenant.
   * @returns A Promise that resolves to the response from the server.
   */
  public async getConversation(
    conversationId: string,
    tenantId: string,
  ): Promise<AgentConversation> {
    const response = await s360AxiosClient.get<AgentConversation>(
      `/agent-assist-orchestration-service/private/v1/conversation?tenant_id=${tenantId}&conversaton_uuid=${conversationId}`,
    );

    return response.data;
  }

  /**
   * Gets a suggestion from the Agent Assist service.
   *
   * @param conversation - The conversation to get a suggestion for.
   * @param version - The version is to target api version. Defaults to 'v1'.
   * @returns A Promise that resolves to the response from the server.
   */
  public async getSuggestion(conversation: AgentAssistConversation, version: "v1" | "v2" = 'v1'): Promise<SuggestionResponse> {
    const response = await s360AxiosClient.post<SuggestionResponse>(
      `/agent-assist-orchestration-service/private/${version}/suggest-response`,
      conversation,
    );
    return response.data;
  }

  /**
   * Decorates text using the Agent Assist service.
   *
   * @param options - The options to use when decorating the text.
   * @returns A Promise that resolves to the response from the server.
   */
  public async decorateText(options: TextDecoration): Promise<TextDecorationResponse> {
    const response = await s360AxiosClient.post<TextDecorationResponse>(
      '/agent-assist-orchestration-service/private/v1/text-manipulation',
      options,
    );
    return response.data;
  }
}
