import type { Observable } from 'rxjs';
import type { InjectionContainer } from '../internal';
import type {
  AgenticSearchOptions,
  AttentionResponse,
  Contact,
  NCXObjectType,
  QuickSearchPayload,
  QuickSearchResponseBody,
  QuickSearchUsersAndContactsPayload,
  RealTimeUser,
  RecentSearchesResponse,
  SearchFeedbackPayload,
  SearchFeedbackResponse,
  SearchOptions,
  SearchResponseBody,
  SearchStreamOptions,
} from '../types';
import { axiosInstance, createSseStream, type SseEvent } from '../utilities';
import { type LoggerService } from './logger';
import type { StateService } from './state';

export const isNCXObjectTypeContact = (value: NCXObjectType): value is Contact => {
  const castedValue = value as Record<string, unknown>;
  return Boolean(castedValue['contactId']) && castedValue['objectType'] === 'contact';
};

const DEFAULT_API_LIMIT = 10;
const MAX_RESULTS = 10;

export class SearchService {
  private stateService: StateService;
  private logger: LoggerService;

  constructor({
    loggerService,
    stateService,
  }: Pick<InjectionContainer, 'stateService' | 'loggerService'>) {
    this.stateService = stateService;
    this.logger = loggerService;
  }
  /**
   * Performs a search based on the provided search options.
   *
   * @param {SearchOptions} options - The search options.
   * @returns {Promise<SearchResponseBody>} - A promise that resolves to the search response body.
   */
  async search(options: SearchOptions) {
    this.logger.debug('SearchService - search - invoked with payload:', options);
    const params = this.transformSearchParams(options);

    const response = await axiosInstance.get<SearchResponseBody>('data/api/search', {
      params,
      paramsSerializer: {
        indexes: null,
      },
    });
    return response.data;
  }

  private transformSearchParams(options: SearchOptions) {
    const { orderBy, ...rest } = options;

    return {
      ...rest,
      orderBy: orderBy && `${orderBy.property} ${orderBy.order}`,
    };
  }

  /**
   * Retrieves search suggestions.
   * @returns A promise that resolves to the search suggestions.
   */
  async suggestions() {
    this.logger.trace('SearchService - suggestions');

    const response = await axiosInstance.get<SearchResponseBody>('data/api/search/suggestions');

    return response.data;
  }

  async quickSearch(params: QuickSearchPayload) {
    this.logger.debug('SearchService - quickSearch - invoked with payload:', params);

    const response = await axiosInstance.get<QuickSearchResponseBody>('data/api/quicksearch', {
      params,
      paramsSerializer: {
        indexes: null,
      },
    });

    return response.data;
  }

  /**
   * Uses SearchService to search for contacts and filters users from local memory to
   * deliver a combined list of contacts and users matching the provided filter
   *
   * @param payload
   * @param payload.apiLimit - The maximum number of Contact rows to return from the Search API.
   * @param payload.maxSize - The maximum number of combined results to return. The result may have less rows than the max size, depending on the search criteria and API limit.
   * @param payload.q - Query string to search for contacts and filter users.
   * @returns A combined list of contacts and users matching the provided query.
   */
  async quickSearchUsersAndContacts(payload: QuickSearchUsersAndContactsPayload) {
    this.logger.debug(
      'SearchService - quickSearchUsersAndContacts - invoked with payload:',
      payload,
    );

    const searchResponse = await this.search({
      pageSize: payload.apiLimit ?? DEFAULT_API_LIMIT,
      q: payload.q,
      start: 0,
      type: 'contact',
    });

    const searchTerm = payload.q.toLowerCase();

    const contacts = (searchResponse.objects?.filter(
      (item) =>
        isNCXObjectTypeContact(item) &&
        ((Boolean(item.name) && item.name.toLowerCase().includes(searchTerm)) ||
          (Boolean(item.firstName) && item.firstName.toLowerCase().includes(searchTerm)) ||
          (Boolean(item.lastName) && item.lastName.toLowerCase().includes(searchTerm)) ||
          Boolean(
            item.connections?.some(
              (connection) =>
                Boolean(connection.value) && connection.value.toLowerCase().includes(searchTerm),
            ),
          ) ||
          Boolean(item.phone?.includes(searchTerm)) ||
          Boolean(item.mobile?.includes(searchTerm)) ||
          Boolean(item.email?.toLowerCase().includes(searchTerm))),
    ) ?? []) as Contact[];

    let users: RealTimeUser[];
    try {
      users =
        this.stateService.getUsers()?.filter((user) => {
          const validUser =
            !user.hideInCompanyDirectory && (user.dnis || user.extension || user.username);
          if (!validUser) {
            return false;
          }

          const containsSearchTerm =
            (Boolean(user.name) && user.name.toLowerCase().includes(searchTerm)) ||
            (Boolean(user.firstName) && user.firstName.toLowerCase().includes(searchTerm)) ||
            (Boolean(user.lastName) && user.lastName.toLowerCase().includes(searchTerm)) ||
            (Boolean(user.dnis) && user.dnis.toLowerCase().includes(searchTerm)) ||
            (Boolean(user.extension) && user.extension.toLowerCase().includes(searchTerm)) ||
            (Boolean(user.username) && user.username.toLowerCase().includes(searchTerm));

          return containsSearchTerm;
        }) ?? [];
    } catch (error: unknown) {
      users = [];
    }

    return [...contacts, ...users]
      .sort((a: Partial<RealTimeUser | Contact>, b: Partial<RealTimeUser | Contact>) => {
        const aCompare = a.name?.length ? a.name : (a.firstName ?? '') + (a.lastName ?? '');
        const bCompare = b.name?.length ? b.name : (b.firstName ?? '') + (b.lastName ?? '');
        return aCompare.localeCompare(bCompare);
      })
      .slice(0, payload.maxSize ?? MAX_RESULTS);
  }

  /**
   * Executes agentic search constrained to a single collection.
   *
   * @param params - Request options
   * @param params.q - Query string for lexical/semantic search
   * @param params.alpha - Optional blend factor for semantic vs lexical scoring (inclusive 0-1)
   * @param params.pageSize - Number of results to return per page
   * @param params.start - Pagination offset
   * @param params.type - The collection to search within
   * @returns SearchResponseBody with results for the specified collection
   */
  async agenticSearch(params: AgenticSearchOptions) {
    this.logger.debug('SearchService - agenticSearch - invoked with payload:', params);

    const response = await axiosInstance.get<SearchResponseBody>(
      'global-search-poc/api/v1/search',
      {
        params,
        paramsSerializer: {
          indexes: null,
        },
      },
    );
    return response.data;
  }

  // ============================================
  // V2 Search (Nexar Global Search)
  // ============================================

  private static readonly V2_BASE = 'cxfabric/api/v2/search';

  /**
   * Opens an SSE stream for typed-query search.
   * Returns an RxJS Observable that emits raw SSE events.
   * Consumer is responsible for parsing `event.data` as JSON.
   *
   * @param options - Search query and options
   * @param signal - Optional AbortSignal for cancellation
   * @returns Observable of SSE events (results, done, recent_searches, error)
   */
  searchStream(options: SearchStreamOptions, signal?: AbortSignal): Observable<SseEvent> {
    this.logger.info('SearchService - searchStream', options);

    const {
      alpha = 0.5,
      pageSize = 5,
      q,
      save = true,
      type: types,
    } = options;

    const params: Record<string, string | string[] | boolean | number> = {
      alpha,
      pageSize,
      q,
      save,
    };

    if (types && types.length > 0) {
      params['type[]'] = types;
    }

    return createSseStream(`${SearchService.V2_BASE}/stream`, {
      params,
      signal,
    });
  }

  /**
   * Fetches "Needs Attention" items for the default dropdown (empty query).
   */
  async fetchAttention(): Promise<AttentionResponse> {
    this.logger.trace('SearchService - fetchAttention');

    const response = await axiosInstance.get<AttentionResponse>(
      `${SearchService.V2_BASE}/attention`,
    );
    return response.data;
  }

  /**
   * Fetches recent searches for the current user.
   */
  async fetchRecentSearches(): Promise<RecentSearchesResponse> {
    this.logger.trace('SearchService - fetchRecentSearches');

    const response = await axiosInstance.get<RecentSearchesResponse>(
      `${SearchService.V2_BASE}/recent`,
    );
    return response.data;
  }

  /**
   * Clears all recent searches for the current user.
   */
  async clearRecentSearches(): Promise<void> {
    this.logger.trace('SearchService - clearRecentSearches');

    await axiosInstance.delete(`${SearchService.V2_BASE}/recent`);
  }

  /**
   * Submits thumbs up/down feedback for a search session.
   */
  async submitSearchFeedback(payload: SearchFeedbackPayload): Promise<SearchFeedbackResponse> {
    this.logger.debug('SearchService - submitSearchFeedback', payload);

    const response = await axiosInstance.post<SearchFeedbackResponse>(
      `${SearchService.V2_BASE}/feedback`,
      payload,
    );
    return response.data;
  }
}
