import type { FetchQueryOptions } from '@tanstack/query-core';
import type { TicketSearchFilters, TicketsQueryData } from '../../types';
import { Logger } from '../logger';

export function getTicketsQueryOptions(filters?: TicketSearchFilters) {
  return {
    queryFn: ({ client, queryKey }) => {
      const queryData = client.getQueryData<TicketsQueryData>(queryKey);

      Logger.log('getTicketsQueryOptions', 'Query invoked', {
        hasData: !!queryData,
        ticketCount: queryData?.tickets.length ?? 0,
      });

      // Return cached data if available, otherwise return empty state
      return queryData ?? {
        hasMore: true,
        nextCursor: null,
        tickets: [],
      };
    },
    queryKey: ['tickets', 'search', filters ?? {}] as const,
  } satisfies FetchQueryOptions<TicketsQueryData>;
}
