import type { AIEmployee, AIEmployeeSummaryResponse } from '../../types';
import { axiosInstance } from '../axios';
import { type FetchQueryOptions } from '@tanstack/query-core';
import { dependencyInjectionContainer } from '../../internal';

export interface AIEmployeesQueryData {
  cursor?: number;
  employees: AIEmployee[];
}

export function getAIEmployeesQueryOptions() {
  return {
    queryFn: async ({ client, queryKey }) => {
      const logger = dependencyInjectionContainer.resolve('loggerService');
      const rawCachedData = client.getQueryData(queryKey);
      // Tolerate the legacy cache shape (a plain AIEmployee[] persisted before the
      // summary-endpoint migration). Treat it as employees with no cursor.
      const queryData: AIEmployeesQueryData | undefined = Array.isArray(rawCachedData)
        ? { cursor: undefined, employees: rawCachedData as AIEmployee[] }
        : (rawCachedData as AIEmployeesQueryData | undefined);
      const cursor = queryData?.cursor;

      logger.debug('getAIEmployeesQueryOptions - requesting', {
        cursor,
        hasQueryData: queryData !== undefined,
      });

      const response = await axiosInstance.get<AIEmployeeSummaryResponse>(
        '/data/api/types/aiemployee/summary',
        {
          params: cursor === undefined ? undefined : { cursor },
        },
      );

      logger.debug(
        `getAIEmployeesQueryOptions - request resolved with status [${response.status}]`,
        response.data,
      );

      // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- backend may omit objects when empty
      const responseObjects = response.data.objects ?? [];
      const nextCursor = response.data.cursor;

      // First load — seed the cache directly from the response.
      if (!queryData) {
        logger.info('getAIEmployeesQueryOptions - first load, seeding cache');
        return {
          cursor: nextCursor,
          employees: responseObjects.filter((emp) => !emp.deletedAt),
        };
      }

      // Incremental sync — the response is primarily an ack; updates flow via
      // AiEmployeeUpdatedNotification websocket messages handled by AIEmployeeService.
      // If the BE happens to include objects in the response, merge them defensively.
      if (responseObjects.length === 0) {
        return { cursor: nextCursor, employees: queryData.employees };
      }

      logger.debug('getAIEmployeesQueryOptions - merging incremental response objects');

      const merged = queryData.employees.reduce<AIEmployee[]>((acc, cachedEmployee) => {
        const updatedEmployee = responseObjects.find(
          (emp) => emp.aiemployeeId === cachedEmployee.aiemployeeId,
        );

        if (updatedEmployee) {
          if (updatedEmployee.deletedAt) {
            return acc;
          }
          acc.push(updatedEmployee);
          return acc;
        }

        acc.push(cachedEmployee);
        return acc;
      }, []);

      responseObjects.forEach((emp) => {
        if (
          !queryData.employees.some((cached) => cached.aiemployeeId === emp.aiemployeeId) &&
          !emp.deletedAt
        ) {
          merged.push(emp);
        }
      });

      return { cursor: nextCursor, employees: merged };
    },
    queryKey: ['static', 'aiemployees'],
  } satisfies FetchQueryOptions<AIEmployeesQueryData>;
}
