import type {
  AudioQualityNumericStat,
  AudioQualityStatsSample,
  IRTCStatsGetter,
  ITwilioRTCStatsGetter,
  ParsedRTCStats,
  ParsedTwilioRTCStats,
  QualityWarnings,
} from '../../types/rtc-stats';
import { parseRtcPeerConnectionStats, parseTwilioRTCReportStats } from './parser';
import { calculateQualityMetrics, calculateTwilioQualityMetrics } from './quality';
import { type AudioQualityService, type EventsService } from '../../services';
import { equalSet } from '../equal-set';
import { ExternalEvents } from '../../models';
import { type BaseDatadogService, dependencyInjectionContainer } from '../../internal';

interface CallQualityStats {
  qualityMetrics: AudioQualityStatsSample | undefined;
  stats: ParsedRTCStats | ParsedTwilioRTCStats | undefined;
}

interface WarningValue {
  value: number;
  warningName: string;
}

type WarningStatThreshold = Partial<Record<AudioQualityNumericStat, WarningValue>>;

const WARNING_NAMES = {
  QualitySample: 'sample',
  QualityWarningCleared: 'warning-cleared',
  QualityWarningHighJitter: 'high-jitter',
  QualityWarningHighPacketLoss: 'high-packet-loss',
  QualityWarningHighRTT: 'high-rtt',
  QualityWarningLowMos: 'low-mos',
} as const;

const WARNING_CONFIG: {
  clearAlarmWhen: number;
  interval: number;
  max: WarningStatThreshold;
  min: WarningStatThreshold;
  raiseAlarmWhen: number;
} = {
  clearAlarmWhen: 1,
  interval: 1000,
  max: {
    jitter: { value: 30, warningName: WARNING_NAMES.QualityWarningHighJitter },
    packetsLostFraction: { value: 1, warningName: WARNING_NAMES.QualityWarningHighPacketLoss },
    rtt: { value: 400, warningName: WARNING_NAMES.QualityWarningHighRTT },
  },
  min: {
    mos: { value: 3, warningName: WARNING_NAMES.QualityWarningLowMos },
  },
  raiseAlarmWhen: 3,
} as const;

/**
 * Handles monitoring the quality of an ongoing call by setting an interval to collect
 * and evaluate the RTC Peer connection's stats.
 *
 * Exposes public methods to start or stop the interval.
 */
class RTCCallQualityMonitor {
  private previousRTCStatsParsed: ParsedRTCStats | undefined;
  private previousTwilioRTCStatsParsed: ParsedTwilioRTCStats | undefined;
  private qualityMetricsInterval: ReturnType<typeof setInterval> | undefined;
  private datadogInterval: ReturnType<typeof setInterval> | undefined;
  private initialDelayTimeout: ReturnType<typeof setTimeout> | undefined;
  private rtcStatsGetter: IRTCStatsGetter | undefined;
  private twilioRTCStatsGetter: ITwilioRTCStatsGetter | undefined;
  private samplePool: AudioQualityStatsSample[];
  private audioQualityServiceInstance: AudioQualityService;
  private eventsService: EventsService;
  private activeAlarms: Set<string>;
  private datadogService: BaseDatadogService | null;
  private logger = dependencyInjectionContainer.resolve('loggerService');

  constructor(rtcStatsGetter?: IRTCStatsGetter, twilioRTCStatsGetter?: ITwilioRTCStatsGetter) {
    this.rtcStatsGetter = rtcStatsGetter;
    this.twilioRTCStatsGetter = twilioRTCStatsGetter;
    this.samplePool = [];
    this.eventsService = dependencyInjectionContainer.resolve('eventsService');
    this.audioQualityServiceInstance = dependencyInjectionContainer.resolve('audioQualityService');
    this.datadogService = dependencyInjectionContainer.resolve('datadogService');
    this.activeAlarms = new Set();
  }

  /**
   * Starts the quality metrics interval, populate the sample pool
   * and evaluate the quality of the call
   *
   * Includes an initial delay to allow the connection to stabilize before
   * starting aggressive stats collection, reducing noise from transitional states.
   */
  public startQualityMetricsMonitor(callId: string) {
    this.previousTwilioRTCStatsParsed = undefined;
    this.previousRTCStatsParsed = undefined;

    // Initial delay to let connection stabilize before starting stats collection
    const INITIAL_DELAY = 2000; // Wait 2 seconds before first collection
    const NORMAL_INTERVAL = WARNING_CONFIG.interval; // Then collect every 1 second

    this.initialDelayTimeout = setTimeout(() => {
      this.qualityMetricsInterval = setInterval(() => {
      // Validate that we have a stats getter
      if (!this.rtcStatsGetter && !this.twilioRTCStatsGetter) {
        this.stopMonitor();
        this.logger.error('RTCCallQualityMonitor - No StatsGetter provided');
        return;
      }

      // Check connection state to ensure it's appropriate for stats collection
      if (this.rtcStatsGetter) {
        const connectionState = this.rtcStatsGetter.connectionState;

        // Stop monitoring if connection is closed or failed
        if (connectionState === 'closed' || connectionState === 'failed') {
          this.stopMonitor();
          this.logger.debug(
            `RTCCallQualityMonitor - Stopping monitor, connection state: ${connectionState}`,
          );
          return;
        }

        // Skip collection during transitional states to avoid collecting unreliable stats
        if (connectionState === 'new' || connectionState === 'connecting') {
          this.logger.debug(
            `RTCCallQualityMonitor - Skipping stats collection during connection setup, state: ${connectionState}`,
          );
          return;
        }

        // Only proceed if connected
        if (connectionState !== 'connected') {
          this.logger.debug(
            `RTCCallQualityMonitor - Skipping stats collection, state: ${connectionState}`,
          );
          return;
        }
      }

      let qualityMetricsPromise: Promise<CallQualityStats>;
      // Choose method to generate stats based on the getter provided
      if (this.twilioRTCStatsGetter) {
        qualityMetricsPromise = this.generateTwilioCallQualityStats();
      } else if (this.rtcStatsGetter) {
        qualityMetricsPromise = this.generateCallQualityStats();
      } else {
        this.stopMonitor();
        this.logger.error('RTCCallQualityMonitor - No StatsGetter provided');
        return;
      }
      // Populate sample pool and evaluate quality
      qualityMetricsPromise
        .then(async (callQualityStats) => {
          if (callQualityStats.qualityMetrics) {
            this.samplePool.unshift(callQualityStats.qualityMetrics);
            this.samplePool = this.samplePool.slice(0, 5);
            // this.eventsServiceInstance.emitExternal(
            //   WARNING_NAMES.QualitySample,
            //   callQualityStats.qualityMetrics,
            // );
            // Logger.log('QualityMonitor - latest sample:', callQualityStats.qualityMetrics);
          }

          if (this.samplePool.length === 5) {
            await this.verifySampleQuality().then(() => {});
          }
        })
        .catch((error: unknown) => {
          this.logger.error('RTCCallQualityMonitor - error in quality metrics monitor', error);
        });
      }, NORMAL_INTERVAL);

      this.datadogInterval = setInterval(() => {
        const sample = this.samplePool[0];

        if (sample) {
          this.datadogService?.addAction('AudioQualitySample', { ...sample, callId });
        }
      }, 15_000);

      this.logger.debug(
        `RTCCallQualityMonitor - Started quality metrics collection after ${INITIAL_DELAY}ms stabilization delay`,
      );
    }, INITIAL_DELAY);
  }

  /**
   * Stops the quality metrics interval if running and discards the collected samples
   */
  public stopMonitor(): void {
    this.activeAlarms.clear();
    this.samplePool = [];
    if (this.initialDelayTimeout !== undefined) {
      clearTimeout(this.initialDelayTimeout);
    }
    if (this.qualityMetricsInterval !== undefined) {
      clearInterval(this.qualityMetricsInterval);
    }
    if (this.datadogInterval !== undefined) {
      clearInterval(this.datadogInterval);
    }
    const warnings: QualityWarnings = {
      highJitter: false,
      highPacketLoss: false,
      highRtt: false,
      lowMos: false,
    };
    this.eventsService.emitExternal(ExternalEvents.QualityWarningsChangedNotification, warnings);
  }

  private async generateCallQualityStats(): Promise<CallQualityStats> {
    const callQualityStats: CallQualityStats = {
      qualityMetrics: undefined,
      stats: undefined,
    };
    if (!this.rtcStatsGetter) {
      return callQualityStats;
    }
    try {
      callQualityStats.stats = await parseRtcPeerConnectionStats(this.rtcStatsGetter);

      if (callQualityStats.stats && !!this.previousRTCStatsParsed) {
        callQualityStats.qualityMetrics = calculateQualityMetrics(
          callQualityStats.stats,
          this.previousRTCStatsParsed,
        );
      }
      // Update previousRTCStatsParsed after quality metrics
      this.previousRTCStatsParsed = callQualityStats.stats;

      return callQualityStats;
    } catch (error) {
      this.logger.error('RTCCallQualityMonitor caught:', error);
      return callQualityStats;
    }
  }

  private async generateTwilioCallQualityStats(): Promise<CallQualityStats> {
    const callQualityStats: CallQualityStats = {
      qualityMetrics: undefined,
      stats: undefined,
    };
    if (!this.twilioRTCStatsGetter) {
      return callQualityStats;
    }
    try {
      callQualityStats.stats = await parseTwilioRTCReportStats(this.twilioRTCStatsGetter);

      if (callQualityStats.stats && !!this.previousTwilioRTCStatsParsed) {
        callQualityStats.qualityMetrics = calculateTwilioQualityMetrics(
          callQualityStats.stats,
          this.previousTwilioRTCStatsParsed,
        );
      }
      // Update previousRTCStatsParsed after quality metrics
      this.previousTwilioRTCStatsParsed = callQualityStats.stats;

      return callQualityStats;
    } catch (error) {
      this.logger.error('RTCCallQualityMonitor caught:', error);
      return callQualityStats;
    }
  }

  private async verifySampleQuality() {
    // Initialize warning count and copy sample pool
    const warningCount: Partial<Record<AudioQualityNumericStat, number>> = {
      jitter: 0,
      mos: 0,
      packetsLostFraction: 0,
      rtt: 0,
    };
    const currentSamplePool = this.samplePool.slice();

    // Compare stats of each sample against warning max and min values
    currentSamplePool.forEach((sample) => {
      for (const stat of Object.keys(WARNING_CONFIG.max) as AudioQualityNumericStat[]) {
        if (sample[stat] >= WARNING_CONFIG.max[stat]!.value) {
          this.logger.warn(
            `RTCQualityMonitor warning: '${stat}' is above the maximum threshold with value ${sample[stat]}`,
          );
          warningCount[stat]!++;
        }
      }

      for (const stat of Object.keys(WARNING_CONFIG.min) as AudioQualityNumericStat[]) {
        if (sample[stat] <= WARNING_CONFIG.min[stat]!.value) {
          this.logger.warn(
            `RTCQualityMonitor warning: '${stat}' is below the minimum threshold with value ${sample[stat]}`,
          );
          warningCount[stat]!++;
        }
      }
    });

    // Iterate warnings and raise alarms based on config
    const previousActiveAlarms = new Set(this.activeAlarms);
    Object.entries(warningCount).forEach(([stat, count]) => {
      const threshold = {
        ...(stat in WARNING_CONFIG.max
          ? { name: 'max', value: WARNING_CONFIG.max[stat as AudioQualityNumericStat]!.value }
          : {
              name: 'min',
              value: WARNING_CONFIG.min[stat as AudioQualityNumericStat]!.value,
            }),
      };
      const warningName =
        threshold.name === 'max'
          ? WARNING_CONFIG.max[stat as AudioQualityNumericStat]!.warningName
          : WARNING_CONFIG.min[stat as AudioQualityNumericStat]!.warningName;
      if (count >= WARNING_CONFIG.raiseAlarmWhen && !this.activeAlarms.has(warningName)) {
        this.logger.warn(`RTCCallQualityMonitor - Warning: '${warningName}' alarm raised`);
        // TODO: evaluate if Twilio-like formatting is required for warnings
        // const warningPayload: QualityWarning = {
        //   name: stat.toString(),
        //   samples: currentSamplePool,
        //   threshold,
        //   values: currentSamplePool.map(
        //     (sampleStat) => sampleStat[stat as AudioQualityNumericStat],
        //   ),
        // };
        this.activeAlarms.add(warningName);
        // this.eventsServiceInstance.emitExternal(warningName, warningPayload);
      } else if (count <= WARNING_CONFIG.clearAlarmWhen && this.activeAlarms.has(warningName)) {
        this.activeAlarms.delete(warningName);
        // this.eventsServiceInstance.emitExternal(WARNING_NAMES.QualityWarningCleared, warningName);
      }
    });

    // Only send current warnings if they're different from the last iteration
    if (!equalSet(previousActiveAlarms, this.activeAlarms)) {
      const message: QualityWarnings = {
        highJitter: this.activeAlarms.has(WARNING_NAMES.QualityWarningHighJitter),
        highPacketLoss: this.activeAlarms.has(WARNING_NAMES.QualityWarningHighPacketLoss),
        highRtt: this.activeAlarms.has(WARNING_NAMES.QualityWarningHighRTT),
        lowMos: this.activeAlarms.has(WARNING_NAMES.QualityWarningLowMos),
      };

      this.eventsService.emitExternal(ExternalEvents.QualityWarningsChangedNotification, message);
      try {
        await this.audioQualityServiceInstance.sendCurrentWarnings(message);
      } catch (error) {
        this.logger.error('RTCCallQualityMonitor - error reporting warnings');
      }
    }
  }
}

export { RTCCallQualityMonitor };
