  private _checkIsValidModel(currModel: any): void {
    // Logger.warn('Deprecated - SchemaType is deprecated, use SchemaTypeClient instead');
    if (currModel.constructor === FormData) {
      // eslint-disable-next-line @typescript-eslint/ban-ts-comment
      // @ts-ignore TODO: FormData isn't an Iterator on React Native
      const formDataAsJson = Object.fromEntries(currModel);

      for (const key of ['fieldModifiers', 'object']) {
        //FormData usualy has only these values as keys and the json is stored inside it
        // eslint-disable-next-line no-prototype-builtins
        if (formDataAsJson.hasOwnProperty(key)) {
          const jsonStr: string = formDataAsJson[key] as string;
          currModel = JSON.parse(jsonStr);
          break;
        }
      }
    } else {
      currModel = cloneDeep(currModel);
    }

    for (const key of ['id']) {
      //these keys might be present in the payload but not in the schema

      //these keys might be present in the payload but not in the schema
      // eslint-disable-next-line no-prototype-builtins
      if (currModel.hasOwnProperty(key)) {
        delete currModel[key];
      }
    }

    if (Object.keys(currModel as object).length == 0) {
      throw new Error(`SchemaType - No paramenter Passed`);
    }

    for (const field in this.model.fields) {
      //check if all the keys in payload is a part of model.fields

      // eslint-disable-next-line no-prototype-builtins
      if (currModel.hasOwnProperty(field)) {
        delete currModel[field];
      }
    }

    if (Object.keys(currModel as object).length > 0) {
      //check if remaining keys in payload is a part of model.relations
      for (const field in this.model.relations) {
        // eslint-disable-next-line no-prototype-builtins
        if (currModel.hasOwnProperty(field)) {
          delete currModel[field];
        }
      }
    }

    if (Object.keys(currModel as object).length > 0) {
      //if still keys are remaining , those keys are not allowed in schema
      throw new Error(
        `SchemaType - Unknown Parameter passed ${Object.keys(currModel as object).toString()}`,
      );
    }
  }

