  /**
   * @deprecated Use `SchemaTypeClient` to interact with `SchemaTypes`
   */
  private async getData(url: string) {
    this.logger.warn('SchemaType - getData is deprecated, use SchemaTypeClient instead');

    const collection: any[] = [];

    const axiosResponse = await axiosInstance.get(url);
    const data = axiosResponse.data;

    const model: any = this.getNewModel();

    data.objects?.forEach((data: any) => {
      collection.push(this.addModel(data, model));
    });

    const sort: any = this.getSortedMethod();

    sortObject(collection, sort.ascending as number, sort.getter as (value: any) => any);

    this.searchConfig.previous = parseInt(data.previous as string) || 0;
    this.searchConfig.next = parseInt(data.next as string) || 0;
    this.searchConfig.count = data.count;
    this.searchConfig.total = data.total;

    return collection;
  }
