  private getSortedMethod(): any {
    // Logger.warn('Deprecated - SchemaType is deprecated, use SchemaTypeClient instead');
    switch (this.model.name) {
      case 'workitem':
      case 'recording':
        return {
          ascending: -1,
          fieldname: 'model.createdAt',
          getter: (model: any) => {
            return model.createdAt;
          },
        };

      default:
        return {
          ascending: 1,
          fieldname: 'model.name',
          getter: (model: any) => {
            return model.name;
          },
        };
    }
  }

