  public addModel(model: any, baseModel: any): any {
    // Logger.warn('Deprecated - SchemaType is deprecated, use SchemaTypeClient instead');
    this.helper.processData(model);

    const newModel = Object.assign({}, baseModel, model);
    return newModel;
  }

  public updateModel(currentModel: any, newModel: any): any {
    // Logger.warn('Deprecated - SchemaType is deprecated, use SchemaTypeClient instead');
    Object.assign(currentModel, newModel);

    return currentModel;
  }
