import type {
  Language,
  ISchemaType,
  PaginatedResponse,
  SchemaLayout,
  Status,
  Campaign,
  Disposition,
} from '../../types';
import { axiosInstance } from '../axios';
import { type FetchQueryOptions } from '@tanstack/query-core';

export function getStaticDataQueryOptions<
  const T extends StaticDataObjectTypes = StaticDataObjectTypes,
>(key: T) {
  return {
    queryFn: async ({ client, queryKey }) => {
      const queryData = client.getQueryData<Array<StaticDataTypes[T]>>(queryKey);

      const ifModifiedSince = queryData?.reduce((previous, current) => {
        const { modifiedAt } = current;

        return modifiedAt > previous ? modifiedAt : previous;
      }, 0);

      const response = await axiosInstance.get<PaginatedResponse<StaticDataTypes[T]>>(
        staticDataURLs[key],
        {
          params: {
            ifModifiedSince,
          },
        },
      );

      if (response.status === 304) {
        return queryData!;
      }

      let data: Array<StaticDataTypes[T]>;

      if (!queryData) {
        data = response.data.objects ?? [];
      } else {
        data = queryData.reduce<Array<StaticDataTypes[T]>>((acc, objectType) => {
          const schema = response.data.objects?.find((schemaFromResponse) => {
            return schemaFromResponse._id === objectType._id;
          });

          if (schema) {
            if (schema.deletedAt) {
              return acc;
            }

            acc.push(schema);

            return acc;
          }

          acc.push(objectType);

          return acc;
        }, []);
      }

      return data;
    },
    queryKey: ['static', key],
  } satisfies FetchQueryOptions<Array<StaticDataTypes[T]>>;
}

interface StaticDataTypes {
  campaign: Campaign;
  disposition: Disposition;
  language: Language;
  schemalayout: SchemaLayout;
  schematype: ISchemaType;
  status: Status;
}

type StaticDataObjectTypes = keyof StaticDataTypes;

type StaticDataURLs = Record<StaticDataObjectTypes, string>;

const staticDataURLs: StaticDataURLs = {
  campaign: '/users/api/types/campaign?rows=1000',
  disposition: '/users/api/types/disposition?q=*',
  language: '/data/api/types/language?q=*&rows=1000',
  schemalayout: '/data/api/types/schemalayout?q=*&rows=1000',
  schematype: '/data/api/types/schematype?q=*&rows=1000',
  status: '/users/api/types/status?q=*&rows=1000', // &fields=%5B_id,name,status,presentToAgent%5D
};
