import type {
  ParsedConnectionStats,
  IceCandidateConnectionStats,
  ParsedOutboundAudioStreamStats,
  ParsedInboundAudioStreamStats,
  ParsedRemoteOutboundStreamStats,
  ParsedRemoteInboundStreamStats,
  IRTCStatsGetter,
  ParsedRTCStats,
  ITwilioRTCStatsGetter,
  ParsedTwilioRTCStats,
  RTCStatsReport,
  RTCStatsType,
} from '../../types/rtc-stats';

const getIsAudio = (reportItem: Record<string, unknown>): boolean => {
  const mediaType = (reportItem['mediaType'] || reportItem['kind']) as 'audio' | 'video';

  if (!['audio', 'video'].includes(mediaType)) {
    const { id: reportId } = reportItem;

    if (!reportId) {
      return false;
    }

    // Check for Safari browser as it does not have kind and mediaType props
    if (JSON.stringify(reportId).includes('Video')) {
      return false;
    }

    if (JSON.stringify(reportId).includes('Audio')) {
      return true;
    }

    return false;
  }

  return mediaType === 'audio';
};

const allowedReportTypes = new Set([
  'candidate-pair',
  'inbound-rtp',
  'outbound-rtp',
  'remote-outbound-rtp',
  'remote-inbound-rtp',
  'track',
  'transport',
  'codec',
]);

const prepareConnectionStats = (
  candidatePair?: Record<string, unknown>,
  stats?: RTCStatsReport,
): ParsedConnectionStats => {
  if (!candidatePair || !stats) {
    return {} as ParsedConnectionStats;
  }

  const connectionStats = { ...candidatePair };

  if (connectionStats['remoteCandidateId']) {
    const candidate = stats.get(
      connectionStats['remoteCandidateId'] as string,
    ) as IceCandidateConnectionStats;
    connectionStats['remote'] = { ...candidate };
  }

  if (connectionStats['localCandidateId']) {
    const candidate = stats.get(
      connectionStats['localCandidateId'] as string,
    ) as IceCandidateConnectionStats;
    connectionStats['local'] = { ...candidate };
  }

  return connectionStats as unknown as ParsedConnectionStats;
};

const mapConnectionStatsIfNecessary = (
  mappedStats: ParsedRTCStats,
  statsItem: Record<string, unknown>,
  stats: RTCStatsReport,
) => {
  if (!!mappedStats.connection.id || !statsItem['transportId']) {
    return;
  }

  const transportStats = stats.get(statsItem['transportId'] as string) as Record<
    string,
    unknown
  > | null;

  if (transportStats?.['selectedCandidatePairId']) {
    const candidatePair = stats.get(transportStats['selectedCandidatePairId'] as string) as Record<
      string,
      unknown
    >;
    mappedStats.connection = prepareConnectionStats(candidatePair, stats);
  }
};

const updateMappedStatsWithReportItemData = (
  statsItem: Record<string, unknown>,
  mappedStats: ParsedRTCStats,
  stats: RTCStatsReport,
): void => {
  const type = statsItem['type'] as RTCStatsType;

  if (type === 'candidate-pair' && statsItem['state'] === 'succeeded' && statsItem['nominated']) {
    mappedStats.connection = prepareConnectionStats(statsItem, stats);
    return;
  }

  const isAudio = getIsAudio(statsItem);
  if (!isAudio) {
    return;
  }

  if (type === 'outbound-rtp') {
    const trackInfo = (stats.get(statsItem['trackId'] as string) ||
      stats.get(statsItem['mediaSourceId'] as string) ||
      stats.get(statsItem['trackIdentifier'] as string) ||
      null) as ParsedOutboundAudioStreamStats['track'];

    const statsToAdd = {
      ...statsItem,
      track: { ...trackInfo },
    };

    mappedStats.audio.outbound.push(statsToAdd as ParsedOutboundAudioStreamStats);
    return;
  }

  if (type === 'inbound-rtp') {
    const trackInfo = (stats.get(statsItem['trackId'] as string) ||
      stats.get(statsItem['mediaSourceId'] as string) ||
      stats.get(statsItem['trackIdentifier'] as string) ||
      null) as ParsedInboundAudioStreamStats['track'];

    mapConnectionStatsIfNecessary(mappedStats, statsItem, stats);

    const statsToAdd = {
      ...statsItem,
      track: { ...trackInfo },
    };

    mappedStats.audio.inbound.push(statsToAdd as ParsedInboundAudioStreamStats);

    // Get codec
    if (statsItem['codecId']) {
      const codecItem = stats.get(statsItem['codecId'] as string) as Record<string, unknown>;
      mappedStats.codec = codecItem['mimeType'] as string;
    }
    return;
  }

  if (type === 'remote-outbound-rtp') {
    mappedStats.remote.audio.outbound.push({
      ...statsItem,
    } as unknown as ParsedRemoteOutboundStreamStats);
    return;
  }

  if (type === 'remote-inbound-rtp') {
    mapConnectionStatsIfNecessary(mappedStats, statsItem, stats);

    mappedStats.remote.audio.inbound.push({
      ...statsItem,
    } as unknown as ParsedRemoteInboundStreamStats);
  }
};

const mapReportsStats = (rtcStats: RTCStatsReport): ParsedRTCStats => {
  const mappedStats: ParsedRTCStats = {
    audio: {
      inbound: [],
      outbound: [],
    },
    codec: '',
    connection: {} as ParsedConnectionStats,
    remote: {
      audio: {
        inbound: [],
        outbound: [],
      },
    },
  };

  rtcStats.forEach((reportItem: Record<string, unknown>) => {
    if (!allowedReportTypes.has(reportItem['type'] as RTCStatsType)) {
      return;
    }

    updateMappedStatsWithReportItemData(reportItem, mappedStats, rtcStats);
  });

  return mappedStats;
};

const checkIsConnectionClosed = (c: IRTCStatsGetter): boolean => {
  // Interface implementer doesn't have all peer connection data available
  if (!c.iceConnectionState || !c.connectionState) {
    return false;
  }

  return c.iceConnectionState === 'closed' || c.connectionState === 'closed';
};

export const parseRtcPeerConnectionStats = async (
  rtcPeerConnection: IRTCStatsGetter,
): Promise<ParsedRTCStats | undefined> => {
  if (checkIsConnectionClosed(rtcPeerConnection)) {
    return undefined;
  }

  try {
    const allStats = await rtcPeerConnection.getStats();
    return mapReportsStats(allStats);
  } catch (error) {
    return undefined;
  }
};

export const parseTwilioRTCReportStats = async (
  twilioRtcStatsGetter: ITwilioRTCStatsGetter,
): Promise<ParsedTwilioRTCStats | undefined> => {
  const mappedStats: ParsedTwilioRTCStats = {
    availableIncomingBitrate: 0,
    availableOutgoingBitrate: 0,
    codec: '',
    currentRoundTripTime: 0,
    localAudioLevel: 0,
    localJitter: 0,
    localPacketsLost: 0,
    localTimestamp: 0,
    packetsReceived: 0,
    packetsSent: 0,
    remoteAudioLevel: 0,
    remoteJitter: 0,
    remotePacketsLost: 0,
    remoteTimestamp: 0,
    totalRoundTripTime: 0,
  };
  try {
    const reports = await twilioRtcStatsGetter.getStats();
    if (reports.length <= 0) {
      return undefined;
    }
    const stats = reports[0]!;
    stats.localAudioTrackStats.forEach((track) => {
      if (mappedStats.codec === '') {
        mappedStats.codec = track.codec;
      }
      mappedStats.localAudioLevel += track.audioLevel;
      mappedStats.localJitter += track.jitter;
      mappedStats.localPacketsLost += track.packetsLost;
      mappedStats.packetsSent += track.packetsSent;
      mappedStats.localTimestamp += track.timestamp;
    });

    mappedStats.localAudioLevel /= stats.localAudioTrackStats.length;
    mappedStats.localJitter /= stats.localAudioTrackStats.length;
    mappedStats.localPacketsLost /= stats.localAudioTrackStats.length;
    mappedStats.localTimestamp /= stats.localAudioTrackStats.length;
    mappedStats.packetsSent /= stats.localAudioTrackStats.length;

    stats.remoteAudioTrackStats.forEach((track) => {
      if (mappedStats.codec === '') {
        mappedStats.codec = track.codec;
      }
      mappedStats.remoteAudioLevel += track.audioLevel;
      mappedStats.remoteJitter += track.jitter;
      mappedStats.remotePacketsLost += track.packetsLost;
      mappedStats.packetsReceived += track.packetsReceived;
      mappedStats.remoteTimestamp += track.timestamp;
    });

    mappedStats.remoteAudioLevel /= stats.remoteAudioTrackStats.length;
    mappedStats.remoteJitter /= stats.remoteAudioTrackStats.length;
    mappedStats.remotePacketsLost /= stats.remoteAudioTrackStats.length;
    mappedStats.packetsReceived /= stats.remoteAudioTrackStats.length;
    mappedStats.remoteTimestamp /= stats.remoteAudioTrackStats.length;

    stats.iceCandidatePairStats.forEach((pair) => {
      if (pair.activeCandidatePair) {
        mappedStats.availableIncomingBitrate = pair.availableIncomingBitrate;
        mappedStats.availableOutgoingBitrate = pair.availableOutgoingBitrate;
        mappedStats.currentRoundTripTime = pair.currentRoundTripTime;
        mappedStats.totalRoundTripTime = pair.totalRoundTripTime;
      }
    });
    return mappedStats;
  } catch (error) {
    return undefined;
  }
};
