import { type InjectionContainer } from '../internal';
import { axiosInstance } from '../utilities';
import { type StateService } from './state';

export class InternalStateManagementService {
  protected stateService: StateService;

  constructor({ stateService }: Pick<InjectionContainer, 'stateService'>) {
    this.stateService = stateService;
  }

  public async upsertValueFromAPI(name: string, url: string, fields?: string[]) {
    // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
    if (fields !== null && fields !== undefined) {
      url += `&fields=[${fields.toString()}]`;
    }

    const response = await axiosInstance.get(encodeURI(url));
    // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
    this.stateService.set(name, response.data.objects || response.data || []);
    return response;
  }
}
