import { dependencyInjectionContainer, type InjectionContainer } from '../internal';
import { ExternalEvents, InternalEvents } from '../models';
import { type UserStatistics } from '../types';
import {
  type StatisticsByStatusId,
  type SupervisorStatsNotificationData,
} from '../types/statistics';
import { axiosInstance, ofType } from '../utilities';
import { type EventsService } from './eventsservice';
import { type LoggerService } from './logger';
import { type StateService } from './state';

export class StatisticsService {
  private eventsService: EventsService;
  private stateService: StateService;
  private logger: LoggerService;
  private isSocketStarted = false;

  constructor({
    eventsService,
    loggerService,
    stateService,
  }: Pick<InjectionContainer, 'eventsService' | 'stateService' | 'loggerService'>) {
    this.eventsService = eventsService;
    this.stateService = stateService;
    this.logger = loggerService;

    this.handleSupervisorStatsNotification();
    this.handleSocketDisconnectedNotification();
    this.handleSocketConnectedNotification();
  }

  /**
   * Starts the statistics service.
   *
   * @param options - The options for starting the statistics service.
   * @returns A promise that resolves to the response from the server.
   */
  async start(options: StartStatisticsOptions) {
    this.logger.debug('StatisticsService - start - invoked with payload:', options);

    const statisticsSocketClient = dependencyInjectionContainer.resolve('statisticsSocketClient');
    if (!statisticsSocketClient.isSocketInitiated()) {
      if (!this.stateService.canView('dashboard')) {
        throw new Error('User does not have permission to view dashboard statistics');
      }
      await statisticsSocketClient.connect();
    }

    const payload: StartStatisticsPayload = {
      campaigns: options.campaigns ? 1 : undefined,
      outboundlists: options.outboundLists ? 1 : undefined,
      queues: options.queues ? 1 : undefined,
      users: options.users ? 1 : undefined,
      workitems: options.workItems ? 1 : undefined,
    };

    return axiosInstance.post('/users/api/stats/filter', payload);
  }

  /**
   * Stops the statistics service.
   *
   * @returns {Promise<void>} A promise that resolves when the service is stopped.
   */
  stop() {
    this.logger.trace('StatisticsService - stop');
    return axiosInstance.delete('/users/api/stats/filter');
  }

  private handleSocketDisconnectedNotification() {
    this.eventsService.statisticWebSocketEvents$
      .pipe(
        ofType([
          InternalEvents.SocketDisconnectedNotification,
          InternalEvents.SocketClosedNotification,
        ]),
      )
      .subscribe(() => {
        if (this.isSocketStarted) {
          this.isSocketStarted = false;
          this.stop().catch((error: unknown) => {
            this.logger.error(
              'StatisticsService - handleSocketDisconnectedNotification - error',
              error,
            );
          });
        }
      });
  }

  private handleSocketConnectedNotification() {
    this.eventsService.statisticWebSocketEvents$
      .pipe(ofType([InternalEvents.SocketConnectedNotification]))
      .subscribe(() => {
        this.isSocketStarted = true;
      });
  }

  private handleSupervisorStatsNotification() {
    this.eventsService.statisticWebSocketEvents$
      .pipe(ofType(InternalEvents.SupervisorStatsNotification))
      .subscribe((event) => {
        const campaigns = Object.values(event.data.stats.campaigns);
        const outboundlists = Object.values(event.data.stats.outboundlists);
        const queues = Object.values(event.data.stats.queues);
        const users = Object.values(event.data.stats.users).map(
          ({ statisticsByStatusId, ...stats }) => {
            // remove bad data
            const fixedStatisticsByStatusId = Object.entries(
              statisticsByStatusId,
            ).reduce<StatisticsByStatusId>((previousValue, [id, { duration, percentage }]) => {
              previousValue[id] = {
                duration,
                percentage,
              };
              return previousValue;
            }, {});
            return { ...stats, statisticsByStatusId: fixedStatisticsByStatusId } as UserStatistics;
          },
        );
        const workitems = Object.values(event.data.stats.workitems);
        const payload: SupervisorStatsNotificationData = {
          campaigns,
          outboundlists,
          queues,
          users,
          workitems,
        };
        this.eventsService.emitExternal(ExternalEvents.SupervisorStatsNotification, payload);
      });
  }
}

interface StartStatisticsOptions {
  campaigns?: boolean;
  outboundLists?: boolean;
  queues?: boolean;
  users?: boolean;
  workItems?: boolean;
}

interface StartStatisticsPayload {
  campaigns?: 1;
  outboundlists?: 1;
  queues?: 1;
  users?: 1;
  workitems?: 1;
}
