import { Logger } from '../../utilities';
import { type DataService } from '../data';
import { Helper, type HelperInterface } from './base';
import { WorkitemTypes } from '../../models';

export class HelperWorkitem extends Helper {
  private static instance: HelperInterface;

  public static getInstance(language: string, dataService: DataService): HelperInterface {
    if (!this.instance) {
      this.instance = new HelperWorkitem(language, dataService);
    }

    return this.instance;
  }

  private constructor(
    protected override language: string,
    protected override dataService: DataService,
  ) {
    super(language, dataService);
  }

  public processData(model: any): void {
    if (!model.name) {
      if (model.contact) {
        if (model.contact.name) {
          model.name = model.contact.name;
        } else {
          if (model.contact.firstName && model.contact.lastName) {
            model.name = `${model.firstName} ${model.lastName}`;
          } else {
            if (model.contact.firstName) {
              model.name = `${model.firstName}`;
            }

            if (model.contact.lastName) {
              model.name = `${model.lastName}`;
            }
          }
        }
      } else {
        if (
          // @ts-expect-error TODO: revisit this logic since it currently doesn't check anything
          [
            WorkitemTypes.OutboundCall,
            WorkitemTypes.OutboundEmail,
            WorkitemTypes.OutboundExtensionCall,
            WorkitemTypes.OutboundFax,
            WorkitemTypes.OutboundSMS,
          ].indexOf
        ) {
          model.name = model.to;
        } else {
          model.name = model.from;
        }
      }
    }

    if (
      ['undefined', 'null'].includes(model.contactId as string) ||
      model.contactId === undefined
    ) {
      model.contactId = null;
    }

    Logger.log(`HelperWorkitem - processData ${model.name}`);
  }
}
