export class BaseLocalStorageService {
  public getValue(_key: string): Promise<string | null> {
    return Promise.resolve(null);
  }
  public setValue(_key: string, _value: string): Promise<void> {
    return Promise.resolve();
  }

  public async upsertObjectValue<T>(key: string, value: Partial<T>): Promise<Partial<T> | null> {
    const currentValue = await this.getValue(key);
    if (!currentValue) {
      await this.setValue(key, JSON.stringify(value));
      return value;
    }

    if (currentValue.startsWith('{')) {
      try {
        const parsedCurrentValue = JSON.parse(currentValue) as T;
        const updatedValue = { ...parsedCurrentValue, ...value };
        await this.setValue(key, JSON.stringify(updatedValue));
        return updatedValue;
      } catch (error: unknown) {
        //Logger.log('Error parsing JSON from localStorage:', error);
        return null;
      }
    }

    return null;
  }

  public async getObjectValue(key: string): Promise<Record<string, unknown> | null> {
    const currentValue = await this.getValue(key);
    if (currentValue?.startsWith('{')) {
      try {
        const parsedCurrentValue = JSON.parse(currentValue) as Record<string, unknown>;
        return parsedCurrentValue;
      } catch (error: unknown) {
        //Logger.log('Error parsing JSON from localStorage:', error);
        return null;
      }
    } else {
      return null;
    }
  }

  public async setObjectValue(key: string, value: Record<string, unknown>): Promise<void> {
    await this.setValue(key, JSON.stringify(value));
  }
}
