import type { FetchPSTNNumbersResponseBody, SchemaTypeSearchPayload } from '../types';
import { type BaseSchemaTypeClient } from '../models';
import { axiosInstance } from '../utilities';
import { type InjectionContainer } from '../internal';
import { type LoggerService } from './logger';

/**
 * @deprecated ProvisioningService is deprecated
 */
export class ProvisioningService {
  private schemaTypeClient: BaseSchemaTypeClient;
  private logger: LoggerService;

  constructor({
    loggerService,
    schemaTypeClient,
  }: Pick<InjectionContainer, 'schemaTypeClient' | 'loggerService'>) {
    this.schemaTypeClient = schemaTypeClient;
    this.logger = loggerService;
  }

  /**
   * @deprecated searchUnusedPSTNNumbers is deprecated
   */
  async searchUnusedPSTNNumbers({
    q = '*',
    queryParams,
    rows = 100,
    start = 0,
  }: SchemaTypeSearchPayload): Promise<FetchPSTNNumbersResponseBody> {
    this.logger.warn(
      'ProvisioningService - searchUnusedPSTNNumbers is deprecated and will be removed in a future version',
    );
    const uri = this.schemaTypeClient.getLinkURI('pstnnumber', 'retrieveUnusedNumbers');
    const params = {
      ...queryParams,
      q: encodeURIComponent(q),
      rows,
      start,
    };

    const response = await axiosInstance.get<FetchPSTNNumbersResponseBody>(uri, { params });
    return response.data;
  }
}
