import parsePhoneNumberFromString, { type CountryCode, parsePhoneNumberWithError } from 'libphonenumber-js';

export interface PhoneNumber {
  country: string | undefined;
  countryCallingCode: string,
  nationalNumber: string;
  number: string;
}

export type PhoneNumberFormat = 'NATIONAL' | 'INTERNATIONAL' | 'E.164';


/**
 * Formats a phone number to E.164 format.
 * @param {string} phoneNumber - The phone number to format.
 * @param {CountryCode} countryCode - The country code of the phone number. By defult , its US.
 * @returns {string | null} - The formatted phone number in E.164 format or null if the number is invalid.
 */
export const formatPhoneNumberEx = (
  phoneNumber: string,
  countryCode: CountryCode = 'US',
): string | null => {
  const phoneNumberInstance = parsePhoneNumberFromString(phoneNumber, countryCode);

  if (phoneNumberInstance?.isValid()) {
    return phoneNumberInstance.format('E.164');
  }

  return null;
};

export const formatPhoneNumber = (
  phoneNumber: string,
  format: PhoneNumberFormat = 'INTERNATIONAL',
): string | null => {
  try {
    phoneNumber = `+${phoneNumber.replaceAll(/\D/g, '')}`;

    const phoneNumberInstance = parsePhoneNumberWithError(phoneNumber);

    return phoneNumberInstance.format(format);
  } catch (error) {
    /* ignore */
    return null;
  }
};

/**
 * Formats a phone number to E.164 format.
 * @param {string} phoneNumber - The phone number to format.
 * @returns {string | null} - The formatted phone number in E.164 format or null if the number is invalid.
 */
export const parsePhoneNumber = (
  phoneNumber: string
): PhoneNumber | null => {
  try {
    phoneNumber = `+${phoneNumber.replaceAll(/\D/g, '')}`;

    const phoneNumberInstance = parsePhoneNumberWithError(phoneNumber);

    return {
      country: phoneNumberInstance.country,
      countryCallingCode: phoneNumberInstance.countryCallingCode,
      nationalNumber: phoneNumberInstance.nationalNumber,
      number: phoneNumberInstance.number,

    };
  } catch (error) {
    /* ignore */
    return null;
  }
};
