export const PERMISSIONS = {
  ALL: '*',
  CREATE: 'create',
  DELETE: 'delete',
  HIDDEN: 'hidden',
  HIDE: 'hide',
  IMPORT: 'import',
  LISTEN: 'listen',
  LISTEN_MINE: 'listen-mine',
  SEARCH: 'search',
  SHOW: 'show',
  UPDATE: 'update',
  UPDATE_MINE: 'update-mine',
  VIEW: 'view',
  VIEW_MINE: 'view-mine',
} as const;
export type Permission = (typeof PERMISSIONS)[keyof typeof PERMISSIONS];

