import type { RelatedArticlesV2Response, RelatedArticleRequest, RelatedArticlesResponse } from '../types/relatedArticles';
import { s360AxiosClient } from '../utilities/s360AxiosClient';

/**
 * Represents a service for managing related articles.
 */
export class RelatedArticlesService {
  /**
   * Creates an article in the Related Articles service.
   *
   * @param article - The article to create.
   * @returns A Promise that resolves to the response from the server.
   */
  public async createArticle(article: RelatedArticleRequest): Promise<string> {
    const response = await s360AxiosClient.post<string>(
      '/related-articles-service/private/v1/articles',
      article,
    );

    return response.data;
  }

  /**
   * Creates a post-processed article in the Related Articles service.
   *
   * @param article - The article to create.
   * @param version - The version is to target api version. Defaults to 'v1'.
   * @returns A Promise that resolves to the response from the server.
   */
  public async createPostProcessedArticle(
    article: RelatedArticleRequest,
    version?: "v1",
  ): Promise<RelatedArticlesResponse>;
  public async createPostProcessedArticle(
    article: RelatedArticleRequest,
    version: "v2",
  ): Promise<RelatedArticlesV2Response>;
  public async createPostProcessedArticle(
    article: RelatedArticleRequest,
    version: "v1" | "v2" = 'v1',
  ): Promise<RelatedArticlesResponse | RelatedArticlesV2Response> {
    const response = await s360AxiosClient.post<RelatedArticlesResponse | RelatedArticlesV2Response>(
      `/related-articles-service/private/${version}/articles-post-processed`,
      article,
    );
    return response.data;
  }

  /**
   * Fetches an article by its ID from the related articles service.
   *
   * @param {string} articleId - The unique identifier of the article to fetch.
   * @returns {Promise<string>} - A promise that resolves to the article content as a string.
   */
  public async getArticle(articleId: string): Promise<string> {
    const response = await s360AxiosClient.get<string>(
      `/related-articles-service/private/v1/articles/${articleId}`,
    );
    return response.data;
  }
}
