/**
 * Temporarily required function to filter out the contact array item in conversations response
 */
const isWorkitem = (value: Workitem | ContactArray): value is Workitem => {
  return (value as { objectType?: string }).objectType === 'workitem';
};

const isEngagementDataWithWorkitem = (
  data: EngagementData,
): data is EngagementData & { workitem: Workitem } => {
  const unknownData = data as unknown;
  return (
    typeof unknownData === 'object' &&
    unknownData !== null &&
    'workitem' in unknownData &&
    typeof unknownData.workitem === 'object' &&
    unknownData.workitem !== null
  );
};

