/**
 * Converts camelCase or PascalCase string to SNAKE_CASE
 * Example: "OutboundVideoMeeting" -> "OUTBOUND_VIDEO_MEETING"
 */
function toSnakeCase(str: string): string {
  return str
    .replaceAll(/([A-Z])/g, '_$1')
    .replace(/^_/, '')
    .toUpperCase();
}

