  private getFeedLoadingKey(
    filter: FetchFeedPayload['filter'],
    queueIds: FetchFeedPayload['queueIds'],
    tab: FetchFeedPayload['tab'],
  ): string {
    const normalizedFilter = normalizeFeedFilter(filter).join(',');
    const normalizedQueueIds = queueIds != null && queueIds !== '' ? queueIds : 'my-inbox';
    return `${normalizedFilter}:${normalizedQueueIds}:${tab}`;
  }

  public isFeedLoading(
    filter: FetchFeedPayload['filter'],
    queueIds: FetchFeedPayload['queueIds'],
    tab: FetchFeedPayload['tab'],
  ): boolean {
    return this.feedLoadingStates.get(this.getFeedLoadingKey(filter, queueIds, tab)) ?? false;
  }

