  public getConversationIdsByQueueIds({
    filter,
    queueIds,
    tab,
  }: {
    filter: FetchFeedPayload['filter'];
    queueIds: string[];
    tab: FetchFeedPayload['tab'];
  }): Array<{ conversationId: string; participants: Participant[]; workitems: Workitem[] }> {
    const result: Array<{
      conversationId: string;
      participants: Participant[];
      workitems: Workitem[];
    }> = [];
    for (const queueId of queueIds) {
      const feedQueryKey = getConversationsQueryOptions({
        filter,
        queueIds: queueId,
        tab,
      }).queryKey;
      const feedCache = queryClient.getQueryData<ConversationsQueryData>(feedQueryKey);
      for (const engagement of feedCache?.engagementData ?? []) {
        if (engagement.conversationId) {
          const workitemsQueryKey = getConversationWorkitemsQueryOptions({
            conversationId: engagement.conversationId,
          }).queryKey;
          const workitemsCache =
            queryClient.getQueryData<ConversationWorkitemsQueryData>(workitemsQueryKey);
          result.push({
            conversationId: engagement.conversationId,
            participants: engagement.participants ?? [],
            workitems: workitemsCache?.workitems ?? [],
          });
        }
      }
    }
    return result;
  }

  /**
   * Subscribe to TanStack Query cache changes and emit events
   * when conversation or workitem queries are updated
   */
  private subscribeToQueryCacheChanges() {
    const queryCache = queryClient.getQueryCache();

    this.queryCacheUnsubscribe = queryCache.subscribe((event) => {
      // Only handle 'updated' events (when query data changes)
      if (event.type !== 'updated') {
        return;
      }

      const query = event.query;
      const queryKey = query.queryKey as QueryKey;

      // Check if this is a conversations query (key:
      // ['conversations', 'push-feed', filter, tab, queueIds | 'my-inbox'])
      if (
        Array.isArray(queryKey) &&
        queryKey[0] === 'conversations' &&
        queryKey[1] === 'push-feed'
      ) {
        const feedFilter = normalizeFeedFilter(queryKey[2] as FetchFeedPayload['filter']);
        const feedTab = queryKey[3] as NonNullable<FetchFeedPayload['tab']>;
        const queueIdsSegment = queryKey[4] as string;
        const queryData = queryClient.getQueryData(queryKey);
        const data = queryData as ConversationsQueryData | undefined;

        if (data) {
          this.logger.debug('BaseConversationService - Query cache updated: conversations', {
            count: data.engagementData.length,
            filter: feedFilter,
            queueIds: queueIdsSegment,
            tab: feedTab,
          });

          // Emit event that conversations query was updated
          this.eventsService.emitExternal(ExternalEvents.ConversationsFeedQueryUpdated, {
            engagementData: data.engagementData,
            filter: feedFilter,
            queueIds: queueIdsSegment,
            tab: feedTab,
          });
        }
      }

      // Check if this is a conversation workitems query
      else if (
        Array.isArray(queryKey) &&
        queryKey[0] === 'conversations' &&
        queryKey[1] === 'workitems'
      ) {
        const [, , conversationId] = queryKey as QueryKey;
        const queryData = queryClient.getQueryData(queryKey);
        const data = queryData as ConversationWorkitemsQueryData | undefined;

        if (data) {
          this.logger.debug('BaseConversationService - Query cache updated: workitems', {
            conversationId,
            count: data.workitems.length,
          });

          // Emit event that conversation workitems query was updated
          this.eventsService.emitExternal(ExternalEvents.ConversationWorkitemsQueryUpdated, {
            conversationId: conversationId as string,
            workitems: data.workitems,
          });
        }
      }
    });
  }

  private getQueryKeyCacheKey(queryKey: QueryKey): string {
    return JSON.stringify(queryKey);
  }

  private schedulePersistQuery(queryKey: QueryKey): void {
    const queryPersister = dependencyInjectionContainer
      .resolve('persisterClient')
      .getQueryPersister();

    if (!queryPersister) {
      return;
    }

    this.pendingPersistQueryKeys.set(this.getQueryKeyCacheKey(queryKey), queryKey);

    if (this.persistQueriesTimer) {
      return;
    }

    // Delay persistence to the next macrotask so a burst of cache updates only
    // persists each query key once instead of blocking this hot path repeatedly.
    this.persistQueriesTimer = setTimeout(() => {
      this.persistQueriesTimer = undefined;
      const queryKeys = Array.from(this.pendingPersistQueryKeys.values());
      this.pendingPersistQueryKeys.clear();

      queryKeys.forEach((pendingQueryKey) => {
        queryPersister.persistQueryByKey(pendingQueryKey, queryClient).catch((error: unknown) => {
          this.logger.debug(
            'ConversationService - schedulePersistQuery - persistQueryByKey error',
            error,
          );
        });
      });
    }, 0);
  }

  private mergeWorkitemFeedNotification(
    current: ConversationWorkitemFeedPushNotificationData | undefined,
    incoming: ConversationWorkitemFeedPushNotificationData,
  ): ConversationWorkitemFeedPushNotificationData {
    if (!current) {
      return incoming;
    }

    const workitemsMap = current.workitems.reduce((acc: Map<string, Workitem>, item) => {
      if (!item.workitemId) {
        return acc;
      }
      acc.set(item.workitemId, item);
      return acc;
    }, new Map<string, Workitem>());

    incoming.workitems.forEach((item) => {
      if (!item.workitemId) {
        return;
      }
      workitemsMap.set(item.workitemId, item);
    });

    return {
      ...current,
      ...incoming,
      aiSummaries: incoming.aiSummaries.length > 0 ? incoming.aiSummaries : current.aiSummaries,
      batchMetadata: incoming.batchMetadata,
      conversation: incoming.conversation,
      pagination: incoming.pagination,
      workitems: Array.from(workitemsMap.values()),
    };
  }

  private queueWorkitemFeedNotification(
    notification: ConversationWorkitemFeedPushNotificationData,
  ): void {
    // Collapse multiple workitem feed events for the same conversation into one
    // pending payload so a single fetch burst does not cause per-event cache churn.
    const mergedNotification = this.mergeWorkitemFeedNotification(
      this.pendingWorkitemFeedNotifications.get(notification.conversationId),
      notification,
    );

    this.pendingWorkitemFeedNotifications.set(notification.conversationId, mergedNotification);

    if (this.workitemFeedNotificationsTimer) {
      return;
    }

    // Using setTimeout(..., 0) gives the socket burst one event-loop turn to
    // accumulate before we touch the cache, which is the core batching window.
    this.workitemFeedNotificationsTimer = setTimeout(() => {
      this.flushQueuedWorkitemFeedNotifications();
    }, 0);
  }

  private flushQueuedWorkitemFeedNotifications(): void {
    this.workitemFeedNotificationsTimer = undefined;

    if (this.pendingWorkitemFeedNotifications.size === 0) {
      return;
    }

    const notifications = Array.from(this.pendingWorkitemFeedNotifications.values());
    this.pendingWorkitemFeedNotifications.clear();

    // The push feed bypasses fixWorkitem(), so normalize the owner here to keep the
    // resolved `owner` field consistent with the REST path.
    const users = this.stateService.getUsers();

    // Batch query notifications so TanStack subscribers do not react to every
    // queued workitem update individually during a large notification burst.
    notifyManager.batch(() => {
      notifications.forEach((workitemFeedPushNotification) => {
        const workitems = workitemFeedPushNotification.workitems.map((workitem) => ({
          ...workitem,
          owner: resolveWorkitemOwner(workitem, users),
        }));
        this.upsertConversationWorkitemsCache({
          conversationId: workitemFeedPushNotification.conversationId,
          persist: true,
          workitems,
        });
        this.upsertMultiScopeWorkitemsCache({ workitems });
      });
    });
  }

