import type { FetchQueryOptions } from '@tanstack/query-core';
import type { TicketLinkedWorkitemsQueryData } from '../../types';
import { Logger } from '../logger';

export function getTicketLinkedWorkitemsQueryOptions({
  filter,
  ticketId,
}: {
  filter?: string[];
  ticketId: string;
}) {
  return {
    queryFn: ({ client, queryKey }) => {
      const queryData = client.getQueryData<TicketLinkedWorkitemsQueryData>(queryKey);

      Logger.log('getTicketLinkedWorkitemsQueryOptions', 'Query invoked', {
        hasData: !!queryData,
        ticketId,
        workitemCount: queryData?.workitems.length ?? 0,
      });

      // Return cached data if available, otherwise return empty state
      return queryData ?? {
        hasMore: true,
        nextCursor: null,
        workitems: [],
      };
    },
    queryKey: ['tickets', 'workitems', ticketId, filter ?? []],
  } satisfies FetchQueryOptions<TicketLinkedWorkitemsQueryData>;
}
