import axios, { isAxiosError } from 'axios';
import { dependencyInjectionContainer } from '../internal/dependencyInjectionContainer';
import { ExternalEvents } from '../models/events';

/**
 * Axios instance for making HTTP requests.
 */
export const axiosInstance = axios.create({
  headers: {
    Accept: 'application/json',
    'Content-Type': 'application/json',
  },
  // Axios will treat any non 2xx status codes as an error
  validateStatus: (status) => (status >= 200 && status < 300) || status == 304,

  withCredentials: true,
});

axiosInstance.interceptors.response.use(undefined, (error) => {
  if (
    isAxiosError(error) &&
    error.response?.status === 403 &&
    // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
    error.response.data?.errorCode === 403_020
  ) {
    const datadogService = dependencyInjectionContainer.resolve('datadogService');
    datadogService?.addAction(ExternalEvents.ExpiredTokenNotification);
    dependencyInjectionContainer
      .resolve('eventsService')
      .emitExternal(ExternalEvents.ExpiredTokenNotification);
  }

  throw error; // Re-throw the error to be handled in catch blocks
});

/**
 * Upserts the default request header with the specified header and value.
 * @param header - The header to be updated.
 * @param value - The value to be set for the header.
 */
export const upsertDefaultRequestHeader = (header: string, value: string) => {
  const logger = dependencyInjectionContainer.resolve('loggerService');
  logger.debug(`upsertDefaultRequestHeader - Axios header [${header}]`);
  axiosInstance.defaults.headers.common[header] = value;
};

/**
 * Returns the current value of a default request header, or undefined if not set.
 * @param header - The name of the header to read.
 */
export const getDefaultRequestHeader = (header: string): string | undefined => {
  const value = axiosInstance.defaults.headers.common[header];
  return typeof value === 'string' ? value : undefined;
};

/**
 * Deletes the default request header with the specified name.
 * @param header - The name of the header to delete.
 */
export const deleteDefaultRequestHeader = (header: string) => {
  const logger = dependencyInjectionContainer.resolve('loggerService');
  logger.debug(`deleteDefaultRequestHeader - Axios header [${header}] was deleted`);
  axiosInstance.defaults.headers.common[header] = undefined;
};

/**
 * Configures the Axios instance with the provided base URL and language.
 * @param options - The configuration options.
 * @param options.baseURL - The base URL for the Axios instance.
 * @param options.language - The language to be set in the 'Accept-Language' header.
 */
export const configureAxios = (options: { baseURL?: string; language?: string }) => {
  const { baseURL, language = 'en' } = options;
  const logger = dependencyInjectionContainer.resolve('loggerService');

  logger.debug('configureAxios - Axios configured with options', options);

  upsertDefaultRequestHeader('Accept-Language', language);
  axiosInstance.defaults.baseURL = baseURL;
};
