import {
  type BaseConversationService,
  type BaseTelephonyService,
  type InjectionContainer,
} from '../internal';
import { type UserSocketClient } from '../utilities/socketClient';
import { type WorkitemCache } from './workitemCache';
import { type StateService } from './state';
import { queryClient } from '../utilities';
import { type BasePersisterClient } from './persister';
import { defaultOptions } from '../utilities/queryClient';

export class ResourceManager {
  private stateService: StateService;
  private telephonyService: BaseTelephonyService;
  private userSocketClient: UserSocketClient;
  private workitemCache: WorkitemCache;
  private persisterClient: BasePersisterClient;
  private conversationService: BaseConversationService;

  constructor({
    conversationService,
    persisterClient,
    stateService,
    telephonyService,
    userSocketClient,
    workitemCache,
  }: Pick<
    InjectionContainer,
    | 'stateService'
    | 'telephonyService'
    | 'userSocketClient'
    | 'workitemCache'
    | 'persisterClient'
    | 'conversationService'
  >) {
    this.stateService = stateService;
    this.telephonyService = telephonyService;
    this.userSocketClient = userSocketClient;
    this.workitemCache = workitemCache;
    this.persisterClient = persisterClient;
    this.conversationService = conversationService;
  }

  async cleanup() {
    queryClient.setDefaultOptions(defaultOptions);
    queryClient.clear();
    this.persisterClient.dispose();
    this.stateService.clear();
    this.workitemCache.stop();
    this.conversationService.destroy();
    await this.userSocketClient.disconnect();
    await this.telephonyService.close();
  }
}
