import type { FetchFeedFilter, FetchFeedPayload } from '../types/conversation';
// Import directly from the constants module (not the `../models` barrel) to avoid a
// circular import: the barrel re-exports modules that import from `../utilities`, and
// `feedFilter` is itself part of `../utilities` — pulling the barrel here breaks module
// init order (WorkitemTypes ends up undefined at evaluation time).
import { WorkitemConversationTypes, type WorkitemConversationType } from '../models/constants';

/**
 * Conversation types each feed `tab` is allowed to contain.
 *
 * Mirrors the backend membership rule the push-feed batch already enforces
 * (e.g. `tab=internal` → `conversationType IN ('internal_chat','shared_inbox_internal')`).
 * Tabs not listed here (e.g. `all`, `unread`, `mentions`, `drafts`, `archived`) are
 * cross-cutting and are NOT restricted by conversation type.
 */
const TAB_TO_CONVERSATION_TYPES: Record<string, WorkitemConversationType[]> = {
  channels: [WorkitemConversationTypes.CHANNEL],
  external: [WorkitemConversationTypes.CONTACT_BASED, WorkitemConversationTypes.QUEUE_CONTACT],
  internal: [WorkitemConversationTypes.INTERNAL_CHAT, WorkitemConversationTypes.SHARED_INBOX_INTERNAL],
};

/**
 * Whether a conversation of the given `conversationType` belongs in the given feed `tab`.
 *
 * Used to gate realtime inserts/updates so a live conversation from one tab cannot leak
 * into another tab's cache bucket on the shared per-user WebSocket topic. `filter="all"`
 * means "all channels" — NOT "all conversation types" — so the tab check still applies.
 *
 * Returns `true` (unrestricted) for tabs with no type restriction, or when
 * `conversationType` is unknown (to avoid dropping legitimate conversations).
 */
export function tabAllowsConversationType(
  tab: FetchFeedPayload['tab'],
  conversationType: string | undefined,
): boolean {
  if (!tab) return true;
  const allowed = TAB_TO_CONVERSATION_TYPES[String(tab).toLowerCase()];
  // Tab has no conversation-type restriction (e.g. 'all', 'unread').
  if (!allowed) return true;
  // Cannot determine the type — don't block to avoid false negatives.
  if (!conversationType) return true;
  return allowed.includes(conversationType as WorkitemConversationType);
}

export function normalizeFeedFilter(
  filter: FetchFeedPayload['filter'],
): FetchFeedFilter[] {
  if (!filter) return ['all'];
  const arr = Array.isArray(filter) ? filter : [filter];
  const sorted = arr
    .filter((v): v is FetchFeedFilter => typeof v === 'string' && v.trim().length > 0)
    .sort((a, b) => a.localeCompare(b));
  const unique = [...new Set(sorted)];
  return unique.length === 0 ? ['all'] : unique;
}

export function areFeedFiltersEqual(
  a: FetchFeedPayload['filter'],
  b: FetchFeedPayload['filter'],
): boolean {
  const arrA = normalizeFeedFilter(a);
  const arrB = normalizeFeedFilter(b);
  return arrA.length === arrB.length && arrA.every((value, index) => value === arrB[index]);
}

export function isFetchFeedPayloadEqual(
  prev: {
    filter: FetchFeedPayload['filter'];
    queueIds?: string;
    tab: FetchFeedPayload['tab'];
  },
  current: {
    filter: FetchFeedPayload['filter'];
    queueIds?: string;
    tab: FetchFeedPayload['tab'];
  },
): boolean {
  if (prev.tab !== current.tab) return false;
  if (prev.queueIds && current.queueIds && prev.queueIds !== current.queueIds) {
    return false;
  }
  return areFeedFiltersEqual(prev.filter, current.filter);
}
