import { dependencyInjectionContainer } from '../internal';
import {
  type ActivationState,
  Client,
  type StompConfig,
  type StompSubscription,
} from '@stomp/stompjs';

import { InternalEvents } from '../models';
import { SocketState } from '..';

export type Callback = (messageBody: MessageBody) => void;

interface SocketOptions {
  callback: Callback;
  getToken: () => string;
  id: string;
  onSocketStatusChange?: (status: SocketState) => void;
  subscriptionURL: string;
  webSocketURL: string;
}

export interface MessageBody {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  [key: string]: any;
  id?: string;
  name: string;
}

export class Socket {
  private stompClient: Client | null | undefined;

  private subscription: StompSubscription | null | undefined;

  private callback: Callback;
  private onSocketStatusChange: (status: SocketState) => void;

  private id: string;

  private getToken: () => string;

  private webSocketURL: string;

  public subscriptionURL: string;

  protected datadogService = dependencyInjectionContainer.resolve('datadogService');

  private logger = dependencyInjectionContainer.resolve('loggerService');

  constructor({
    callback,
    getToken,
    id,
    onSocketStatusChange,
    subscriptionURL,
    webSocketURL,
  }: SocketOptions) {
    this.logger.debug(`Socket was instantiated with options: `, {
      id,
      subscriptionURL,
      webSocketURL,
    });

    this.id = id;
    this.getToken = getToken;
    this.webSocketURL = webSocketURL;
    this.subscriptionURL = subscriptionURL;
    this.callback = callback;
    this.onSocketStatusChange = onSocketStatusChange ?? (() => {});
  }

  public connect() {
    this.logger.trace('Socket - connect');

    const config: StompConfig = {
      appendMissingNULLonIncoming: true,
      brokerURL: this.webSocketURL,
      connectHeaders: {},
      discardWebsocketOnCommFailure: true,
      forceBinaryWSFrames: true,
      heartbeatIncoming: 10_000,
      heartbeatOutgoing: 0,
      logRawCommunication: true,
      maxWebSocketChunkSize: 8 * 1024 * 1024,
      reconnectDelay: 1000,
    };

    this.stompClient = new Client(config);

    this.stompClient.onConnect = (frame) => {
      this.logger.trace(`Socket - onConnect`, frame);

      if (this.subscription) {
        this.subscription.unsubscribe();

        this.subscription = undefined;
      }

      this.subscription = this.stompClient?.subscribe(
        this.subscriptionURL,
        (message) => {
          try {
            const body = JSON.parse(message.body) as MessageBody;
            this.callback(body);
          } catch (error) {
            // eslint-disable-next-line no-console
            console.error(error);
          }
        },
        { id: this.id },
      );

      this.onSocketStatusChange(SocketState.OPEN);

      this.datadogService?.addAction('EventRelaySocketConnect', {
        frame,
        id: this.id,
        subscriptionURL: this.subscriptionURL,
        webSocketURL: this.webSocketURL,
      });

      this.send('/public/token', null, '');

      this.callback({
        date: new Date().getTime(),
        name: InternalEvents.SocketConnectedNotification,
        workitemId: this.id,
      });
    };

    this.stompClient.onDisconnect = (frame) => {
      this.logger.error(`Socket - onDisconnect - stompClientState [${this.stompClient?.state}]`);

      this.datadogService?.addAction('EventRelaySocketDisconnect', {
        frame,
        id: this.id,
        stompClientState: this.stompClient?.state,
        subscriptionURL: this.subscriptionURL,
        webSocketURL: this.webSocketURL,
      });

      this.callback({
        date: new Date().getTime(),
        name: InternalEvents.SocketDisconnectedNotification,
        workitemId: this.id,
      });
    };

    this.stompClient.onWebSocketClose = () => {
      this.logger.info(`Socket - onWebSocketClose - stompClientState [${this.stompClient?.state}]`);

      this.datadogService?.addAction('EventRelaySocketClose', {
        id: this.id,
        stompClientState: this.stompClient?.state,
        subscriptionURL: this.subscriptionURL,
        webSocketURL: this.webSocketURL,
      });

      if (this.subscription) {
        this.subscription.unsubscribe();

        this.subscription = null;
      }

      this.onSocketStatusChange(SocketState.CLOSED);

      this.callback({
        date: new Date().getTime(),
        name: InternalEvents.SocketClosedNotification,
        workitemId: this.id,
      });
    };

    this.stompClient.onWebSocketError = () => {
      this.logger.error(
        `Socket - onWebSocketError - stompClientState [${this.stompClient?.state}]`,
      );

      this.datadogService?.addAction('EventRelaySocketError', {
        id: this.id,
        stompClientState: this.stompClient?.state,
        subscriptionURL: this.subscriptionURL,
        webSocketURL: this.webSocketURL,
      });

      this.callback({
        date: new Date().getTime(),
        name: InternalEvents.SocketErrordNotification,
        workitemId: this.id,
      });
    };

    this.stompClient.onChangeState = (state: ActivationState) => {
      this.logger.info(`Socket - onChangeState - ActivationState changed to [${state}]`);

      this.callback({
        date: new Date().getTime(),
        name: InternalEvents.SocketStateChangedNotification,
        workitemId: this.id,
      });
    };

    this.stompClient.onStompError = (frame) => {
      this.logger.error(`Socket - onStompError`, frame);

      this.datadogService?.addAction('EventRelayStompError', {
        frame,
        id: this.id,
        stompClientState: this.stompClient?.state,
        subscriptionURL: this.subscriptionURL,
        webSocketURL: this.webSocketURL,
      });

      this.callback({
        date: new Date().getTime(),
        name: InternalEvents.SocketErrordNotification,
        workitemId: this.id,
      });
    };

    this.stompClient.activate();
  }

  /**
   * Disconnects the socket connection.
   *
   * @remarks
   * This method logs a message, unsubscribes from any active subscriptions, and deactivates the STOMP client.
   *
   * @returns A promise that resolves once the disconnection is complete.
   */
  public async disconnect() {
    this.logger.trace('Socket - disconnect');
    if (!this.stompClient) {
      return;
    }

    if (this.subscription) {
      this.subscription.unsubscribe();
    }

    await this.stompClient.deactivate();
  }

  private send(destination: string, headers: Record<string, string> | null, message: string): void {
    if (!this.stompClient) {
      return;
    }

    this.logger.debug(`Socket - sending ${this.id} to ${destination} message ${message}`);

    const _headers = {
      Authorization: this.getToken(),
      ...headers,
    };

    this.stompClient.publish({
      body: message || 'empty',
      destination: destination,
      headers: _headers,
    });
  }

  /**
   * Sends binary data to the specified destination.
   * @param destination - The destination to send the data to.
   * @param data - The binary data to send.
   */
  public sendBinary(destination: string, data: Uint8Array): void {
    if (!this.stompClient) {
      return;
    }
    // Logger.log(`Socket - destination ${ this.id } ${ destination } connected ${ this.stompClient.connected }`);

    this.stompClient.publish({
      binaryBody: data,
      body: '{}',
      destination,
      headers: {
        Authorization: this.getToken(),
        'content-type': 'application/octet-stream',
      },
    });
  }
}
