import { type SchemaLayout } from './schemalayout';

const schemaLayouts = new Map<string, SchemaLayout>();

/**
 * @deprecated SchemaLayouts is deprecated
 */
export const SchemaLayouts = {
  get(name: string): SchemaLayout | undefined {
    return schemaLayouts.get(name);
  },

  has(name: string): boolean {
    return schemaLayouts.has(name);
  },

  set(name: string, schemaLayout: SchemaLayout): void {
    schemaLayouts.set(name, schemaLayout);
  },

  values(): SchemaLayout[] {
    return Array.from(schemaLayouts.values());
  },
};
