  /**
   * Fetches the widgets for the user's home tabs.
   *
   * @returns An array of widgets.
   */
  public async fetchWidgets() {
    try {
      this.eventsService.emitExternal(EventTypes.InitFetchWidgets);

      const userHomeTabs = this.stateService.getUser()?.hometabs;
      const userProfileHomeTabs = this.stateService.getUserProfile()?.hometabs;

      let homeTabs: HomeTabObject[] = [];

      if (userProfileHomeTabs && userProfileHomeTabs.count > 0) {
        homeTabs = userProfileHomeTabs.objects ?? [];
      }

      if (userHomeTabs && userHomeTabs.count > 0) {
        homeTabs = userHomeTabs.objects ?? [];
      }

      const requests = homeTabs.map((homeTab) =>
        this.schemaTypeClient.retrieve('hometab', {
          createdAt: -1,
          id: homeTab.hometabId,
        }),
      );

      const response = await Promise.all(requests);

      const widgets = response
        .flatMap((homeTab) => homeTab.widgets?.objects ?? [])
        .map((homeTabWidget) => homeTabWidget.expansions?.widgetId)
        .filter((widgetId) => widgetId !== undefined);

      this.eventsService.emitInternal(InternalEvents.WidgetsDataNotification, widgets);

      this.eventsService.emitExternal(EventTypes.InitFetchWidgetsSuccess);

      return widgets;
    } catch (error) {
      this.eventsService.emitExternal(EventTypes.InitFetchWidgetsError);
    }

    return undefined;
  }

