import { dependencyInjectionContainer } from '../../internal';

export const DEFAULT_CONVERSATION_TIMELINE_LIMIT = 20;

export interface ConversationTimelineQueryOptionsParams {
  conversationId: string;
  limit?: number;
}

export function getConversationTimelineQueryOptions({
  conversationId,
  limit = DEFAULT_CONVERSATION_TIMELINE_LIMIT,
}: ConversationTimelineQueryOptionsParams) {
  const conversationService = dependencyInjectionContainer.resolve('conversationService');

  return {
    queryFn: async ({ pageParam }: { pageParam: number }) => {
      const response = await conversationService.fetchConversationTimeline({
        conversationId,
        limit,
        offset: pageParam,
      });

      return response;
    },
    queryKey: ['conversations', 'timeline', conversationId, limit],
  };
}
