import type { FetchQueryOptions } from '@tanstack/query-core';
import { dependencyInjectionContainer } from '../../internal';
import type { CopilotSession } from '../../types';
import { Logger } from '../logger';
import { queryClient } from '../queryClient';

export interface CopilotSessionsQueryData {
  hasMore: boolean;
  nextCursor: string | null;
  sessions: CopilotSession[];
  totalCount: number;
}

export function getCopilotSessionsQueryOptions() {
  return {
    queryFn: ({ client, queryKey }) => {
      const queryData = client.getQueryData<CopilotSessionsQueryData>(queryKey);

      Logger.log('getCopilotSessionsQueryOptions', 'Query invoked', {
        hasData: !!queryData,
        sessionCount: queryData?.sessions.length ?? 0,
      });

      // Only fetch if no cached data or cache is empty
      if (!queryData || queryData.sessions.length === 0) {
        const copilotService = dependencyInjectionContainer.resolve('copilotService');
        copilotService.fetchSessions({ limit: 20 }).catch((error: unknown) => {
          Logger.error('getCopilotSessionsQueryOptions - Error fetching sessions', error);
        });
      }

      // Return cached data if available, otherwise return empty state
      return queryData ?? {
        hasMore: true,
        nextCursor: null,
        sessions: [],
        totalCount: 0,
      };
    },
    queryKey: ['copilot', 'sessions'],
  } satisfies FetchQueryOptions<CopilotSessionsQueryData>;
}

/**
 * Get a session from the sessions list cache
 */
export function getCopilotSessionFromCache(
  sessionId: string,
): CopilotSession | undefined {
  const data = queryClient.getQueryData<CopilotSessionsQueryData>(['copilot', 'sessions']);
  return data?.sessions.find((s: CopilotSession) => s.sessionId === sessionId);
}
