import { type StateService } from '.';
import { type BaseDatadogService, type InjectionContainer } from '../internal';
import { type LogLevel } from '../types/logger';

const logLevels: LogLevel[] = ['trace', 'debug', 'info', 'warn', 'error', 'fatal'];
const formatSpecifiers = '%c%s%c%s';
const sdk = '[ncx-sdk]';
const sdkStyles = '';

export class LoggerService {
  public level?: LogLevel | false;

  private datadogService: BaseDatadogService | null;
  private stateService: StateService;

  constructor({
    datadogService,
    stateService,
  }: Pick<InjectionContainer, 'datadogService' | 'stateService'>) {
    this.datadogService = datadogService;
    this.stateService = stateService;
  }

  trace(...args: Parameters<typeof console.trace>) {
    this.log('trace', ...args);
  }

  debug(...args: Parameters<typeof console.debug>) {
    this.log('debug', ...args);
  }

  info(...args: Parameters<typeof console.info>) {
    this.log('info', ...args);
  }

  warn(...args: Parameters<typeof console.warn>) {
    this.log('warn', ...args);
  }

  error(...args: Parameters<typeof console.error>) {
    this.log('error', ...args);
  }

  fatal(...args: Parameters<typeof console.error>) {
    this.log('fatal', ...args);
  }

  setLevel(level: LogLevel) {
    this.level = level;
  }

  private log(level: LogLevel, ...args: Parameters<typeof console.log>) {
    if (!this.shouldLog(level)) {
      return;
    }

    const method = level === 'fatal' ? 'error' : level;
    const uppercaseLogLevel = level.toUpperCase();

    if (this.stateService.getPlatform() !== 'web') {
      // eslint-disable-next-line no-console
      console.log(
        formatSpecifiers,
        sdkStyles,
        sdk,
        uppercaseLogLevel,
        ...args,
      );
      return;
    } else {
      // eslint-disable-next-line no-console
      console[method](
        formatSpecifiers,
        sdkStyles,
        sdk,
        this.getLogLevelStyles(level),
        uppercaseLogLevel,
        ...args,
      );
    }

    // this.datadogService?.addAction(`SDK-${uppercaseLogLevel}-Log`, args);
    this.datadogService?.addLog(
      `${sdk} ${uppercaseLogLevel}`,
      {
        details: args.length > 1 ? args : undefined,
        message: args.length === 1 ? String(args[0]) : args.map(String).join(' '),
      },
      level as 'debug' | 'info' | 'warn' | 'error',
    );
  }

  private shouldLog(level: LogLevel) {
    if (!this.level) {
      return false;
    }

    if (this.level === 'trace' || level === this.level) {
      return true;
    }

    return (
      logLevels.findIndex((item) => item === level) >=
      logLevels.findIndex((item) => item === this.level)
    );
  }

  private getLogLevelStyles(level: LogLevel) {
    let backgroundColor: string;

    switch (level) {
      case 'trace':
        backgroundColor = '#424F81';
        break;
      case 'debug':
        backgroundColor = '#008763';
        break;
      case 'info':
        backgroundColor = '#0071FF';
        break;
      case 'warn':
        backgroundColor = '#ED6A21';
        break;
      case 'error':
        backgroundColor = '#D00041';
        break;
      case 'fatal':
        backgroundColor = '#C30025';
        break;
    }

    return `background-color: ${backgroundColor}; color: white; letter-spacing: 0.3em; padding: 4px; border-radius: 5px; margin: 7px`;
  }
}
