import { Logger, adjustComponent } from '../../utilities';
import { type DataService } from '../data';
import { Helper, type HelperInterface } from './base';

export class HelperType extends Helper {
  private static instance: HelperInterface;

  public static getInstance(language: string, dataService: DataService): HelperInterface {
    if (!this.instance) {
      this.instance = new HelperType(language, dataService);
    }

    return this.instance;
  }

  private constructor(
    protected override language: string,
    protected override dataService: DataService,
  ) {
    super(language, dataService);
  }

  public processData(model: any): void {
    // Logger.log(`ScehamType ${ schemaType.name }`, schemaType);

    if (model.name === 'realtimestats') {
      const statistics = model.fields.stats || {};

      Object.keys(statistics as object).forEach((statistic: string) => {
        const stat: any = statistics[statistic];

        Object.keys((stat.fields as object) || {}).forEach((fieldname: string) => {
          if (fieldname === 'statuses') {
            stat.fields[fieldname] = {
              fields: stat.fields[fieldname],
              label: fieldname,
              type: 'jsonObject',
            };

            Object.keys(stat.fields[fieldname].fields as object).forEach((fieldname2: string) => {
              stat.fields[fieldname].fields[fieldname2] = {
                fields: stat.fields[fieldname].fields[fieldname2],
                label: fieldname2,
                type: 'jsonObject',
              };
            });
          }
        });
      });
    }

    model.mappable = model.mappable === 1;

    this.adjustSchemaTypeFields(model.fields, model.definitions, model.localizable as any[]);
  }

  private adjustSchemaTypeFields(fields: any, definitions: any, localizable: any[]): void {
    Object.keys(fields as object).forEach((fieldname: string) => {
      let field: any = fields[fieldname];

      // eslint-disable-next-line no-prototype-builtins
      if (field.hasOwnProperty('_ref')) {
        /* _ref is a special tag to not repeast data */
        try {
          // eslint-disable-next-line @typescript-eslint/no-implied-eval
          const definition: any = new Function(
            'definitions',
            `return definitions.${field._ref.split('/').slice(2).join('.')}`,
          )(definitions);

          field = Object.assign(definition, field);
          delete field._ref;
        } catch (error) {
          Logger.log(`Reference error in schema ${field._ref}`, definitions);

          field.label = 'Reference error in schema';
          field.type = 'string';
        }
      }

      if (field.type === 'avatar') {
        // this.avatars[key] = model.fields[key];
      }

      // eslint-disable-next-line no-prototype-builtins
      if (!field.hasOwnProperty('subType')) {
        field.subType = null;
      }

      // eslint-disable-next-line no-prototype-builtins
      if (field.type === 'objectId' && field.hasOwnProperty('selection')) {
        field.type = 'query';
      }

      field.name = fieldname;
      field.mappable = field.mappable === 1;
      field.isLocalizable =
        localizable !== undefined && localizable !== null && localizable.includes(fieldname);
      field._component = field.type;

      if (field.type?.startsWith('jsonArray')) {
        const tmp = field.type.split(':');

        if (tmp.length === 2) {
          field.type = tmp[0];
          field.subType = tmp[1];

          if (field.subType === 'timeevent') {
            field.type = 'timeevent';
            field.subType = null;
          }
        } else if (
          !['queryFields', 'uniqueKey', 'localizable', 'relations', 'panels'].includes(fieldname)
        ) {
          field.type = 'query';
        }
      }

      if (field.type === 'jsonObject') {
        // this.complexFields.push(model.fields[key]);
      }

      // eslint-disable-next-line @typescript-eslint/no-unsafe-argument
      field._component = adjustComponent(field);

      // eslint-disable-next-line no-prototype-builtins
      if (field.hasOwnProperty('fields')) {
        this.adjustSchemaTypeFields(field.fields, definitions, localizable);
      }
    });
  }

  // private adjustFieldComponent(field: any): string {
  //     if ( ['percentage'].indexOf(field.type) > -1 ) { /* Should create those same type to remove the need of doing this */
  //         return 'progress';
  //     }

  //     if ( ['int', 'long', 'objectId', 'string'].indexOf(field.type) > -1 ) { /* Should create those same type to remove the need of doing this */
  //         return 'string';
  //     }

  //     return field.type;
  // }
}
