import { dependencyInjectionContainer } from '../../internal';
import { Logger, getUniqueIdAsString } from '../../utilities';
import { type DataService } from '../data';
import { Helper, type HelperInterface } from './base';

export class HelperHome extends Helper {
  private static instance: HelperInterface;

  private stateService = dependencyInjectionContainer.resolve('stateService');

  public static getInstance(language: string, dataService: DataService): HelperInterface {
    if (!this.instance) {
      this.instance = new HelperHome(language, dataService);
    }

    return this.instance;
  }

  private constructor(
    protected override language: string,
    protected override dataService: DataService,
  ) {
    super(language, dataService);
  }

  public processData(model: any): void {
    Logger.log(`HelperHome - processData ${model.name}`);

    if (!model) {
      return;
    }

    model.objectType = 'home';
    model.tenantId = this.stateService.getTenantId();
    model._id = getUniqueIdAsString();

    model.workitemlog = null;
    model.workitemlogsummary = {
      totalChat: -1,
      totalContactsLast30days: -1,
      totalContactsLast7days: -1,
      totalContactsToday: -1,
      totalEmail: -1,
      totalFax: -1,
      totalInbound: -1,
      totalOutbound: -1,
      totalPersonalCallback: -1,
      totalPredictive: -1,
      totalProgressive: -1,
      totalSMS: -1,
      totalSocial: -1,
    };

    model.personalcallbacks = null;
    model.personalcallbackssummary = {
      totalChat: -1,
      totalContactsLast30days: -1,
      totalContactsLast7days: -1,
      totalContactsToday: -1,
      totalEmail: -1,
      totalFax: -1,
      totalInbound: -1,
      totalOutbound: -1,
      totalPersonalCallback: -1,
      totalPredictive: -1,
      totalProgressive: -1,
      totalSMS: -1,
      totalSocial: -1,
    };
  }
}
