import { type InjectionContainer } from '../internal';
import type {
  CreateMSTeamsAccessRequestPayload,
  FetchMSTeamsAccessRequestPayload,
  FetchMSTeamsAccessRequestResponse,
  Integration,
  IntegrationAccount,
  MSTeamsAccessRequest,
  UpdateMSTeamsAccessRequestPayload,
  UserDetails,
} from '../types';
import { axiosInstance } from '../utilities';
import { type LoggerService } from './logger';

const REQUEST_ACCESS_URL = '/data/api/msteams/request/access';

export class IntegrationsService {
  private logger: LoggerService;

  constructor({ loggerService }: Pick<InjectionContainer, 'loggerService'>) {
    this.logger = loggerService;
  }

  public async createMSTeamsAccessRequest(payload: CreateMSTeamsAccessRequestPayload) {
    this.logger.debug(
      'IntegrationsService - createMSTeamsAccessRequest - invoked with payload:',
      payload,
    );
    return await axiosInstance.post<MSTeamsAccessRequest>(REQUEST_ACCESS_URL, payload);
  }

  public async fetchMSTeamsAccessRequests(payload: FetchMSTeamsAccessRequestPayload) {
    this.logger.debug(
      'IntegrationsService - fetchMSTeamsAccessRequests - invoked with payload:',
      payload,
    );
    return await axiosInstance.get<FetchMSTeamsAccessRequestResponse>(
      `${REQUEST_ACCESS_URL}/${payload.tenantId}`,
    );
  }

  public async updateMSTeamsAccessRequest(payload: UpdateMSTeamsAccessRequestPayload) {
    this.logger.debug(
      'IntegrationsService - replyMSTeamsAccessRequest - invoked with payload:',
      payload,
    );
    return await axiosInstance.patch<UserDetails>(`${REQUEST_ACCESS_URL}/status`, payload);
  }

  public async fetchIntegrations() {
    const { data } = await axiosInstance.get<Integration[]>('/npaas/mdm/api/integrations');
    return data;
  }

  public async fetchIntegrationAccounts() {
    const { data } = await axiosInstance.get<IntegrationAccount[]>(
      '/npaas/mdm/api/integrations/accounts',
    );
    return data;
  }

  public async disconnectIntegrationAccount(id: string, clearObjects?: boolean) {
    await axiosInstance.delete(`/npaas/mdm/api/integrations/accounts/${id}`, {
      params: { clearObjects: clearObjects ?? false },
    });
  }
}
