import type {
  Conversation,
  ConversationWorkitemsChannelFilter,
  ConversationWorkitemsResponse,
  EngagementData,
  FetchFeedPayload,
  Participant,
  Workitem,
} from '../../types';
import { type FetchQueryOptions, type QueryClient } from '@tanstack/query-core';
import { type ChannelType } from '../../models';
import { Logger } from '../logger';
import { dependencyInjectionContainer } from '../../internal';

export const MY_INBOX_ID = 'my-inbox';

export const CHANNEL_FILTER_TO_CHANNEL_TYPE: Record<
  ConversationWorkitemsChannelFilter,
  ChannelType[]
> = {
  email: ['email'],
  live_chat: ['chat'],
  phone: ['voice'],
  sms: ['sms', 'conversation'],
};

export function sortItems<T extends { createdAt: number }>(items: T[]) {
  return [...items].sort((a, b) => b.createdAt - a.createdAt);
}

export function filterLatestNItems<T extends { createdAt: number }>(items: T[], n: number) {
  const sortedItems = sortItems(items);
  return sortedItems.slice(0, n);
}

// Query key: ['conversations', 'push-feed', filter, tab, queueIds | 'my-inbox']
export interface ConversationsQueryData {
  engagementData: EngagementData[];
}

// Query key: ['conversations', 'workitems', conversationId]
export interface ConversationWorkitemsQueryData {
  workitems: Workitem[];
}

export interface ConversationsQueryOptionsParams {
  filter: FetchFeedPayload['filter'];
  queueIds?: FetchFeedPayload['queueIds'];
  tab: FetchFeedPayload['tab'];
}

export function getConversationsQueryOptions({
  filter,
  queueIds,
  tab,
}: ConversationsQueryOptionsParams) {
  const conversationService = dependencyInjectionContainer.resolve('conversationService');
  const stateService = dependencyInjectionContainer.resolve('stateService');

  return {
    queryFn: ({ client, queryKey }) => {
      const queryData = client.getQueryData<ConversationsQueryData>(queryKey);
      Logger.log(
        'getConversationsQueryOptions',
        'Fetching conversations',
        queryData,
        new Date().getTime(),
      );

      if (!queryData) {
        // No data trigger initial fetch for new conversation feed items
        conversationService
          .fetchFeed({
            fetch: 'newer',
            filter,
            includeWorkitems: true,
            limit: stateService.getConversationsCacheLimit().conversations,
            queueIds,
            tab,
            workitemsLimit: stateService.getConversationsCacheLimit().workitems,
          })
          .catch((error: unknown) => {
            Logger.error('getConversationsQueryOptions - Error fetching conversations feed', error);
          });

        return {
          engagementData: [],
        };
      } else {
        // TODO: Process data to get last modified timestamp
        let cursor = -1;

        queryData.engagementData.forEach((engagement) => {
          if (engagement.createdAt > cursor) {
            cursor = engagement.createdAt;
          }
        });

        const cursorValue = cursor > 0 ? cursor : undefined;

        // Only re-fetch if the cursor has changed since the last request (prevents redundant re-fetches
        // on StrictMode double-mount or when fetching older items doesn't change the newest cursor)
        if (conversationService.getLastRequestedCursor(filter, queueIds, tab) !== cursorValue) {
          // Trigger background fetch for new conversation feed items including the last modified timestamp as cursor
          conversationService
            .fetchFeed({
              cursor: cursorValue,
              fetch: 'newer',
              filter,
              includeWorkitems: true,
              limit: stateService.getConversationsCacheLimit().conversations,
              queueIds,
              tab,
              workitemsLimit: stateService.getConversationsCacheLimit().workitems,
            })
            .catch((error: unknown) => {
              Logger.error(
                'getConversationsQueryOptions - Error fetching conversations feed',
                error,
              );
            });
        }
      }

      const cacheLimit = stateService.getConversationsCacheLimit();
      // always on write do this if we want to limit the number of conversations persisted in cache
      // keep N most recent conversations

      const filteredEngagements = filterLatestNItems(
        queryData.engagementData,
        cacheLimit.conversations,
      );
      return {
        engagementData: filteredEngagements,
      };
    },
    queryKey: ['conversations', 'push-feed', filter, tab, queueIds ? queueIds : MY_INBOX_ID],
  } satisfies FetchQueryOptions<ConversationsQueryData>;
}

export function getWorkitemFromConversationsCache(
  conversationId: string,
  workitemId: string | undefined,
  client: QueryClient,
): Workitem | undefined {
  if (!workitemId) {
    return undefined;
  }
  const data = client.getQueryData<ConversationWorkitemsQueryData>([
    'conversations',
    'workitems',
    conversationId,
  ]);
  return data?.workitems.find((w) => w.workitemId === workitemId);
}

export function getConversationWorkitemsQueryOptions({
  conversationId,
}: {
  conversationId: string;
}) {
  return {
    queryFn: ({ client, queryKey }) => {
      const queryData = client.getQueryData<ConversationWorkitemsQueryData>(queryKey);
      Logger.log(
        'getConversationsQueryOptions',
        'Fetching conversations',
        queryData,
        new Date().getTime(),
      );

      if (!queryData) {
        return {
          workitems: [],
        };
      }

      const stateService = dependencyInjectionContainer.resolve('stateService');
      const cacheLimit = stateService.getConversationsCacheLimit();

      // always on write do this if we want to limit the number of workitems persisted in cache
      // keep N most recent workitems per conversation
      const limitedWorkitems = filterLatestNItems(queryData.workitems, cacheLimit.workitems);
      return {
        workitems: limitedWorkitems,
      };
    },
    queryKey: ['conversations', 'workitems', conversationId],
  } satisfies FetchQueryOptions<ConversationWorkitemsQueryData>;
}

// Query key: ['conversations', 'workitems-multi-scope', { queueIds, conversationIds, contactId, filter }]
export interface ConversationWorkitemsMultiScopeQueryData {
  conversations: Record<string, Conversation>;
  next: string | undefined;
  workitems: Workitem[];
}

export interface ConversationWorkitemsMultiScopeQueryKey {
  contactId: string | undefined;
  conversationIds: string[];
  filter: ConversationWorkitemsChannelFilter[] | undefined;
  queueIds: string[];
}

export function getConversationWorkitemsMultiScopeQueryOptions(
  params: ConversationWorkitemsMultiScopeQueryKey,
) {
  const conversationService = dependencyInjectionContainer.resolve('conversationService');

  return {
    queryFn: async ({ pageParam }: { pageParam: string | undefined }) => {
      const response = await conversationService.fetchV2ConversationsWorkitems({
        contactId: params.contactId,
        conversationIds: params.conversationIds.length ? params.conversationIds : undefined,
        cursor: pageParam,
        filter: params.filter?.length ? params.filter : undefined,
        queueIds: params.queueIds.length ? params.queueIds : undefined,
      });

      return response;
    },
    queryKey: [
      'conversations',
      'workitems-multi-scope',
      {
        contactId: params.contactId,
        conversationIds: [...params.conversationIds].sort(),
        filter: params.filter?.length ? [...params.filter].sort() : undefined,
        queueIds: [...params.queueIds].sort(),
      },
    ],
  };
}

export interface ConversationByQueueId {
  conversationId: string;
  participants: Participant[];
  workitems: Workitem[];
}

export function getConversationIdByQueueIdQueryOptions({
  contactId,
  queueId,
}: {
  contactId?: string;
  queueId: string;
}) {
  const conversationService = dependencyInjectionContainer.resolve('conversationService');

  return {
    queryFn: async (): Promise<ConversationByQueueId | null> => {
      // Cache-first: delegate to service method which reads the push-feed + workitems caches
      const cached = conversationService.getConversationIdsByQueueIds({
        filter: 'all',
        queueIds: [queueId],
        tab: 'all',
      });

      const cachedEntry =
        contactId !== undefined
          ? cached.find((entry) => entry.participants.some((p) => p.id === contactId))
          : undefined;

      if (cachedEntry) {
        return cachedEntry;
      }

      // API fallback
      let response: ConversationWorkitemsResponse;
      try {
        response = await conversationService.fetchV2ConversationsWorkitems({
          contactId,
          includeConversation: true,
          queueIds: [queueId],
        });
      } catch {
        return null;
      }

      const firstWorkitem = (response.objects ?? []).find((w) => {
        if (!w.conversationId) {
          return false;
        }
        const conversation = response.conversations?.[w.conversationId];
        return contactId === undefined || conversation?.contactId === contactId;
      });

      if (!firstWorkitem?.conversationId) {
        return null;
      }

      const conversation = response.conversations?.[firstWorkitem.conversationId];
      return {
        conversationId: firstWorkitem.conversationId,
        participants: conversation?.participants ?? [],
        workitems: response.objects ?? [],
      };
    },
    queryKey: ['conversations', 'conversationIdsByQueueIds', queueId, contactId],
  };
}
