import { type InjectionContainer } from '../internal';
import { ExternalEvents, InternalEvents, type BaseSchemaTypeClient } from '../models';
import type { ContactDetails, FetchContactsResponseBody, SchemaTypeSearchPayload } from '../types';
import { axiosInstance, ofType } from '../utilities';
import { type EventsService } from './eventsservice';
import { type LoggerService } from './logger';

export class ContactService {
  private eventsService: EventsService;
  private schemaTypeClient: BaseSchemaTypeClient;
  private logger: LoggerService;

  constructor({
    eventsService,
    loggerService,
    schemaTypeClient,
  }: Pick<InjectionContainer, 'eventsService' | 'schemaTypeClient' | 'loggerService'>) {
    this.eventsService = eventsService;
    this.schemaTypeClient = schemaTypeClient;
    this.logger = loggerService;
    this.handleContactImportNotification();
    this.handleContactImportFailureNotification();
  }

  private handleContactImportNotification() {
    this.eventsService.internalEvents$
      .pipe(ofType(InternalEvents.ContactImportNotificationEvent))
      .subscribe(({ data }) => {
        this.logger.debug('ContactService - handleContactImportNotification', data);
        this.eventsService.emitExternal(
          ExternalEvents.ContactImportNotificationEvent,
          data.message,
        );
      });
  }

  private handleContactImportFailureNotification() {
    this.eventsService.internalEvents$
      .pipe(ofType(InternalEvents.ContactImportFailureNotificationEvent))
      .subscribe(({ data }) => {
        this.logger.debug('ContactService - handleContactImportFailureNotification', data);
        this.eventsService.emitExternal(
          ExternalEvents.ContactImportFailureNotificationEvent,
          data.message,
        );
      });
  }

  /**
   * Blocks or unblocks a contact based on the provided block parameter (true to block, false to unblock).
   * @param block - Whether to block or unblock the contact.
   * @param contactId - The ID of the contact.
   */
  async block({ block, contactId }: { block: boolean; contactId: string }) {
    await axiosInstance.put(`/data/api/types/contact/${contactId}/blocked`, block);
  }

  /**
   * @deprecated Use sdk.getSchemaTypeClient().search('contact')
   */
  async fetchContacts(payload?: SchemaTypeSearchPayload): Promise<FetchContactsResponseBody> {
    this.logger.warn('ContactService - fetchContacts is deprecated');
    return this.schemaTypeClient.search('contact', payload);
  }

  /**
   * @deprecated Use sdk.getSchemaTypeClient().retrieve('contact', { id })
   */
  async fetchContact(id: string): Promise<ContactDetails> {
    this.logger.warn('ContactService - fetchContact is deprecated');
    return this.schemaTypeClient.retrieve('contact', { id });
  }
}
