import { type InjectionContainer } from '../internal';
import { type BaseSchemaTypeClient } from '../models';
import { type SchemaTypeSearchPayload } from '../types';
import { type LoggerService } from './logger';

/**
 * @deprecated FunctionsService is deprecated
 */
export class FunctionsService {
  private schemaTypeClient: BaseSchemaTypeClient;
  private logger: LoggerService;

  constructor({
    loggerService,
    schemaTypeClient,
  }: Pick<InjectionContainer, 'schemaTypeClient' | 'loggerService'>) {
    this.schemaTypeClient = schemaTypeClient;
    this.logger = loggerService;
  }
  /**
   * @deprecated Use sdk.getSchemaTypeClient().search('function')
   */
  async fetchFunctions(payload?: SchemaTypeSearchPayload) {
    this.logger.warn('FunctionsService - fetchFunctions is deprecated');
    return this.schemaTypeClient.search('function', payload);
  }
}
