// import { type TwilioRefreshTokenResponse } from '../types';
import { type InjectionContainer } from '../internal';
import { type LoggerService } from '../services/logger';
import type { MultiloginDevice, TelephonyConfig, UserDetails, UserSession } from '../types/user';
import { axiosInstance } from '../utilities';

export interface TelephonyInitParams {
  debug: boolean;
  edgeId: string | null;
  multiloginDevice: MultiloginDevice | undefined;
  session: UserSession | undefined;
  telephonyConfig: TelephonyConfig;
  user: UserDetails;
}

export abstract class AbstractTelephony {
  protected session: UserSession | undefined;
  protected user: UserDetails | undefined;
  protected multiloginDevice: MultiloginDevice | undefined;
  protected telephonyConfig: TelephonyConfig | undefined;
  protected edgeId: string | null | undefined;
  protected debug = false;
  protected isConnected = true;
  protected logger: LoggerService;

  protected audioOutputDeviceId?: string;
  protected audioInputDeviceId?: string;

  constructor({ loggerService }: Pick<InjectionContainer, 'loggerService'>) {
    this.logger = loggerService;
  }

  abstract init({
    debug,
    edgeId,
    multiloginDevice,
    session,
    telephonyConfig,
    user,
  }: TelephonyInitParams): Promise<void>;
  abstract activeConnection(): void;
  abstract close(): Promise<void>;
  abstract logout(): void;
  abstract hangup(): void;
  abstract disconnectAll(): void;
  abstract status(): void;
  abstract dtmf(digits: string): Promise<void>;

  /**
   * Resolves if able to switch the audio input device to the one specified by `deviceId`.
   * Throws when unsupported or error opening the MediaStream for the device.
   *
   * `deviceId` can be obtained from the list of devices provided by `NcxSdk.getTelephonyService().events$`
   * observable, or through the `useAvailableAudioDevices()` React hook that consumes that observable.
   *
   * @param deviceId - identifies the device to be selected as audio input
   */
  public updateAudioInputDevice(_deviceId: string): Promise<void> {
    return Promise.reject(new Error('Method not implemented.'));
  }
  /**
   * Resolves if able to switch the audio output device to the one specified by `deviceId`.
   * Throws when unsupported or error opening the MediaStream for the device.
   *
   * `deviceId` can be obtained from the list of devices provided by `NcxSdk.getTelephonyService().events$`
   * observable, or through the `useAvailableAudioDevices()` React hook that consumes that observable.
   *
   * @param deviceId - identifies the device to be selected as audio output
   */
  public updateAudioOutputDevice(_deviceId: string): Promise<void> {
    return Promise.reject(new Error('Method not implemented.'));
  }

  protected async refreshTelephonyToken() {
    const telephony = this.telephonyConfig;

    if (!telephony) {
      throw new Error('Missing telephony config.');
    }

    if (telephony.type !== 'WEBRTC') {
      throw new Error(`Cannot refresh token for type: ${telephony.type}.`);
    }

    if (!telephony.tokenRefreshUrl) {
      throw new Error(
        'Missing the token refresh URL in the telephony configuration of the session.',
      );
    }

    this.logger.debug('AbstractTelephony - refreshTelephonyToken', this.telephonyConfig);

    try {
      const response = await axiosInstance.get(telephony.tokenRefreshUrl);

      return response.data as unknown;
    } catch (error) {
      this.logger.error(`AbstractTelephony - refreshTelephonyToken - error`, error);

      throw error;
    }
  }

  public getSocketStatus() {
    return { isConnected: false, state: 'unknown' };
  }

  public reconnectSocket() {
    this.logger.warn('AbstractTelephony - reconnectSocket not implemented');
  }

  public networkReconnection() {
    this.logger.warn('AbstractTelephony - networkReconnection not implemented');
  }

  public set isOnline(value: boolean) {
    this.isConnected = value;
  }

  public get isOnline(): boolean {
    return this.isConnected;
  }

  public checkToken(): Promise<boolean> {
    return Promise.resolve(true);
  }
}
