import { type InjectionContainer } from '../internal/dependencyInjectionContainer';
import { type BaseSchemaTypeClient } from '../models';
import { type StateService } from '../services/state';
import { type TenantEntitlement, type UserEntitlements } from '../types';
import { type LoggerService } from './logger';

export class EntitlementsService {
  private stateService: StateService;
  private schemaTypeClient: BaseSchemaTypeClient;
  private logger: LoggerService;

  constructor({
    loggerService,
    schemaTypeClient,
    stateService,
  }: Pick<
    InjectionContainer,
    'eventsService' | 'stateService' | 'schemaTypeClient' | 'loggerService'
  >) {
    this.stateService = stateService;
    this.schemaTypeClient = schemaTypeClient;
    this.logger = loggerService;
  }

  async fetchUserEntitlements(): Promise<UserEntitlements[]> {
    this.logger.trace('EntitlementsService - fetchUserEntitlements');
    const hasUserEntitlementSchemaType = this.schemaTypeClient.has('entitlementsuserentitlement');

    if (!hasUserEntitlementSchemaType) {
      return [];
    }

    const data = await this.schemaTypeClient.search<UserEntitlements>(
      'entitlementsuserentitlement',
      { q: '*' },
    );
    this.stateService.setUserEntitlements(data.objects ?? []);
    return data.objects ?? [];
  }

  async fetchTenantEntitlements(): Promise<TenantEntitlement[]> {
    this.logger.trace('EntitlementsService - fetchTenantEntitlements');
    const hasTenantEntitlementSchemaType = this.schemaTypeClient.has(
      'entitlementstenantentitlement',
    );

    if (!hasTenantEntitlementSchemaType) {
      return [];
    }

    const data = await this.schemaTypeClient.search<TenantEntitlement>(
      'entitlementstenantentitlement',
      { q: '*' },
    );
    this.stateService.setTenantEntitlements(data.objects ?? []);
    return data.objects ?? [];
  }

  private hasEveryEntitlement(
    expectedEntitlements: string[],
    entitlements: UserEntitlements[] | TenantEntitlement[],
  ): boolean {
    return expectedEntitlements.every((expected) => {
      return entitlements.some((entitlement) => {
        return entitlement.assignedFeatures.includes(expected);
      });
    });
  }

  userHasEntitlements(expectedEntitlements: string[] | Set<string>): boolean {
    const entitlements = this.stateService.getUserEntitlements();
    const expected =
      expectedEntitlements instanceof Set ? expectedEntitlements : new Set(expectedEntitlements);

    return this.hasEveryEntitlement(Array.from(expected), entitlements ?? []);
  }

  tenantHasEntitlements(expectedEntitlements: string[] | Set<string>): boolean {
    const entitlements = this.stateService.getTenantEntitlements();
    const expected =
      expectedEntitlements instanceof Set ? expectedEntitlements : new Set(expectedEntitlements);

    return this.hasEveryEntitlement(Array.from(expected), entitlements ?? []);
  }

  private hasSomeEntitlements(
    expectedEntitlements: string[],
    entitlements: UserEntitlements[] | TenantEntitlement[],
  ): boolean {
    return expectedEntitlements.some((expected) => {
      return entitlements.some((entitlement) => {
        return entitlement.assignedFeatures.includes(expected);
      });
    });
  }

  hasSomeUserEntitlements(expectedEntitlements: string[] | Set<string>): boolean {
    const entitlements = this.stateService.getUserEntitlements();
    const expected =
      expectedEntitlements instanceof Set ? expectedEntitlements : new Set(expectedEntitlements);

    return this.hasSomeEntitlements(Array.from(expected), entitlements ?? []);
  }

  hasSomeTenantEntitlements(expectedEntitlements: string[] | Set<string>): boolean {
    const entitlements = this.stateService.getTenantEntitlements();
    const expected =
      expectedEntitlements instanceof Set ? expectedEntitlements : new Set(expectedEntitlements);

    return this.hasSomeEntitlements(Array.from(expected), entitlements ?? []);
  }
}
