import {
  experimental_createQueryPersister,
  type PersistedQuery,
} from '@tanstack/query-persist-client-core';
import { type BaseAsyncStorageService, type InjectionContainer } from '../internal';
import { CACHE_BUSTER_VERSION } from '../models';

export type QueryPersister = ReturnType<typeof experimental_createQueryPersister>;

export interface BasePersisterClient {
  createQueryPersister(userID: string, enableEcryption: boolean): QueryPersister;
  dispose(): void;
  getQueryPersister(): QueryPersister | undefined;
}

export class PersisterClient {
  private asyncStorageService: BaseAsyncStorageService;
  private persister?: QueryPersister;

  constructor({ asyncStorageService }: Pick<InjectionContainer, 'asyncStorageService'>) {
    this.asyncStorageService = asyncStorageService;
  }

  public createQueryPersister(userID: string, encrypted: boolean): QueryPersister {
    const asyncStorage = this.asyncStorageService.createAsyncStorage({
      encryptionKey: encrypted ? userID : undefined,
      name: `ncx-sdk-cache-${userID}`,
    });

    const persister = experimental_createQueryPersister<PersistedQuery>({
      buster: `version=${CACHE_BUSTER_VERSION}, encrypted=${encrypted}`,
      deserialize: (cached) => cached,
      // change buster version when there's a breaking change to a persisted data structure
      maxAge: Infinity,
      serialize: (persistedQuery) => persistedQuery,
      storage: asyncStorage,
    });

    this.persister = persister;
    return this.persister;
  }

  public getQueryPersister(): QueryPersister | undefined {
    return this.persister;
  }

  dispose() {
    this.persister = undefined;
  }
}
