import { type InjectionContainer } from '../internal';
import { type BaseSchemaTypeClient } from '../models';
import { type UserDetails, type Queues } from '../types';
import { type StateService } from './state';

const resolveFlag = (value: unknown): boolean | undefined => {
  switch (value) {
    case 'on':
    case 'true':
    case true:
      return true;
    case 'off':
    case 'false':
    case false:
      return false;
    default:
      return undefined;
  }
};

