const isFetchTicketByTicketIdPayload = (
  payload: FetchTicketByTicketIdPayload | FetchTicketByWorkitemIdPayload,
): payload is FetchTicketByTicketIdPayload => {
  if (Object.hasOwn(payload, 'ticketId')) {
    return true;
  }
  return false;
};

