  private handleSupervisorTicketUpdateNotification() {
    this.eventsService.internalEvents$
      .pipe(ofType(InternalEvents.SupervisorTicketUpdateNotification))
      .subscribe((event) => {
        this.logger.debug('BaseTicketService - handleSupervisorTicketUpdateNotification', event);

        this.eventsService.emitExternal(
          ExternalEvents.SupervisorTicketUpdateNotification,
          event.data,
        );
      });
  }

