  /**
   * Fetches workitems from the server.
   * @returns A promise that resolves to a response of workitems.
   * @deprecated Use schemaTypeClient.request method instead.
   */
  async fetchWorkitems(payload?: FetchWorkItemsRequestBody) {
    this.logger.warn(
      'BaseTicketService - fetchWorkitems is deprecated and will be removed in a future version',
    );
    this.logger.debug('BaseTicketService - fetchWorkitems', payload);

    // Inititalize with default values
    let apiParsedBody: APIParsedFetchWorkItemsRequestBody = {
      q: '*',
      rows: 10,
      start: 0,
    };

    if (payload) {
      const { agentIds, currentSources, inboxIds, statuses, ...singleValueFilters } = payload;
      apiParsedBody = {
        ...apiParsedBody,
        ...singleValueFilters,
        agentId: agentIds?.join(',') ?? undefined,
        currentSource: currentSources?.join(',') ?? undefined,
        latestQueueId: inboxIds?.join(',') ?? undefined,
        status: statuses?.join(',') ?? undefined,
      };
    }

    // /data/api/types/workitems/find
    const url = this.schemaTypeClient.getLinkURI('ticket', 'findandsearch');

    const response = await axiosInstance.post<FetchWorkitemsResponseBody>(url, apiParsedBody);
    return response.data;
  }

