import type { FetchQueryOptions } from '@tanstack/query-core';
import { dependencyInjectionContainer } from '../../internal';
import type { CopilotMessage } from '../../types';
import { Logger } from '../logger';
import { queryClient } from '../queryClient';

export interface CopilotSessionQueryData {
  hasMore: boolean;
  messages: CopilotMessage[];
  nextCursor: string | null;
  sessionId: string;
  title: string;
}

export function getCopilotSessionQueryOptions({ sessionId }: { sessionId: string }) {
  return {
    queryFn: ({ client, queryKey }) => {
      const queryData = client.getQueryData<CopilotSessionQueryData>(queryKey);

      Logger.log('getCopilotSessionQueryOptions', 'Query invoked', {
        hasData: !!queryData,
        messageCount: queryData?.messages.length ?? 0,
        sessionId,
      });

      // Only fetch if no cached data or cache is empty
      if (!queryData || queryData.messages.length === 0) {
        const copilotService = dependencyInjectionContainer.resolve('copilotService');

        // Fetch session metadata
        copilotService.fetchSession({ sessionId }).catch((error: unknown) => {
          Logger.error('getCopilotSessionQueryOptions - Error fetching session metadata', error);
        });

        // Fetch session messages (separate endpoint with cursor pagination)
        copilotService.fetchSessionMessages({ limit: 50, sessionId }).catch((error: unknown) => {
          Logger.error('getCopilotSessionQueryOptions - Error fetching session messages', error);
        });
      }

      // Return cached data if available, otherwise return empty state
      return queryData ?? {
        hasMore: true,
        messages: [],
        nextCursor: null,
        sessionId,
        title: '',
      };
    },
    queryKey: ['copilot', 'session', sessionId],
  } satisfies FetchQueryOptions<CopilotSessionQueryData>;
}

/**
 * Get a message from a session cache
 */
export function getCopilotMessageFromCache(
  sessionId: string,
  messageId: string,
): CopilotMessage | undefined {
  const data = queryClient.getQueryData<CopilotSessionQueryData>([
    'copilot',
    'session',
    sessionId,
  ]);
  return data?.messages.find((m: CopilotMessage) => m.messageId === messageId);
}
