import type { QueryKey } from '@tanstack/query-core';
import { axiosInstance } from '../../utilities/axios';
import { queryClient, ofType } from '../../utilities';
import { ExternalEvents, InternalEvents } from '../../models';
import { type InjectionContainer } from '../dependencyInjectionContainer';
import type { EventsService, StateService, LoggerService } from '../../services';
import type {
  CopilotSession,
  CopilotMessage,
  FetchCopilotSessionsPayload,
  FetchCopilotSessionsResponse,
  FetchCopilotSessionPayload,
  FetchCopilotSessionResponse,
  FetchCopilotSessionMessagesPayload,
  FetchCopilotSessionMessagesResponse,
  CursorPagination,
  CreateCopilotSessionPayload,
  CreateCopilotSessionResponse,
  RenameCopilotSessionPayload,
  SendCopilotMessagePayload,
  SendCopilotMessageResponse,
  CopilotSessionCreatedData,
  CopilotSessionUpdatedData,
  CopilotSessionDeletedData,
  CopilotStreamStartData,
  CopilotStreamChunkData,
  CopilotStreamDoneData,
  CopilotStreamErrorData,
} from '../../types';
import type {
  CopilotSessionsQueryData,
} from '../../utilities/queries/getCopilotSessionsQueryOptions';
import type {
  CopilotSessionQueryData,
} from '../../utilities/queries/getCopilotSessionQueryOptions';

// Track streaming state for accumulating chunks
interface ActiveStream {
  chunks: Map<number, string>;
  messageId: string;
  sessionId: string; // sequence -> text
  startedAt: number;
}

export class BaseCopilotService {
  private queryCacheUnsubscribe?: () => void;
  protected stateService: StateService;
  protected eventsService: EventsService;
  protected logger: LoggerService;
  private sessionsLoading = false;
  private sessionLoadingStates = new Map<string, boolean>();
  // Track active streams by messageId
  private activeStreams = new Map<string, ActiveStream>();

  constructor({
    eventsService,
    loggerService,
    stateService,
  }: Pick<InjectionContainer, 'stateService' | 'eventsService' | 'loggerService'>) {
    loggerService.trace('BaseCopilotService - constructor');

    this.stateService = stateService;
    this.eventsService = eventsService;
    this.logger = loggerService;

    // Subscribe to WebSocket events
    this.handleSessionCreatedNotification();
    this.handleSessionUpdatedNotification();
    this.handleSessionDeletedNotification();
    this.handleStreamStartNotification();
    this.handleStreamChunkNotification();
    this.handleStreamDoneNotification();
    this.handleStreamErrorNotification();

    // Subscribe to query cache changes
    this.subscribeToQueryCacheChanges();
  }

  // ============================================
  // Public API Methods
  // ============================================

  public async fetchSessions(
    params: FetchCopilotSessionsPayload = {}
  ): Promise<FetchCopilotSessionsResponse> {
    const { before, limit = 20 } = params;
    const isInitialLoad = !before;

    this.logger.info('BaseCopilotService - fetchSessions', { before, isInitialLoad, limit });
    this.setSessionsLoading(true);

    try {
      const response = await axiosInstance.get<FetchCopilotSessionsResponse>(
        '/cxfabric/api/copilot/sessions',
        { params: { before, limit } }
      );

      const { pagination, sessions, totalCount } = response.data;

      // Update cache - replace on initial load, append on subsequent loads
      this.updateSessionsCache(sessions, isInitialLoad ? 'replace' : 'append', pagination, totalCount);

      this.logger.info('BaseCopilotService - fetchSessions success', {
        hasMore: pagination.hasMore,
        nextCursor: pagination.nextCursor,
        sessionCount: sessions.length,
        totalCount,
      });

      return response.data;
    } catch (error) {
      this.logger.error('BaseCopilotService - fetchSessions error', error);
      throw error;
    } finally {
      this.setSessionsLoading(false);
    }
  }

  public async fetchSession(
    params: FetchCopilotSessionPayload
  ): Promise<FetchCopilotSessionResponse> {
    const { sessionId } = params;

    this.logger.info('BaseCopilotService - fetchSession', { sessionId });

    try {
      const response = await axiosInstance.get<FetchCopilotSessionResponse>(
        `/cxfabric/api/copilot/sessions/${sessionId}`
      );

      const session = response.data;

      // Update session title in the messages cache if it exists
      this.updateSessionTitleInCache(sessionId, session.title);

      this.logger.info('BaseCopilotService - fetchSession success', {
        messageCount: session.messageCount,
        sessionId,
        title: session.title,
      });

      return response.data;
    } catch (error) {
      this.logger.error('BaseCopilotService - fetchSession error', error);
      throw error;
    }
  }

  public async fetchSessionMessages(
    params: FetchCopilotSessionMessagesPayload
  ): Promise<FetchCopilotSessionMessagesResponse> {
    const { before, limit = 50, sessionId } = params;
    const isInitialLoad = !before;

    this.logger.info('BaseCopilotService - fetchSessionMessages', { before, isInitialLoad, limit, sessionId });
    this.setSessionLoading(sessionId, true);

    try {
      const response = await axiosInstance.get<FetchCopilotSessionMessagesResponse>(
        `/cxfabric/api/copilot/sessions/${sessionId}/messages`,
        { params: { before, limit } }
      );

      const { messages, pagination } = response.data;

      // Update cache - replace on initial load, prepend older messages on subsequent loads
      this.updateSessionMessagesCache(sessionId, messages, isInitialLoad ? 'replace' : 'prepend', pagination);

      this.logger.info('BaseCopilotService - fetchSessionMessages success', {
        hasMore: pagination.hasMore,
        messageCount: messages.length,
        nextCursor: pagination.nextCursor,
        sessionId,
      });

      return response.data;
    } catch (error) {
      this.logger.error('BaseCopilotService - fetchSessionMessages error', error);
      throw error;
    } finally {
      this.setSessionLoading(sessionId, false);
    }
  }

  public async createSession(
    params: CreateCopilotSessionPayload = {}
  ): Promise<CreateCopilotSessionResponse> {
    this.logger.info('BaseCopilotService - createSession', params);

    try {
      const response = await axiosInstance.post<CreateCopilotSessionResponse>(
        '/cxfabric/api/copilot/sessions',
        params
      );

      // Session will be added to cache via CopilotSessionCreatedNotification
      this.logger.info('BaseCopilotService - createSession success', response.data);

      return response.data;
    } catch (error) {
      this.logger.error('BaseCopilotService - createSession error', error);
      throw error;
    }
  }

  public async renameSession(
    params: RenameCopilotSessionPayload
  ): Promise<CopilotSession> {
    const { sessionId, title } = params;

    this.logger.info('BaseCopilotService - renameSession', { sessionId, title });

    try {
      const response = await axiosInstance.patch<CopilotSession>(
        `/cxfabric/api/copilot/sessions/${sessionId}`,
        { title }
      );

      // Session will be updated in cache via CopilotSessionUpdatedNotification
      this.logger.info('BaseCopilotService - renameSession success', response.data);

      return response.data;
    } catch (error) {
      this.logger.error('BaseCopilotService - renameSession error', error);
      throw error;
    }
  }

  public async deleteSession(sessionId: string): Promise<void> {
    this.logger.info('BaseCopilotService - deleteSession', { sessionId });

    try {
      await axiosInstance.delete(`/cxfabric/api/copilot/sessions/${sessionId}`);

      // Session will be removed from cache via CopilotSessionDeletedNotification
      this.logger.info('BaseCopilotService - deleteSession success', { sessionId });
    } catch (error) {
      this.logger.error('BaseCopilotService - deleteSession error', error);
      throw error;
    }
  }

  public async sendMessage(
    params: SendCopilotMessagePayload
  ): Promise<SendCopilotMessageResponse> {
    const { message, mode = 'AUTO', sessionId } = params;

    this.logger.info('BaseCopilotService - sendMessage', { messageLength: message.length, mode, sessionId });

    try {
      const response = await axiosInstance.post<SendCopilotMessageResponse>(
        '/cxfabric/api/copilot/chat',
        { message, mode, sessionId }
      );

      const { messageId, sessionId: responseSessionId } = response.data;

      // Add user message to cache immediately (optimistic update)
      const userMessage: CopilotMessage = {
        content: message,
        createdAt: new Date().toISOString(),
        messageId,
        role: 'user',
      };
      this.addMessageToSessionCache(responseSessionId, userMessage);

      this.logger.info('BaseCopilotService - sendMessage success', { messageId, sessionId: responseSessionId });

      return response.data;
    } catch (error) {
      this.logger.error('BaseCopilotService - sendMessage error', error);
      throw error;
    }
  }

  // ============================================
  // Loading State
  // ============================================

  public isSessionsLoading(): boolean {
    return this.sessionsLoading;
  }

  public isSessionLoading(sessionId: string): boolean {
    return this.sessionLoadingStates.get(sessionId) ?? false;
  }

  private setSessionsLoading(isLoading: boolean): void {
    this.sessionsLoading = isLoading;
    this.eventsService.emitExternal(ExternalEvents.CopilotSessionsLoadingChanged, {
      isLoading,
    });
  }

  private setSessionLoading(sessionId: string, isLoading: boolean): void {
    this.sessionLoadingStates.set(sessionId, isLoading);
    this.eventsService.emitExternal(ExternalEvents.CopilotSessionLoadingChanged, {
      isLoading,
      sessionId,
    });
  }

  // ============================================
  // Cache Management - Sessions List
  // ============================================

  private updateSessionsCache(
    sessions: CopilotSession[],
    mode: 'replace' | 'append',
    pagination: CursorPagination,
    totalCount: number
  ): void {
    const queryKey: QueryKey = ['copilot', 'sessions'];

    queryClient.setQueryData<CopilotSessionsQueryData>(queryKey, (old) => {
      let mergedSessions: CopilotSession[];

      if (mode === 'replace' || !old) {
        mergedSessions = sessions;
      } else {
        // Append and deduplicate
        const existingIds = new Set(old.sessions.map((s) => s.sessionId));
        const newSessions = sessions.filter((s) => !existingIds.has(s.sessionId));
        mergedSessions = [...old.sessions, ...newSessions];
      }

      // Sort by lastActivity descending
      mergedSessions.sort(
        (a, b) => new Date(b.lastActivity).getTime() - new Date(a.lastActivity).getTime()
      );

      return {
        hasMore: pagination.hasMore,
        nextCursor: pagination.nextCursor,
        sessions: mergedSessions,
        totalCount,
      };
    });
  }

  private addSessionToCache(session: CopilotSession): void {
    const queryKey: QueryKey = ['copilot', 'sessions'];

    queryClient.setQueryData<CopilotSessionsQueryData>(queryKey, (old) => {
      if (!old) {
        return {
          hasMore: false,
          nextCursor: null,
          sessions: [session],
          totalCount: 1,
        };
      }

      // Check if already exists
      if (old.sessions.some((s) => s.sessionId === session.sessionId)) {
        return old;
      }

      // Add to beginning and sort
      const newSessions = [session, ...old.sessions].sort(
        (a, b) => new Date(b.lastActivity).getTime() - new Date(a.lastActivity).getTime()
      );

      return {
        ...old,
        sessions: newSessions,
        totalCount: old.totalCount + 1,
      };
    });
  }

  private updateSessionInCache(sessionData: Partial<CopilotSession> & { sessionId: string }): void {
    const queryKey: QueryKey = ['copilot', 'sessions'];

    queryClient.setQueryData<CopilotSessionsQueryData>(queryKey, (old) => {
      if (!old) return old;

      const updatedSessions = old.sessions.map((s) =>
        s.sessionId === sessionData.sessionId ? { ...s, ...sessionData } : s
      );

      // Re-sort after update
      updatedSessions.sort(
        (a, b) => new Date(b.lastActivity).getTime() - new Date(a.lastActivity).getTime()
      );

      return {
        ...old,
        sessions: updatedSessions,
      };
    });
  }

  private removeSessionFromCache(sessionId: string): void {
    const queryKey: QueryKey = ['copilot', 'sessions'];

    queryClient.setQueryData<CopilotSessionsQueryData>(queryKey, (old) => {
      if (!old) return old;

      const sessionExists = old.sessions.some((s) => s.sessionId === sessionId);

      return {
        ...old,
        sessions: old.sessions.filter((s) => s.sessionId !== sessionId),
        totalCount: sessionExists ? old.totalCount - 1 : old.totalCount,
      };
    });

    // Also remove the session messages cache
    queryClient.removeQueries({ queryKey: ['copilot', 'session', sessionId] });
  }

  // ============================================
  // Cache Management - Session Messages
  // ============================================

  private updateSessionTitleInCache(sessionId: string, title: string): void {
    const queryKey: QueryKey = ['copilot', 'session', sessionId];

    queryClient.setQueryData<CopilotSessionQueryData>(queryKey, (old) => {
      if (!old) return old;
      return { ...old, title };
    });
  }

  private updateSessionMessagesCache(
    sessionId: string,
    messages: CopilotMessage[],
    mode: 'replace' | 'prepend',
    pagination: CursorPagination
  ): void {
    const queryKey: QueryKey = ['copilot', 'session', sessionId];

    queryClient.setQueryData<CopilotSessionQueryData>(queryKey, (old) => {
      let mergedMessages: CopilotMessage[];

      if (mode === 'replace' || !old) {
        mergedMessages = messages;
      } else {
        // Prepend older messages (for "load more" when scrolling up)
        // When loading older messages, merge and let the sort handle ordering
        const existingIds = new Set(old.messages.map((m) => m.messageId));
        const newMessages = messages.filter((m) => !existingIds.has(m.messageId));
        mergedMessages = [...newMessages, ...old.messages];
      }

      // Sort by createdAt ascending (oldest first - chat UI shows oldest at top, newest at bottom)
      mergedMessages.sort(
        (a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
      );

      return {
        hasMore: pagination.hasMore,
        messages: mergedMessages,
        nextCursor: pagination.nextCursor,
        sessionId,
        title: old?.title ?? '',
      };
    });
  }

  private addMessageToSessionCache(sessionId: string, message: CopilotMessage): void {
    const queryKey: QueryKey = ['copilot', 'session', sessionId];

    queryClient.setQueryData<CopilotSessionQueryData>(queryKey, (old) => {
      if (!old) {
        return {
          hasMore: false,
          messages: [message],
          nextCursor: null,
          sessionId,
          title: '',
        };
      }

      // Check if already exists
      if (old.messages.some((m) => m.messageId === message.messageId)) {
        return old;
      }

      // Append to end (newest at bottom for chat UI)
      const newMessages = [...old.messages, message];

      return {
        ...old,
        messages: newMessages,
      };
    });
  }

  // ============================================
  // Query Cache Subscription
  // ============================================

  private subscribeToQueryCacheChanges(): void {
    const queryCache = queryClient.getQueryCache();

    this.queryCacheUnsubscribe = queryCache.subscribe((event) => {
      if (event.type !== 'updated') {
        return;
      }

      const query = event.query;
      const queryKey = query.queryKey as QueryKey;

      // Check if this is a copilot sessions query
      if (
        Array.isArray(queryKey) &&
        queryKey[0] === 'copilot' &&
        queryKey[1] === 'sessions'
      ) {
        this.eventsService.emitExternal(ExternalEvents.CopilotSessionsQueryUpdated, {
          queryKey,
        });
      }

      // Check if this is a copilot session query
      if (
        Array.isArray(queryKey) &&
        queryKey[0] === 'copilot' &&
        queryKey[1] === 'session' &&
        typeof queryKey[2] === 'string'
      ) {
        this.eventsService.emitExternal(ExternalEvents.CopilotSessionQueryUpdated, {
          queryKey,
          sessionId: queryKey[2],
        });
      }
    });
  }

  // ============================================
  // WebSocket Event Handlers - Session Lifecycle
  // ============================================

  private handleSessionCreatedNotification(): void {
    this.eventsService.internalEvents$
      .pipe(ofType(InternalEvents.CopilotSessionCreatedNotification))
      .subscribe((event) => {
        const data = event.data as CopilotSessionCreatedData;
        this.logger.debug('BaseCopilotService - SessionCreated', data);

        const session: CopilotSession = {
          createdAt: data.createdAt,
          lastActivity: data.createdAt,
          lastMessagePreview: data.lastMessagePreview,
          messageCount: 0,
          sessionId: data.sessionId,
          title: data.title,
          userId: data.userId,
        };

        this.addSessionToCache(session);

        // Emit external event
        this.eventsService.emitExternal(
          ExternalEvents.CopilotSessionCreatedNotification,
          data
        );
      });
  }

  private handleSessionUpdatedNotification(): void {
    this.eventsService.internalEvents$
      .pipe(ofType(InternalEvents.CopilotSessionUpdatedNotification))
      .subscribe((event) => {
        const data = event.data as CopilotSessionUpdatedData;
        this.logger.debug('BaseCopilotService - SessionUpdated', data);

        this.updateSessionInCache({
          lastActivity: data.lastActivity,
          lastMessagePreview: data.lastMessagePreview,
          messageCount: data.messageCount,
          sessionId: data.sessionId,
          title: data.title,
        });

        // Also update the session query cache title
        const sessionQueryKey: QueryKey = ['copilot', 'session', data.sessionId];
        queryClient.setQueryData<CopilotSessionQueryData>(sessionQueryKey, (old) => {
          if (!old) return old;
          return { ...old, title: data.title };
        });

        // Emit external event
        this.eventsService.emitExternal(
          ExternalEvents.CopilotSessionUpdatedNotification,
          data
        );
      });
  }

  private handleSessionDeletedNotification(): void {
    this.eventsService.internalEvents$
      .pipe(ofType(InternalEvents.CopilotSessionDeletedNotification))
      .subscribe((event) => {
        const data = event.data as CopilotSessionDeletedData;
        this.logger.debug('BaseCopilotService - SessionDeleted', data);

        this.removeSessionFromCache(data.sessionId);

        // Emit external event
        this.eventsService.emitExternal(
          ExternalEvents.CopilotSessionDeletedNotification,
          data
        );
      });
  }

  // ============================================
  // WebSocket Event Handlers - Stream
  // ============================================

  private handleStreamStartNotification(): void {
    this.eventsService.internalEvents$
      .pipe(ofType(InternalEvents.CopilotStreamStartNotification))
      .subscribe((event) => {
        const data = event.data as CopilotStreamStartData;
        this.logger.debug('BaseCopilotService - StreamStart', data);

        // Initialize active stream to accumulate chunks
        this.activeStreams.set(data.messageId, {
          chunks: new Map(),
          messageId: data.messageId,
          sessionId: data.sessionId,
          startedAt: Date.now(),
        });

        // Emit external event for hooks to consume
        this.eventsService.emitExternal(
          ExternalEvents.CopilotStreamStartNotification,
          data
        );
      });
  }

  private handleStreamChunkNotification(): void {
    this.eventsService.internalEvents$
      .pipe(ofType(InternalEvents.CopilotStreamChunkNotification))
      .subscribe((event) => {
        const data = event.data as CopilotStreamChunkData;
        this.logger.trace('BaseCopilotService - StreamChunk', {
          sequence: data.sequence,
          sessionId: data.sessionId,
          textLength: data.text.length,
        });

        // Store chunk in active stream
        const activeStream = this.activeStreams.get(data.messageId);
        if (activeStream) {
          activeStream.chunks.set(data.sequence, data.text);
        }

        // Emit external event for hooks to consume
        this.eventsService.emitExternal(
          ExternalEvents.CopilotStreamChunkNotification,
          data
        );
      });
  }

  private handleStreamDoneNotification(): void {
    this.eventsService.internalEvents$
      .pipe(ofType(InternalEvents.CopilotStreamDoneNotification))
      .subscribe((event) => {
        const data = event.data as CopilotStreamDoneData;
        this.logger.debug('BaseCopilotService - StreamDone', data);

        // Build complete message from accumulated chunks and add to cache
        const activeStream = this.activeStreams.get(data.messageId);
        if (activeStream) {
          const content = this.buildContentFromChunks(activeStream.chunks);

          const assistantMessage: CopilotMessage = {
            content,
            createdAt: new Date().toISOString(),
            messageId: data.messageId,
            role: 'assistant',
          };

          this.addMessageToSessionCache(activeStream.sessionId, assistantMessage);

          this.logger.debug('BaseCopilotService - Added streamed message to cache', {
            contentLength: content.length,
            messageId: data.messageId,
            sessionId: activeStream.sessionId,
          });

          // Clean up active stream
          this.activeStreams.delete(data.messageId);
        }

        // Emit external event for hooks to consume
        this.eventsService.emitExternal(
          ExternalEvents.CopilotStreamDoneNotification,
          data
        );
      });
  }

  private handleStreamErrorNotification(): void {
    this.eventsService.internalEvents$
      .pipe(ofType(InternalEvents.CopilotStreamErrorNotification))
      .subscribe((event) => {
        const data = event.data as CopilotStreamErrorData;
        this.logger.error('BaseCopilotService - StreamError', data);

        // Clean up active stream on error
        this.activeStreams.delete(data.messageId);

        // Emit external event for hooks to consume
        this.eventsService.emitExternal(
          ExternalEvents.CopilotStreamErrorNotification,
          data
        );
      });
  }

  // ============================================
  // Stream Helpers
  // ============================================

  private buildContentFromChunks(chunks: Map<number, string>): string {
    if (chunks.size === 0) return '';

    // Get all sequences sorted
    const sequences = Array.from(chunks.keys()).sort((a, b) => a - b);

    // Concatenate in order
    return sequences.map((seq) => chunks.get(seq) ?? '').join('');
  }

  // ============================================
  // Cleanup
  // ============================================

  public destroy(): void {
    if (this.queryCacheUnsubscribe) {
      this.queryCacheUnsubscribe();
      this.queryCacheUnsubscribe = undefined;
    }
    this.sessionLoadingStates.clear();
    this.activeStreams.clear();
    this.logger.trace('BaseCopilotService - destroyed');
  }
}
