  private getFieldFromSchemaType(name: string, fieldname: string): any {
    const schemaType = this.dataService.getSchemaType(name);

    return schemaType
      ? schemaType.getFields().find((field: any) => field.name === fieldname)
      : null;
  }

  // @ts-ignore implicit any
  private adjustFields(fields): void {
    // Logger.log('HelperLayout - adjustFields - in', fields);

    fields.forEach((field: any) => {
      if (field.title) {
        field.title.label = field.label = this.dataService.adjustLabel(
          this.language,
          field.title.label,
          field.title.label as string,
        );
        field.type = 'title';
      } else {
        Object.assign(
          field,
          this.getFieldFromSchemaType(field.schema as string, field.name as string),
          field,
        );

        if (field.format) {
          field.type = field.format;
        }

        field.label = this.dataService.adjustLabel(
          this.language,
          field.label,
          field.label as string,
        );

        (field.actions || []).forEach((action: any) => {
          (action.context || []).forEach((context: any) => {
            if (context.label) {
              context.label = this.dataService.adjustLabel(
                this.language,
                context.label,
                context.label as string,
              );
            }
          });

          (action.options || []).forEach((option: any) => {
            if (option.label) {
              option.label = this.dataService.adjustLabel(
                this.language,
                option.label,
                option.label as string,
              );
            }
          });
        });

        // eslint-disable-next-line no-prototype-builtins
        if (!field.hasOwnProperty('readOnly')) {
          field.readOnly = false;
        }
      }

      if (!field.containerClass) {
        field.containerClass = 'normal';
      } else {
        if (field.type === 'html') {
          field.containerClass = 'full-height';
        }

        if (field.type === 'title') {
          field.containerClass = field.type;
        }
      }

      // eslint-disable-next-line @typescript-eslint/no-unsafe-argument
      field._component = adjustComponent(field);
      field._hasCondition = field.conditions !== null && field.conditions !== undefined;
      field._show = true;
    });

    // Logger.log('HelperLayout - adjustFields - out', fields);
  }

  private adjustHeaders(headers: any, fields: any[]): void {
    for (let i = 0; i < headers.length; i++) {
      const header: any = headers[i];

      // eslint-disable-next-line no-prototype-builtins
      if (header.hasOwnProperty('label')) {
        headers[i] = this.dataService.adjustLabel(this.language, header.label, 'Unknown');
        // eslint-disable-next-line no-prototype-builtins
      } else if (header.hasOwnProperty('name') && header.hasOwnProperty('schema')) {
        // @ts-expect-error
        const properties: any = this.dataService
          .getSchemaType(header.schema as string)
          .getField(header.name as string);
        headers[i] = this.dataService.adjustLabel(this.language, properties?.label, 'Unknown');
      } else {
        const tmp: any = fields.find((field: any) => field.name === header);
        headers[i] = tmp?.label || header || 'Unknown';
      }
    }
  }

