import { type BasePersisterClient, type StateService } from '../services';
import type {
  SchemaTypeSearchPayload,
  SchemaTypeRetrievePayload,
  SchemaTypeLinkName,
  SchemaTypeLink,
  SchemaTypeName,
  SearchableSchemaType,
  RetrievableSchemaType,
  Replacements,
  SchemaTypeSearchResponseBody,
  SchemaTypeRetrieveResponseBody,
  SchemaTypeDeletePayload,
  BaseSchemaTypeUpdatePayload,
  BaseSchemaTypeCreatePayload,
  SchemaTypeUpdateResponseBody,
  UpdatableSchemaType,
  CreatableSchemaType,
  SchemaTypeCreateResponseBody,
  ISchemaType,
  DeletableSchemaType,
  SchemaTypeDeleteResponseBody,
  SchemaTypeDownloadPayload,
  SchemaTypeDownloadResponseBody,
  DownloadableSchemaType,
  SchemaTypeRequestResponseBody,
  BaseSchemaTypeRequestOptions,
  UserDetails,
  SchemaTypeRequestLinkNames,
  BaseSchemaObject,
} from '../types';
import { axiosInstance, queryClient } from '../utilities';
import { type BaseLocalStorageService, type InjectionContainer } from '../internal';
import { isUserObject, normalizeUserQueues } from '../utilities/guards/user';
import { type LoggerService } from '../services/logger';

const REPLACEABLE_PATH_VALUE_REGEX = /\{?\{[a-z]+\}\}?/gi;

export class BaseSchemaTypeClient {
  private stateService: StateService;
  private localStorageService: BaseLocalStorageService;
  private persisterClient: BasePersisterClient;
  private logger: LoggerService;
  constructor({
    localStorageService,
    loggerService,
    persisterClient,
    stateService,
  }: Pick<
    InjectionContainer,
    'stateService' | 'localStorageService' | 'persisterClient' | 'loggerService'
  >) {
    this.stateService = stateService;
    this.localStorageService = localStorageService;
    this.persisterClient = persisterClient;
    this.logger = loggerService;
  }

  has(name: string) {
    return this.stateService.getSchemaTypeMap().has(name);
  }

  search<TResponse = void, const TName extends SearchableSchemaType = SearchableSchemaType>(
    name: TName,
    payload?: SchemaTypeSearchPayload,
  ): Promise<SchemaTypeSearchResponseBody<TName, TResponse>>;
  search<TResponse = void, const TName extends string = string>(
    name: TName,
    payload?: SchemaTypeSearchPayload,
  ): Promise<SchemaTypeSearchResponseBody<TName, TResponse>>;
  async search<TResponse = void, const TName extends string = string>(
    name: string,
    { q = '', queryParams, rows = 100, start = 0 }: SchemaTypeSearchPayload = {},
  ): Promise<SchemaTypeSearchResponseBody<TName, TResponse>> {
    if (!this.stateService.canSearch(name)) {
      throw new Error(`Permission denied search ${name}`);
    }

    this.logger.debug(`SchemaTypeClient - search - schemaTypeName [${name}]`);

    const uri = this.getLinkURI(name, 'search');

    const params = {
      ...queryParams,
      q,
      rows,
      start,
    };

    const response = await axiosInstance.get<SchemaTypeSearchResponseBody<TName, TResponse>>(uri, {
      params,
    });
    return response.data;
  }

  create<TResponse = void, const TName extends CreatableSchemaType = CreatableSchemaType>(
    name: TName,
    payload: BaseSchemaTypeCreatePayload,
  ): Promise<SchemaTypeCreateResponseBody<TName, TResponse>>;
  create<TResponse = void, const TName extends string = string>(
    name: TName,
    payload: BaseSchemaTypeCreatePayload,
  ): Promise<SchemaTypeCreateResponseBody<TName, TResponse>>;
  async create<TResponse = void, const TName extends string = string>(
    name: string,
    payload: BaseSchemaTypeCreatePayload,
  ): Promise<SchemaTypeCreateResponseBody<TName, TResponse>> {
    this.logger.debug(`SchemaTypeClient - create - schemaTypeName [${name}] and payload`, payload);
    const { file } = payload;
    let { data } = payload;
    const uri = this.getLinkURI(name, 'create');
    const contentType = this.getLinkContentType(name, 'create');
    const isFormDataRequired = contentType === 'multipart/form-data';

    data = this.fixLocalizableFields(name, data);

    let formData: FormData | undefined;
    const headers = new AxiosHeaders();

    if (isFormDataRequired) {
      headers.setContentType('multipart/form-data');
      formData = new FormData();
      formData.append('object', JSON.stringify(data));

      if (file) {
        formData.append('file_file', file);
      }
    }

    const response = await axiosInstance.post<SchemaTypeCreateResponseBody<TName, TResponse>>(
      uri,
      formData ?? data,
      { headers },
    );
    return response.data;
  }

  retrieve<TResponse = void, const TName extends RetrievableSchemaType = RetrievableSchemaType>(
    name: TName,
    payload: SchemaTypeRetrievePayload,
  ): Promise<SchemaTypeRetrieveResponseBody<TName, TResponse>>;
  retrieve<TResponse = void, const TName extends string = string>(
    name: TName,
    payload: SchemaTypeRetrievePayload,
  ): Promise<SchemaTypeRetrieveResponseBody<TName, TResponse>>;
  async retrieve<TResponse = void, const TName extends string = string>(
    name: TName,
    payload: SchemaTypeRetrievePayload,
  ): Promise<SchemaTypeRetrieveResponseBody<TName, TResponse>> {
    this.logger.debug(
      `SchemaTypeClient - retrieve - schemaTypeName [${name}] and payload`,
      payload,
    );
    const uri = this.getLinkURI(name, 'retrieve', { ...payload });

    const isStaticDataRequest =
      (name === 'user' && this.stateService.getUserId() === payload.id) ||
      (name === 'userprofile' && this.stateService.getUserProfileId() === payload.id) ||
      (name === 'tenant' && this.stateService.getTenantId() === payload.id);

    let data: SchemaTypeRetrieveResponseBody<TName, TResponse>;

    if (isStaticDataRequest) {
      try {
        data = await queryClient.ensureQueryData({
          queryFn: async ({ client, queryKey }) => {
            const queryData = client.getQueryData<BaseSchemaObject>(queryKey);

            const response = await axiosInstance.get<BaseSchemaObject>(uri, {
              params: {
                ifModifiedSince: queryData?.modifiedAt ? queryData.modifiedAt : undefined,
              },
            });

            if (response.status === 304) {
              if (isUserObject(queryData)) {
                let localDevices: UserDetails['settings']['devices'] | undefined;

                try {
                  localDevices = (await this.localStorageService.getObjectValue(
                    'user.settings.devices',
                  )) as UserDetails['settings']['devices'];
                } catch (error: unknown) {
                  this.logger.error(
                    'SchemaTypeClient - retrieve - error retrieving devices from local storage:',
                    error,
                  );
                }
                queryData.settings.devices = {
                  ...(queryData.settings.devices ?? {}),
                  ...(localDevices ?? {}),
                };
                queryData.queues = normalizeUserQueues(queryData.queues);
              }
              return queryData! as SchemaTypeRetrieveResponseBody<TName, TResponse>;
            }

            if (isUserObject(response.data)) {
              let localDevices: UserDetails['settings']['devices'] | undefined;

              try {
                localDevices = (await this.localStorageService.getObjectValue(
                  'user.settings.devices',
                )) as UserDetails['settings']['devices'];
              } catch (error: unknown) {
                this.logger.error(
                  'SchemaTypeClient - retrieve - error retrieving devices from local storage:',
                  error,
                );
              }

              const queryDataDevices = isUserObject(queryData)
                ? queryData.settings.devices
                : undefined;
              response.data.settings.devices = {
                ...(queryDataDevices ?? {}),
                ...(localDevices ?? {}),
              };
              response.data.queues = normalizeUserQueues(response.data.queues);
            }

            return response.data as SchemaTypeRetrieveResponseBody<TName, TResponse>;
          },
          queryKey: ['static', name],
          revalidateIfStale: true,
        });
      } catch (error: unknown) {
        this.logger.error(
          'SchemaTypeClient - retrieve - error retrieving static data from queryClient:',
          error,
        );
        throw error;
      }
    } else {
      const response =
        await axiosInstance.get<SchemaTypeRetrieveResponseBody<TName, TResponse>>(uri);
      data = response.data;
    }
    /*
    const { id } = payload;

    if (name === 'user' && this.stateService.getUserId() === id) {
      const userDetails = { ...data } as UserDetails;
      const localDevices = (await this.localStorageService.getObjectValue(
        'user.settings.devices',
      )) as UserDetails['settings']['devices'];
      if (localDevices) {
        userDetails.settings.devices = { ...userDetails.settings.devices, ...localDevices };
      }
      this.stateService.setUser(userDetails);
    }
    */
    return data;
  }

  download<TResponse = void, const TName extends DownloadableSchemaType = DownloadableSchemaType>(
    name: TName,
    payload: SchemaTypeDownloadPayload,
  ): Promise<SchemaTypeDownloadResponseBody<TName, TResponse>>;
  download<TResponse = void, const TName extends string = string>(
    name: TName,
    payload: SchemaTypeDownloadPayload,
  ): Promise<SchemaTypeDownloadResponseBody<TName, TResponse>>;
  async download<TResponse = void, const TName extends string = string>(
    name: TName,
    payload: SchemaTypeDownloadPayload,
  ): Promise<SchemaTypeDownloadResponseBody<TName, TResponse>> {
    const uri = this.getLinkURI(name, 'download', { ...payload });
    const response = await axiosInstance.get<SchemaTypeDownloadResponseBody<TName, TResponse>>(uri);
    return response.data;
  }

  delete<TResponse = void, const TName extends DeletableSchemaType = DeletableSchemaType>(
    name: TName,
    payload: SchemaTypeDeletePayload,
  ): Promise<SchemaTypeDeleteResponseBody<TName, TResponse>>;
  delete<TResponse = void, const TName extends string = string>(
    name: TName,
    payload: SchemaTypeDeletePayload,
  ): Promise<SchemaTypeDeleteResponseBody<TName, TResponse>>;
  async delete<TResponse = void, const TName extends string = string>(
    name: string,
    payload: SchemaTypeDeletePayload,
  ): Promise<SchemaTypeDeleteResponseBody<TName, TResponse>> {
    this.logger.debug(
      `SchemaTypeClient - delete - schemaTypeName [${name}] with id [${payload.id}]`,
      payload,
    );
    const uri = this.getLinkURI(name, 'delete', { ...payload });
    const response =
      await axiosInstance.delete<SchemaTypeDeleteResponseBody<TName, TResponse>>(uri);
    return response.data;
  }

  update<TResponse = void, const TName extends UpdatableSchemaType = UpdatableSchemaType>(
    name: TName,
    payload: BaseSchemaTypeUpdatePayload,
  ): Promise<SchemaTypeUpdateResponseBody<TName, TResponse>>;
  update<TResponse = void, const TName extends string = string>(
    name: TName,
    payload: BaseSchemaTypeUpdatePayload,
  ): Promise<SchemaTypeUpdateResponseBody<TName, TResponse>>;
  async update<TResponse = void, const TName extends string = string>(
    name: TName,
    payload: BaseSchemaTypeUpdatePayload,
  ): Promise<SchemaTypeUpdateResponseBody<TName, TResponse>> {
    this.logger.debug(`SchemaTypeClient - update - schemaTypeName [${name}] and payload`, payload);
    const { createdAt, file, filesMetadata, id } = payload;
    let { data } = payload;

    const uri = this.getLinkURI(name, 'update', { createdAt, id });
    const contentType = this.getLinkContentType(name, 'update');
    const isFormDataRequired = contentType === 'multipart/form-data';

    data = this.fixLocalizableFields(name, data);

    let response: AxiosResponse<SchemaTypeUpdateResponseBody<TName, TResponse>> | undefined;
    let localUserDevices: UserDetails['settings']['devices'] | undefined;

    const queryKey = ['static', name];
    const shouldOptimisticallyUpdateUser = name === 'user' && this.stateService.getUserId() === id;

    if (shouldOptimisticallyUpdateUser) {
      const userDetails = data as Partial<UserDetails>;
      if (userDetails.settings?.devices) {
        try {
          await this.localStorageService.upsertObjectValue<UserDetails['settings']['devices']>(
            'user.settings.devices',
            {
              ...userDetails.settings.devices,
            },
          );
          localUserDevices = userDetails.settings.devices;
        } catch (error: unknown) {
          this.logger.error(
            'SchemaTypeClient - update - error saving devices to local storage:',
            error,
          );
        }
        delete userDetails.settings.devices;
      } else {
        try {
          localUserDevices = (await this.localStorageService.getObjectValue(
            'user.settings.devices',
          )) as UserDetails['settings']['devices'] | undefined;
        } catch (error) {
          this.logger.error(
            'SchemaTypeClient - update - error retrieving devices from local storage:',
            error,
          );
        }
      }
    }

    const backupUserData = shouldOptimisticallyUpdateUser
      ? queryClient.getQueryData<UserDetails>(queryKey)
      : undefined;

    if (backupUserData) {
      queryClient.setQueryData<UserDetails>(queryKey, {
        ...backupUserData,
        ...(data as Partial<UserDetails>),
        settings: {
          ...backupUserData.settings,
          ...((data as Partial<UserDetails>).settings ?? {}),
          devices: {
            ...(backupUserData.settings.devices ?? {}),
            ...(localUserDevices ?? {}),
          },
        },
      });
    }

    try {
      if (isFormDataRequired) {
        const formData = new FormData();
        formData.append('fieldModifiers', JSON.stringify(data));

        if (filesMetadata) {
          formData.append('filesMetadata', JSON.stringify(filesMetadata));
        }

        if (file) {
          formData.append('file_file', file);
        }

        response = await axiosInstance.post<SchemaTypeUpdateResponseBody<TName, TResponse>>(
          uri,
          formData,
          {
            headers: {
              'Content-Type': contentType,
            },
          },
        );
      } else {
        response = await axiosInstance.patch<SchemaTypeUpdateResponseBody<TName, TResponse>>(
          uri,
          data,
        );
      }
    } catch (error: unknown) {
      if (backupUserData) {
        const backupDataWithDevices: UserDetails = {
          ...backupUserData,
          settings: {
            ...backupUserData.settings,
            devices: {
              ...(backupUserData.settings.devices ?? {}),
              ...(localUserDevices ?? {}),
            },
          },
        };
        queryClient.setQueryData<UserDetails>(queryKey, backupDataWithDevices);
      }
      throw error;
    }

    const currentQueryData = queryClient.getQueryData<BaseSchemaObject | BaseSchemaObject[]>(
      queryKey,
    );

    if (!currentQueryData) {
      if (isUserObject(response.data) && this.stateService.getUserId() === id) {
        response.data.settings.devices = {
          ...(response.data.settings.devices ?? {}),
          ...(localUserDevices ?? {}),
        };
        response.data.queues = normalizeUserQueues(response.data.queues);
      }
      return response.data;
    }

    let newQueryData: BaseSchemaObject | BaseSchemaObject[] | undefined;

    const newData = response.data as BaseSchemaObject;

    if (Array.isArray(currentQueryData)) {
      newQueryData = currentQueryData.map((object) =>
        object._id === newData._id ? newData : object,
      );
    } else if (currentQueryData._id === newData._id) {
      newQueryData = newData;

      if (isUserObject(currentQueryData) && isUserObject(newQueryData)) {
        newQueryData.settings.devices = {
          ...(currentQueryData.settings.devices ?? {}),
          ...(localUserDevices ?? {}),
        };
        newQueryData.queues = normalizeUserQueues(newQueryData.queues);
      }
    }

    if (newQueryData) {
      queryClient.setQueryData(queryKey, newQueryData);

      const persister = this.persisterClient.getQueryPersister();
      persister?.persistQueryByKey(queryKey, queryClient).catch((error: unknown) => {
        this.logger.error('SchemaTypeClient - update - persister error: ', error);
      });
    }

    /*
    if (name === 'user' && this.stateService.getUserId() === id) {
      const userDetails = { ...response.data } as UserDetails;
      try {
        const localDevices = (await this.localStorageService.getObjectValue(
          'user.settings.devices',
        )) as UserDetails['settings']['devices'];
        if (localDevices) {
          userDetails.settings.devices = {
            ...userDetails.settings.devices,
            ...localDevices,
          };
        }
      } catch (error: unknown) {
        this.logger.error(
          'SchemaTypeClient - update - error retrieving data from local storage:',
          error,
        );
      }
      this.stateService.setUser(userDetails);
    } else if (name === 'userprofile' && this.stateService.getUserProfileId() === id) {
      this.stateService.setUserProfile(response.data as UserProfile);
    } else if (name === 'disposition') {
      const dispositions = this.stateService.getDispositions();

      if (dispositions) {
        const newDispositions = dispositions.map((disposition) => {
          if (disposition._id === id) {
            return response.data as Disposition;
          }

          return disposition;
        });
        this.stateService.setDispositions(newDispositions);
      }
    } else if (name === 'campaign') {
      const campaigns = this.stateService.getCampaigns();

      if (campaigns) {
        const newCampaigns = campaigns.map((campaign) => {
          if (campaign._id === id) {
            return response.data as Campaign;
          }

          return campaign;
        });
        this.stateService.setCampaigns(newCampaigns);
      }
    } else if (name === 'status') {
      const statuses = this.stateService.getStatuses();

      if (statuses) {
        const newStatuses = statuses.map((status) => {
          if (status._id === id) {
            return response.data as Status;
          }

          return status;
        });
        this.stateService.setStatuses(newStatuses);
      }
    }
    */
    return response.data;
  }

  getLink(schemaTypeName: SchemaTypeName, linkName: SchemaTypeLinkName): SchemaTypeLink | undefined;
  getLink(schemaTypeName: string, linkName: string): SchemaTypeLink | undefined;
  getLink(schemaTypeName: string, linkName: string) {
    const map = this.stateService.getSchemaTypeMap();
    const schemaType = map.get(schemaTypeName);

    return schemaType?.links[linkName];
  }

  getLinkURI(
    schemaTypeName: SchemaTypeName,
    linkName: SchemaTypeLinkName,
    replacements?: Replacements,
  ): string;
  getLinkURI(schemaTypeName: string, linkName: string, replacements?: Replacements): string;
  getLinkURI(schemaTypeName: string, linkName: string, replacements?: Replacements): string {
    const link = this.getLink(schemaTypeName, linkName);
    const uri = link?.uri;

    if (!uri) {
      throw new Error(`Expected to find ${schemaTypeName} Schema Type with ${linkName} Link URI.`);
    }

    let newURI = uri;

    const matches = uri.match(REPLACEABLE_PATH_VALUE_REGEX);

    matches?.forEach((match) => {
      const path = match.replaceAll('{', '').replaceAll('}', '');
      const value = replacements?.[path];

      if (!value) {
        throw new Error(
          `Expected ${match} to be replaced in ${uri}. The replacement value must be passed to getLinkURI()`,
        );
      }

      const stringifiedValue = typeof value === 'string' ? value : JSON.stringify(value);
      newURI = newURI.replace(match, stringifiedValue);
    });

    return newURI;
  }

  getLinkContentType(schemaTypeName: SchemaTypeName, linkName: SchemaTypeLinkName): string;
  getLinkContentType(schemaTypeName: string, linkName: string): string;
  getLinkContentType(schemaTypeName: string, linkName: string): string {
    const link = this.getLink(schemaTypeName, linkName);
    const contentType = link?.contentType;

    if (!contentType) {
      throw new Error(`Expected to find ${schemaTypeName} Schema Type with ${linkName} Link`);
    }

    return contentType;
  }

  /**
   * Perform a request defined in the links of a Schema.
   *
   * @param schemaTypeName - The Schema's name, e.g. `contact`, `workitem`
   * @param linkName - The Schema link that will give the URI for the request. **Common links** include `create`, `retrieve`, `update`, `delete`, `search` and `download`. Other links are **custom**.
   * @param options - Options for the request. Different options are used for custom and common links.
   * @param options.data - The body to be sent in the request. Only for **custom links**.
   * @param options.files - Any files to be attached to the request body, will change the request body to FormData and append each file as `file`. Only for **custom links**.
   * @param options.queryParams - The query parameters to be sent in the request. Only for **custom links**.
   * @param options.replacements - The replacements to be made in the link URI. Only for **custom links**.
   * @param options.headers - The headers to be sent in the request. Only for **custom links**.
   * @param options.method - The HTTP method to be used. Only for **custom links**.
   * @param options.payload - The payload for the request. Only for **common links** specified above.
   *
   * @returns The response body of the request.
   */
  request<
    TResponse = void,
    const TName extends SchemaTypeName = SchemaTypeName,
    const TSchemaTypeLinkName extends
      SchemaTypeRequestLinkNames<TName> = SchemaTypeRequestLinkNames<TName>,
    TFile = Parameters<FormData['append']>[1],
  >(
    schemaTypeName: TName,
    linkName: TSchemaTypeLinkName,
    options: BaseSchemaTypeRequestOptions<TName, TSchemaTypeLinkName, TFile>,
  ): Promise<SchemaTypeRequestResponseBody<TName, TSchemaTypeLinkName, TResponse>>;
  request<
    TResponse = void,
    const TName extends string = string,
    const TSchemaTypeLinkName extends string = string,
    TFile = Parameters<FormData['append']>[1],
  >(
    schemaTypeName: TName,
    linkName: TSchemaTypeLinkName,
    options: BaseSchemaTypeRequestOptions<TName, TSchemaTypeLinkName, TFile>,
  ): Promise<SchemaTypeRequestResponseBody<TName, TSchemaTypeLinkName, TResponse>>;
  async request<
    TResponse = void,
    const TName extends string = string,
    const TSchemaTypeLinkName extends string = string,
    TFile = Parameters<FormData['append']>[1],
  >(
    schemaTypeName: TName,
    linkName: TSchemaTypeLinkName,
    options: BaseSchemaTypeRequestOptions<TName, TSchemaTypeLinkName, TFile>,
  ): Promise<SchemaTypeRequestResponseBody<TName, TSchemaTypeLinkName, TResponse>> {
    this.logger.debug(
      `SchemaTypeClient - request - schemaTypeName [${schemaTypeName}] linkName [${linkName}] and payload`,
      options,
    );
    if (linkName === 'create') {
      const response = (await this.create(
        schemaTypeName,
        options.payload as BaseSchemaTypeCreatePayload,
      )) as SchemaTypeRequestResponseBody<TName, TSchemaTypeLinkName, TResponse>;
      return response;
    } else if (linkName === 'retrieve') {
      const response = (await this.retrieve(
        schemaTypeName,
        options.payload as SchemaTypeRetrievePayload,
      )) as SchemaTypeRequestResponseBody<TName, TSchemaTypeLinkName, TResponse>;
      return response;
    } else if (linkName === 'update') {
      const response = (await this.update(
        schemaTypeName,
        options.payload as BaseSchemaTypeUpdatePayload,
      )) as SchemaTypeRequestResponseBody<TName, TSchemaTypeLinkName, TResponse>;
      return response;
    } else if (linkName === 'delete') {
      const response = (await this.delete(
        schemaTypeName,
        options.payload as SchemaTypeDeletePayload,
      )) as SchemaTypeRequestResponseBody<TName, TSchemaTypeLinkName, TResponse>;
      return response;
    } else if (linkName === 'search') {
      const response = (await this.search(
        schemaTypeName,
        options.payload as SchemaTypeSearchPayload,
      )) as SchemaTypeRequestResponseBody<TName, TSchemaTypeLinkName, TResponse>;
      return response;
    } else if (linkName === 'download') {
      const response = (await this.download(
        schemaTypeName,
        options.payload as SchemaTypeDownloadPayload,
      )) as SchemaTypeRequestResponseBody<TName, TSchemaTypeLinkName, TResponse>;
      return response;
    }
    const httpMethod = options.method ?? (options.data ? 'post' : 'get');
    const uri = this.getLinkURI(schemaTypeName, linkName, options.replacements);

    const contentType = this.getLinkContentType(schemaTypeName, linkName);
    const isFormDataRequired =
      !options.jsonOverride &&
      contentType === 'multipart/form-data' &&
      httpMethod !== 'get' &&
      httpMethod !== 'GET';

    let formData: FormData | undefined;
    const headers = new AxiosHeaders();

    if (options.headers) {
      for (const header of Object.keys(options.headers)) {
        headers.set(header, options.headers[header]);
      }
    }

    if ((isFormDataRequired && options.data) || options.files?.length) {
      headers.setContentType('multipart/form-data');
      formData = new FormData();
      if (schemaTypeName === 'contact' && linkName === 'import' && options.data?.['file']) {
        for (const key in options.data) {
          if (options.data[key] === undefined || options.data[key] === null) {
            continue; // will not send if the value is undefined or null
          }
          if (typeof options.data[key] == 'string' || key == 'file') {
            formData.append(key, options.data[key] as FormDataEntryValue);
          } else {
            formData.append(key, JSON.stringify(options.data[key]));
          }
        }
      } else {
        if (options.files && options.files.length > 0) {
          for (const file of options.files) {
            formData.append('file', file as File);
          }
        }
        if (options.data) {
          formData.append('object', JSON.stringify(options.data));
        }
      }
    }

    const response = await axiosInstance<
      SchemaTypeRequestResponseBody<TName, TSchemaTypeLinkName, TResponse>
    >({
      data: formData ?? options.data,
      headers,
      method: httpMethod,
      params: options.queryParams,
      url: uri,
    });
    return response.data;
  }

  get(schemaTypeName: string): ISchemaType {
    const map = this.stateService.getSchemaTypeMap();
    const schemaType = map.get(schemaTypeName);

    if (!schemaType) {
      throw new Error(`Expected to find ${schemaTypeName} Schema Type`);
    }

    return schemaType;
  }

  private fixLocalizableFields(schemaTypeName: string, data: Record<string, unknown>) {
    const schemaType = this.get(schemaTypeName);

    if (schemaType.localizable) {
      data = { ...data };
      const language = this.stateService.getLanguage();
      const { localizable } = schemaType;

      localizable.forEach((localizableField) => {
        const value = data[localizableField] as string;

        if (!data[localizableField]) {
          return;
        }

        const localizations = {
          ...(data['localizations'] as
            | Record<string, Record<string, { language: string; value: string }>>
            | undefined),
        };

        if (!localizations[localizableField]?.[language]) {
          localizations[localizableField] = {
            [language]: {
              language,
              value,
            },
          };
        }

        data['localizations'] = localizations;
      });
    }

    return data;
  }
}
