// import { Logger } from '../../utilities';
import { type DataService } from '../data';
import { Helper, type HelperInterface } from './base';

export class HelperContact extends Helper {
  private static instance: HelperInterface;

  public static getInstance(language: string, dataService: DataService): HelperInterface {
    if (!this.instance) {
      this.instance = new HelperContact(language, dataService);
    }

    return this.instance;
  }

  private constructor(
    protected override language: string,
    protected override dataService: DataService,
  ) {
    super(language, dataService);
  }

  public processData(model: any): void {
    if (!model.name) {
      if (model.firstName && model.lastName) {
        model.name = `${model.firstName} ${model.lastName}`;
      } else {
        if (model.firstName) {
          model.name = `${model.firstName}`;
        } else {
          model.name = `${model.lastName}`;
        }
      }
    }

    // Logger.log(`HelperContact - processData ${model.name}`);
  }
}
