import type { SpeedReport } from '../../types';

const TEST_KB = 1024 * 256;

export class SpeedTester {
  private testSize = TEST_KB;
  private uploadTime?: number;
  private downloadTime?: number;
  private currentSpeedTestCallback?: (payload: SpeedReport | null, error?: Error) => void;

  public clear() {
    if (this.currentSpeedTestCallback !== undefined) {
      this.currentSpeedTestCallback(null, new Error('Speed Test cancelled'));
    }
    this.currentSpeedTestCallback = undefined;
    this.downloadTime = undefined;
    this.uploadTime = undefined;
  }

  public speedTest(socket: WebSocket): Promise<SpeedReport | null> {
    return new Promise<SpeedReport | null>((resolve, reject) => {
      const bytes = this.testSize;
      socket.send('#SPU ' + String(bytes));

      const loops = bytes / 1024;
      const rem = bytes % 1024;
      const data = new Array(1024).join('.');
      for (let i = 0; i < loops; i++) {
        socket.send('#SPB ' + data);
      }

      if (rem) {
        socket.send('#SPB ' + data);
      }

      socket.send('#SPE');

      this.currentSpeedTestCallback = (payload, error) => {
        if (error) {
          reject(error);
        } else {
          resolve(payload);
        }
      };
    });
  }

  private reportSpeedTestEnd() {
    if (this.downloadTime && this.uploadTime && this.currentSpeedTestCallback) {
      const uploadTime = this.uploadTime;
      const downloadTime = this.downloadTime;
      const uploadKbps = Number(((this.testSize * 8) / (uploadTime / 1000) / 1024).toFixed(0));
      const downloadKbps = Number(((this.testSize * 8) / (downloadTime / 1000) / 1024).toFixed(0));

      const cb = this.currentSpeedTestCallback;
      this.currentSpeedTestCallback = undefined;
      this.downloadTime = undefined;
      this.uploadTime = undefined;
      cb({
        downloadKbps,
        downloadTime,
        uploadKbps,
        uploadTime,
      });
    }
  }

  /**
   * Returns if the message was handled by this message handler.
   *
   * @param messageEvent Websocket Message during speedtest
   * @returns
   */
  public handleOnMessage(messageEvent: MessageEvent): boolean {
    if (this.currentSpeedTestCallback !== undefined && messageEvent.data && (messageEvent.data as string).length) {
      const strMsg = messageEvent.data as string;
      if (strMsg.startsWith('#') && strMsg[1] == 'S' && strMsg[2] == 'P') {
        if (strMsg[3] == 'U') {
          this.uploadTime = parseInt(strMsg.slice(4));
        } else if (strMsg[3] == 'D') {
          this.downloadTime = parseInt(strMsg.slice(4));
          this.reportSpeedTestEnd();
        }

        return true;
      }
    }
    return false;
  }
}
