import { s360AxiosClient } from '../utilities/s360AxiosClient';
import type { FetchWelcomeQuestionsParams, FetchWelcomeQuestionsResponse } from '../types/dataIngestion';

export class DataIngestionService {
  /**
   * Fetch welcome questions from the Data Ingestion service.
   *
   * @param collectionName - The name of the collection.
   * @param tenantId - The ID of the tenant.
   * @returns A Promise that resolves to the response from the server.
   */
  public async fetchWelcomeQuestions(params: FetchWelcomeQuestionsParams): Promise<FetchWelcomeQuestionsResponse> {
    const response = await s360AxiosClient.get<FetchWelcomeQuestionsResponse>(
      `/data-ingestion-service/private/v1/welcome_questions`,
      {
        params
      }
    );
    return response.data;
  }
}
