export const V2_SYSADMIN_ROLES = [
  'sysadmin',
  'service_delivery',
  'sro',
  'billing',
  'support',
  'support_management',
  'asr',
] as const;

const v2SysadminRoleSet = new Set<string>(V2_SYSADMIN_ROLES);

export const isV2SysadminRole = (role: string | null | undefined): boolean =>
  typeof role === 'string' && v2SysadminRoleSet.has(role);
