import type { FetchQueryOptions } from '@tanstack/query-core';
import type { TicketNotesQueryData } from '../../types';
import { Logger } from '../logger';

export function getTicketNotesQueryOptions({
  ticketId,
}: {
  ticketId: string;
}) {
  return {
    queryFn: ({ client, queryKey }) => {
      const queryData = client.getQueryData<TicketNotesQueryData>(queryKey);

      Logger.log('getTicketNotesQueryOptions', 'Query invoked', {
        hasData: !!queryData,
        noteCount: queryData?.notes.length ?? 0,
        ticketId,
      });

      return queryData ?? { notes: [], total: 0 };
    },
    queryKey: ['tickets', 'notes', ticketId],
  } satisfies FetchQueryOptions<TicketNotesQueryData>;
}
