  public startKeepAlive() {
    if (this.keepAliveTimer) {
      return;
    }

    this.keepAliveTimer = setInterval(() => {
      void this.keepAlive();
    }, KEEP_ALIVE_INTERVAL_MS);
  }

  public stopKeepAlive() {
    if (!this.keepAliveTimer) {
      return;
    }

    clearInterval(this.keepAliveTimer);
    this.keepAliveTimer = undefined;
  }

