  private getUserQueueIdsForACD(): string[] {
    let queueIds: string[] = [];

    const user = this.stateService.getUser();

    const queues: Queue[] = this.getUserQueues();

    if (user?.allowAcdChanges && user.settings.acd?.queues) {
      queueIds = user.settings.acd.queues.filter((queueId: string) =>
        queues.some((queue: Queue) => queue.queueId === queueId),
      );
    }

    if (queueIds.length === 0) {
      queueIds = queues.map((queue: Queue) => queue.queueId);
    }

    return queueIds;
  }

