  private getUserProfileChannelsForACD() {
    const channels: Record<
      string,
      {
        channelId: string;
        enabled: boolean;
        limit: number;
        multitasking: boolean;
        priority: number;
      }
    > = {};

    this.getUserProfileChannels()?.forEach(
      ({ enabled, expansions, limit, multitasking, priority }: Channel) => {
        channels[expansions.channelId.type] = {
          channelId: expansions.channelId.channelId,
          enabled: enabled,
          limit: limit,
          multitasking: multitasking,
          priority: priority,
        };
      },
    );

    return channels;
  }

  private getStatusForAcdLogin() {
    const defaultAcdLoginStatus = this.stateService.getUser()?.defaultAcdLoginStatus;

    const status =
      defaultAcdLoginStatus === undefined
        ? undefined
        : this.stateService
            .getStatuses()
            ?.find((status: Status) => defaultAcdLoginStatus === status.statusId);

    return {
      status: status ? status.status : -1,
      statusId: status ? status._id : '-1',
    };
  }

