import { type Simplify360Config } from '../types/sdk';

/**
 * Simplify360 configuration per environment, keyed by the NCX base URL
 * (without a trailing slash).
 *
 * Centralizing this here means mobile/web clients no longer need to hardcode
 * the CDN URL / API key mapping, and new environments or rotated configs can
 * be shipped via the SDK instead of a client release.
 */
const PROD_SIMPLIFY360_CONFIG: Simplify360Config = {
  cdnUrl: 'https://d3po7etsbw5eiv.cloudfront.net',
  key: 'Njg5YzhkMzU3N2ZjOTgxYTIyMmNmMzRhfG5leHRjb3Jw',
};

const DEV_SIMPLIFY360_CONFIG: Simplify360Config = {
  cdnUrl: 'https://d23pcq1pxuveon.cloudfront.net',
  key: 'Njc4OTE1YzFmMDY1NTU0OTVhMDliYWFmfGRvZ2Zvb2RkZW1v',
};

const SIMPLIFY360_CONFIG_BY_BASE_URL: Record<string, Simplify360Config> = {
  'https://app.nextiva.io': PROD_SIMPLIFY360_CONFIG,
  'https://demo.dev.nextiva.io': DEV_SIMPLIFY360_CONFIG,
  'https://madrid.dev.nextiva.io': DEV_SIMPLIFY360_CONFIG,
  'https://rc.dev.nextiva.io': DEV_SIMPLIFY360_CONFIG,
};

/**
 * Fallback used for unrecognized (typically new, non-production dev)
 * environments, which share the dogfood Simplify360 config.
 */
const DEFAULT_SIMPLIFY360_CONFIG: Simplify360Config = DEV_SIMPLIFY360_CONFIG;

/**
 * Resolves the Simplify360 config for the given NCX base URL.
 *
 * @param baseURL - The active environment's NCX base URL (with or without a
 * trailing slash).
 * @returns The Simplify360 config for that environment, falling back to the
 * dogfood/dev config for unrecognized environments.
 */
export const resolveSimplify360Config = (baseURL?: string): Simplify360Config => {
  const normalized = (baseURL ?? '').replace(/\/+$/, '');
  return SIMPLIFY360_CONFIG_BY_BASE_URL[normalized] ?? DEFAULT_SIMPLIFY360_CONFIG;
};
