import { EventTypes, type SocketState } from '..';
import { dependencyInjectionContainer } from '../internal';
import { Socket, SupportedFCMEvents, axiosInstance, generateNewId } from '../utilities';
import { type Callback } from './socket';

const extractHostFromBaseUrl = (baseUrl: string) => {
  //let port: string;

  let host: string = baseUrl.slice(Math.max(0, baseUrl.indexOf('//') + 2));
  if (host.includes('/')) {
    host = host.slice(0, Math.max(0, host.indexOf('/')));
  }

  if (host.includes(':')) {
    //port = `${parseInt(host.substring(host.indexOf(':') + 1))}`;
    host = host.slice(0, Math.max(0, host.indexOf(':')));
  }

  //return { host, port };
  return host;
};

const buildSocketURL = (baseUrl: string): string => {
  return `wss://ws-${extractHostFromBaseUrl(baseUrl)}/event-relay/websocket`;
};

const buildUserSubscriptionURL = (tenantId: string, userId: string): string => {
  return `/topic/${tenantId}/user/${userId}`;
};

const buildStatsSubscriptionURL = (tenantId: string, userId: string): string => {
  return `/topic/${tenantId}/stats/${userId}`;
};

interface ConnectOptions {
  callback: Callback;
  onSocketStatusChange?: (status: SocketState) => void;
  subscriptionURL: string;
}

abstract class SocketClient {
  protected socket: Socket | null = null;
  protected eventsService = dependencyInjectionContainer.resolve('eventsService');
  protected stateService = dependencyInjectionContainer.resolve('stateService');

  protected async _connect({ callback, onSocketStatusChange, subscriptionURL }: ConnectOptions) {
    if (this.socket) {
      await this.disconnect();
    }

    const webSocketURL = buildSocketURL(axiosInstance.defaults.baseURL!);

    this.socket = new Socket({
      callback,
      getToken: () => {
        return this.stateService.getToken() ?? '';
      },
      id: generateNewId(),
      onSocketStatusChange,
      subscriptionURL,
      webSocketURL,
    });

    this.socket.connect();
  }

  async disconnect() {
    if (!this.socket) {
      return;
    }

    await this.socket.disconnect();
    this.socket = null;
  }

  isSocketInitiated(): boolean {
    return this.socket?.subscriptionURL ? true : false;
  }
}

export class UserSocketClient extends SocketClient {
  /**
   * Connects to the socket server.
   *
   * @returns A promise that resolves when the connection is established.
   */
  async connect() {
    const logger = dependencyInjectionContainer.resolve('loggerService');
    logger.trace('UserSocketClient - connect');
    this.eventsService.emitExternal(EventTypes.InitConnectUserSocket);
    const tenantId = this.stateService.getTenantId();
    const userId = this.stateService.getUserId();

    if (!tenantId || !userId) {
      this.eventsService.emitExternal(EventTypes.InitConnectUserSocketError);
      throw new Error('SocketClient - tenantId and userId not set');
    }

    return this._connect({
      callback: (message) => {
        const { id, name, offerId, workitemId } = message;

        logger.debug(`UserSocketClient - received message [${name}]`, message);

        if (id && SupportedFCMEvents.includes(name)) {
          // Logger.log(
          //   `FCM Message - supported message received in socket with ID id=${id} name=${name}, Stored in state service. The message will be evaluated and handled accordingly by the React Native client.`,
          // );
          this.stateService.set(id, 'added');
        } else if (workitemId) {
          // Logger.log(
          //   `FCM Message - supported message received in socket with workitemID workitemId=${workitemId} name=${name} Stored in state service. The message will be evaluated and handled accordingly by the React Native client.`,
          // );
          this.stateService.set(`${workitemId}-${name}`, 'added');
        } else if (offerId) {
          // Logger.log(
          //   `FCM Message - supported message received in socket with offerID offerId=${offerId} name=${name} Stored in state service. The message will be evaluated and handled accordingly by the React Native client.`,
          // );
          this.stateService.set(`${offerId}-${name}`, 'added');
        }

        // Duplicate-SDKUserSocketEvent will be used for ncx to remove new socket instance
        this.eventsService.emitExternal('Duplicate-SDKUserSocketEvent', message);
        this.eventsService.emitInternal(message.name, message);
      },
      onSocketStatusChange: (socketState: SocketState) => {
        this.stateService.setUserSocketState(socketState);
        this.eventsService.emitExternal(EventTypes.UserSocketStateChangedNotification, socketState);
      },
      subscriptionURL: buildUserSubscriptionURL(tenantId, userId),
    });
  }
}

