/**
 * Disconnects all socket clients.
 *
 * @returns A promise that resolves when all clients are disconnected.
 */
export const disconnectAll = () => {
  const clients = [
    dependencyInjectionContainer.resolve('userSocketClient'),
    dependencyInjectionContainer.resolve('statisticsSocketClient'),
  ] as const;
  const promises = clients.map((client) => client.disconnect());
  return Promise.all(promises);
};
