import { type InjectionContainer } from '../internal';
import { ExternalEvents, OutboundModes, type StatusType } from '../models';
import { axiosInstance } from '../utilities';
import { type EventsService } from './eventsservice';
import { type LoggerService } from './logger';
import { type StateService } from './state';

export class OutboundModeService {
  private stateService: StateService;
  private logger: LoggerService;
  private eventsService: EventsService;

  constructor({
    eventsService,
    loggerService,
    stateService,
  }: Pick<InjectionContainer, 'eventsService' | 'stateService' | 'loggerService'>) {
    this.stateService = stateService;
    this.logger = loggerService;
    this.eventsService = eventsService;
  }

  async loginToProgressive(payload: LoginPayload): Promise<void> {
    this.logger.trace('ProgressiveService - loginToProgressive');

    await axiosInstance.post('/progressive/api/progressive/login', payload);
    const updatedSession = this.stateService.setOutboundMode(OutboundModes.Progressive);
    if (updatedSession) {
      this.eventsService.emitExternal(
        ExternalEvents.SessionStateUpdateNotification,
        updatedSession
      );
    }
  }

  async loginToProgressiveWithCampaigns(payload: LoginWithCampaignsPayload): Promise<void> {
    this.logger.trace('ProgressiveService - loginToProgressiveWithCampaigns');

    await axiosInstance.post('/progressive/api/progressive/login', payload);
    const updatedSession = this.stateService.setOutboundMode(OutboundModes.Progressive);
    if (updatedSession) {
      this.eventsService.emitExternal(
        ExternalEvents.SessionStateUpdateNotification,
        updatedSession
      );
    }
  }

  async logoutFromProgressive(): Promise<void> {
    this.logger.trace('ProgressiveService - logoutFromProgressive');

    await axiosInstance.post('/progressive/api/progressive/logout');
    const updatedSession = this.stateService.setOutboundMode(OutboundModes.NotLoggedIn);
    if (updatedSession) {
      this.eventsService.emitExternal(
        ExternalEvents.SessionStateUpdateNotification,
        updatedSession
      );
    }
  }

  async loginToPredictive(payload: LoginPayload): Promise<void> {
    this.logger.trace('ProgressiveService - loginToPredictive');

    await axiosInstance.post('/progressive/api/predictive/login', payload);
    const updatedSession = this.stateService.setOutboundMode(OutboundModes.Predictive);
    if (updatedSession) {
      this.eventsService.emitExternal(
        ExternalEvents.SessionStateUpdateNotification,
        updatedSession
      );
    }
  }

  async loginToPredictiveWithCampaigns(payload: LoginWithCampaignsPayload): Promise<void> {
    this.logger.trace('ProgressiveService - loginToPredictiveWithCampaigns');

    await axiosInstance.post('/progressive/api/predictive/login', payload);
    const updatedSession = this.stateService.setOutboundMode(OutboundModes.Predictive);
    if (updatedSession) {
      this.eventsService.emitExternal(
        ExternalEvents.SessionStateUpdateNotification,
        updatedSession
      );
    }
  }

  async logoutFromPredictive(): Promise<void> {
    this.logger.trace('ProgressiveService - logoutFromPredictive');

    await axiosInstance.post('/progressive/api/predictive/logout');
    const updatedSession = this.stateService.setOutboundMode(OutboundModes.NotLoggedIn);
    if (updatedSession) {
      this.eventsService.emitExternal(
        ExternalEvents.SessionStateUpdateNotification,
        updatedSession
      );
    }
  }

  async loginToQuarterback(payload: LoginPayload): Promise<void> {
    this.logger.trace('ProgressiveService - loginToQuarterback');

    await axiosInstance.post('/progressive/api/predictive/quarterback/login', payload);
    const updatedSession = this.stateService.setOutboundMode(OutboundModes.Quarterback);
    if (updatedSession) {
      this.eventsService.emitExternal(
        ExternalEvents.SessionStateUpdateNotification,
        updatedSession
      );
    }
  }

  async loginToQuarterbackWithCampaigns(payload: LoginWithCampaignsPayload): Promise<void> {
    this.logger.trace('ProgressiveService - loginToQuarterbackWithCampaigns');

    await axiosInstance.post('/progressive/api/predictive/quarterback/login', payload);
    const updatedSession = this.stateService.setOutboundMode(OutboundModes.Quarterback);
    if (updatedSession) {
      this.eventsService.emitExternal(
        ExternalEvents.SessionStateUpdateNotification,
        updatedSession
      );
    }
  }

  async logoutFromQuarterback(): Promise<void> {
    this.logger.trace('ProgressiveService - logoutFromQuarterback');

    await axiosInstance.post('/progressive/api/predictive/logout');
    const updatedSession = this.stateService.setOutboundMode(OutboundModes.NotLoggedIn);
    if (updatedSession) {
      this.eventsService.emitExternal(
        ExternalEvents.SessionStateUpdateNotification,
        updatedSession
      );
    }
  }
}

interface LoginPayload {
  campaignId: string;
  status: StatusType;
  statusId: string;
}

interface LoginWithCampaignsPayload {
  campaigns: string[];
  status: StatusType;
  statusId: string;
}
