import { type InjectionContainer } from '../internal';
import { type BaseSchemaTypeClient } from '../models';
import type {
  FetchCampaignsResponseBody,
  CampaignDetails,
  SchemaTypeSearchPayload,
} from '../types';
import { type LoggerService } from './logger';

/**
 * @deprecated CampaignService is deprecated
 */
export class CampaignService {
  private schemaTypeClient: BaseSchemaTypeClient;
  private logger: LoggerService;

  constructor({
    loggerService,
    schemaTypeClient,
  }: Pick<InjectionContainer, 'schemaTypeClient' | 'loggerService'>) {
    this.schemaTypeClient = schemaTypeClient;
    this.logger = loggerService;
  }

  /**
   * @deprecated Use sdk.getSchemaTypeClient().search('campaign')
   */
  async fetchCampaigns(payload?: SchemaTypeSearchPayload): Promise<FetchCampaignsResponseBody> {
    this.logger.warn('CampaignService - fetchCampaigns is deprecated');
    return this.schemaTypeClient.search('campaign', payload);
  }

  /**
   * @deprecated Use sdk.getSchemaTypeClient().retrieve('campaign', { id })
   */
  async fetchCampaign(id: string): Promise<CampaignDetails> {
    this.logger.warn('CampaignService - fetchCampaign is deprecated');
    return this.schemaTypeClient.retrieve('campaign', { id });
  }
}
