import { type WorkitemType, WorkitemTypes } from '../models';
import type {
  EngagementData,
  Message,
  MessageAttachment,
  RealTimeUser,
  Workitem,
  WorkitemOwner,
} from '../types';

type ValidSMSWorkitemTypes =
  | typeof WorkitemTypes.InboundSMS
  | typeof WorkitemTypes.OutboundSMS
  | typeof WorkitemTypes.PredictiveSMS;

export function validateSMSWorkitemType(
  workitemType: WorkitemType,
): workitemType is ValidSMSWorkitemTypes {
  return (
    workitemType === WorkitemTypes.InboundSMS ||
    workitemType === WorkitemTypes.OutboundSMS ||
    workitemType === WorkitemTypes.PredictiveSMS
  );
}

type ValidCallWorkitemTypes =
  | typeof WorkitemTypes.InboundCall
  | typeof WorkitemTypes.OutboundCall
  | typeof WorkitemTypes.InboundExtensionCall
  | typeof WorkitemTypes.OutboundExtensionCall
  | typeof WorkitemTypes.PredictiveCall
  | typeof WorkitemTypes.ProgressiveCall
  | typeof WorkitemTypes.SystemCall;

export function validateCallWorkitemType(
  workitemType: WorkitemType,
): workitemType is ValidCallWorkitemTypes {
  return (
    workitemType === WorkitemTypes.InboundCall ||
    workitemType === WorkitemTypes.OutboundCall ||
    workitemType === WorkitemTypes.InboundExtensionCall ||
    workitemType === WorkitemTypes.OutboundExtensionCall ||
    workitemType === WorkitemTypes.PredictiveCall ||
    workitemType === WorkitemTypes.ProgressiveCall ||
    workitemType === WorkitemTypes.SystemCall
  );
}

interface BuildSignedURLOptions {
  baseUrl: string;
  fileName: string;
  messageId: string;
  token?: string;
}

interface BuildSignedAttachmentURLOptions {
  baseURL: string;
  fileName: string;
  token?: string;
  workitemId: string;
}

export const buildSignedURL = ({ baseUrl, fileName, messageId, token }: BuildSignedURLOptions) => {
  if (token === undefined) {
    throw new Error('Token is required to build signed URL');
  }
  return `${baseUrl}/data/api/messages/${messageId}/signedurl?filename=${encodeURIComponent(
    fileName,
  )}&token=${token}`;
};

const buildSignedAttachmentURL = ({
  baseURL,
  fileName,
  token,
  workitemId,
}: BuildSignedAttachmentURLOptions) => {
  if (token === undefined) {
    throw new Error('Token is required to build signed URL');
  }

  return `${baseURL}/data/api/workitem/${workitemId}/signedurl?filename=${encodeURIComponent(
    fileName,
  )}&token=${token}`;
};

const isMissingSignedURL = (message: Message) => {
  return Boolean(message.filename && !message.signedURL);
};

const isMissingState = (message: Message) => {
  const viewedBy = message.viewedBy?.[message.viewedBy.length - 1];
  const length = message.viewedBy?.length;
  return length !== undefined && length > 0 && message.state !== viewedBy?.status;
};

const isMissingFrom = (message: Message) => {
  return !message.from;
};

const getName = ({ firstName, lastName, name, pseudonym, username }: RealTimeUser) => {
  if (pseudonym) {
    return pseudonym;
  }

  if (name) {
    return name;
  }

  if (firstName || lastName) {
    return [firstName, lastName].filter((name) => name).join(' ');
  }

  return username;
};

/**
 * Resolve the normalized owner (the agent who owned/answered the leg) from the
 * authoritative `ownedById` / `agentUsername` fields the backend sends on every workitem.
 * `ownedBy` is one of `agent` | `queue` | `offer` | `ivr` | `""`; only agent-owned legs
 * (or legs with an agent id/username but an unset `ownedBy`) produce an owner so that
 * queue/ivr ids are never surfaced as an agent.
 */
export const resolveWorkitemOwner = (
  workitem: Workitem,
  users: RealTimeUser[] | undefined,
): WorkitemOwner | undefined => {
  const { agentUsername, ownedBy, ownedById } = workitem;
  const isAgentOwned = ownedBy === 'agent' || (!ownedBy && Boolean(ownedById || agentUsername));

  if (!isAgentOwned || (!ownedById && !agentUsername)) {
    return undefined;
  }

  const user = users?.find(
    ({ userId, username }) =>
      (Boolean(ownedById) && userId === ownedById) ||
      (Boolean(agentUsername) && username === agentUsername),
  );

  return {
    displayName: user ? getName(user) : undefined,
    id: ownedById,
    username: agentUsername,
  };
};

const fixMessage = (message: Message, options: FixWorkItemOptions) => {
  const responseMessage = { ...message };

  if (isMissingSignedURL(message)) {
    responseMessage.signedURL = buildSignedURL({
      ...options,
      fileName: responseMessage.filename,
      messageId: responseMessage.id,
    });
  }

  const viewedBy = responseMessage.viewedBy?.[responseMessage.viewedBy.length - 1];
  if (isMissingState(responseMessage) && viewedBy) {
    responseMessage.state = viewedBy.status;
  }

  const user = options.users?.find(({ userId }) => userId === responseMessage.fromId);

  if (isMissingFrom(responseMessage) && user) {
    responseMessage.from = getName(user);
  }

  return responseMessage;
};

const fixMessages = (messages: Message[], options: FixWorkItemOptions) => {
  const hasToBeFixed = messages.some(
    (message) => isMissingSignedURL(message) || isMissingState(message) || isMissingFrom(message),
  );

  if (hasToBeFixed) {
    return messages.map((message) => {
      return fixMessage(message, options);
    });
  }

  return messages;
};

interface FixAttachmentOptions {
  baseURL: string;
  token?: string;
  workitemId: string;
}

/**
 * @deprecated Use sdk.getWorkitemService().buildSignedURL()
 */
const fixAttachment = (
  attachment: MessageAttachment,
  { baseURL, token, workitemId }: FixAttachmentOptions,
): MessageAttachment => {
  return {
    ...attachment,
    signedURL: buildSignedAttachmentURL({
      baseURL,
      fileName: attachment.title,
      token,
      workitemId,
    }),
  };
};

/**
 * @deprecated Use sdk.getWorkitemService().buildSignedURL()
 */
export const fixEngagementDataItem = (
  engagementData: EngagementData,
  options: FixAttachmentOptions,
) => {
  if (!engagementData.attachments) {
    return engagementData;
  }

  return {
    ...engagementData,
    attachments: engagementData.attachments.map((attachment) => fixAttachment(attachment, options)),
  };
};

/**
 * @deprecated Use sdk.getWorkitemService().buildSignedURL()
 */
export const fixEngagementData = (
  engagementData: EngagementData[],
  options: FixAttachmentOptions,
): EngagementData[] => {
  return engagementData.map((item) => {
    return fixEngagementDataItem(item, options);
  });
};

interface FixWorkItemOptions {
  baseUrl: string;
  token?: string;
  users: RealTimeUser[] | undefined;
}

export const fixWorkitem = (workitem: Workitem, options: FixWorkItemOptions): Workitem => {
  const newWorkitem: Workitem = { ...workitem };

  newWorkitem.owner = resolveWorkitemOwner(workitem, options.users);

  if (workitem.smsMessages && workitem.smsMessages.length > 0) {
    newWorkitem.smsMessages = fixMessages(workitem.smsMessages, options);
  } else if (workitem.chatMessages && workitem.chatMessages.length > 0) {
    newWorkitem.chatMessages = fixMessages(workitem.chatMessages, options);
  }

  if (newWorkitem.engagementData) {
    newWorkitem.engagementData = fixEngagementData(newWorkitem.engagementData, {
      baseURL: options.baseUrl,
      token: options.token,
      workitemId: workitem.workitemId,
    });
  }

  if (newWorkitem.currentEngagementData?.attachments) {
    newWorkitem.currentEngagementData.attachments =
      newWorkitem.currentEngagementData.attachments.map((attachment) =>
        fixAttachment(attachment, {
          baseURL: options.baseUrl,
          token: options.token,
          workitemId: workitem.workitemId,
        }),
      );
  }

  if (newWorkitem.conversationMessage) {
    newWorkitem.conversationMessage = fixMessage(newWorkitem.conversationMessage, options);
  }

  if (newWorkitem.currentChatMessage) {
    newWorkitem.currentChatMessage = fixMessage(newWorkitem.currentChatMessage, options);
  }

  if (newWorkitem.currentSMSMessage?.attachments) {
    newWorkitem.currentSMSMessage.attachments = fixAttachment(
      newWorkitem.currentSMSMessage.attachments,
      {
        baseURL: options.baseUrl,
        token: options.token,
        workitemId: workitem.workitemId,
      },
    );
  }

  return newWorkitem;
};

export const DefaultMergeProperties = {
  Default: ['workitemId', 'type', 'createdAt', 'ownedBy', 'to', 'from', 'type'],
  InboundCall: [
    'workitemId',
    'type',
    'createdAt',
    'ownedBy',
    'to',
    'from',
    'type',
    'voicemailFile',
  ],
  InboundSMS: ['workitemId', 'type', 'createdAt', 'ownedBy', 'to', 'from', 'type'],
  OutboundSMS: ['workitemId', 'type', 'createdAt', 'ownedBy', 'to', 'from', 'type'],
};

export type HistoryTypeProperties = Record<string, string[]>;
