import { type LoggerService } from '../../services/logger';
import type { ReplySocialMessagePayload, UploadSocialAttachmentsResponse } from '../../types';
import { axiosInstance } from '../../utilities';
import { type InjectionContainer } from '../dependencyInjectionContainer';
import type { BaseUploadSocialAttachmentsPayload } from '../types';

export class BaseSocialService {
  protected logger: LoggerService;
  constructor({ loggerService }: Pick<InjectionContainer, 'loggerService'>) {
    this.logger = loggerService;
  }

  async reply(payload: ReplySocialMessagePayload): Promise<void> {
    this.logger.trace('SocialService - reply');

    // POST /reply/api/action
    // Returns empty response
    await axiosInstance.post('/reply/api/action', payload);

    return;
  }

  async uploadAttachments({
    files,
    workitemId,
  }: BaseUploadSocialAttachmentsPayload): Promise<UploadSocialAttachmentsResponse> {
    this.logger.trace('SocialService - uploadAttachments');

    const formData: FormData = new FormData();
    files.forEach((file, index) => {
      formData.append(`file${index + 1}`, file);
    });

    // POST /reply/api/action/${workitemId}/attachments
    const response = await axiosInstance.post<UploadSocialAttachmentsResponse>(
      `/reply/api/action/${workitemId}/attachments`,
      formData,
      {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      },
    );

    return response.data;
  }
}
